        /**
         * a semantic event which indicates that a component-defined action occurred.
         *
         * This high-level event is generated by a component (such as a Button) when the component-specific action occurs (such as being pressed). The event is
         * passed to every {@link XActionListener} object that registered to receive such events using the component's `addActionListener` method.
         *
         * The object that implements the {@link XActionListener} interface gets this {@link ActionEvent} when the event occurs. The listener is therefore spared
         * the details of processing individual mouse movements and mouse clicks, and can instead process a "meaningful" (semantic) event like "button pressed".
         */
        interface ActionEvent extends lang.EventObject {
            /** contains the command string associated with this action. */
            ActionCommand: string;
        }

        /** adjustment event emitted by adjustable objects. */
        interface AdjustmentEvent extends lang.EventObject {
            /** contains the type of the adjustment event. */
            Type: AdjustmentType;

            /** contains the current value in the adjustment event. */
            Value: number;
        }

        /**
         * is the default control used for an {@link AnimatedImagesControlModel} , displayed a series of images.
         * @since OOo 3.4
         */
        interface AnimatedImagesControl extends UnoControl, XAnimation {}

        /**
         * describes the model for a control displaying a series of images
         * @since OOo 3.4
         */
        interface AnimatedImagesControlModel extends UnoControlModel, XAnimatedImages {}

        /** contains information about a device. */
        interface DeviceInfo {
            /** contains the color-depth of the device. */
            BitsPerPixel: number;

            /** contains the inset from the bottom. */
            BottomInset: number;

            /**
             * specifies special operations which are possible on the device.
             * @see DeviceCapability
             */
            Capabilities: number;

            /** contains the height of the device in pixels. */
            Height: number;

            /** contains the inset from the left. */
            LeftInset: number;

            /** contains the X-axis resolution of the device in pixel/meter. */
            PixelPerMeterX: number;

            /** contains the Y-axis resolution of the device in pixel/meter. */
            PixelPerMeterY: number;

            /** contains the inset from the right. */
            RightInset: number;

            /** contains the inset from the top. */
            TopInset: number;

            /** contains the width of the device in pixels. */
            Width: number;
        }

        /** Specifies a provider for dialogs implementing the {@link com.sun.star.awt.XDialog} interface. */
        interface DialogProvider extends XDialogProvider {
            createWithModel(Model: frame.XModel): void;
            createWithModelAndScripting(
                Model: frame.XModel,
                InStream: io.XInputStream,
                DialogLib: container.XNameContainer,
                ScriptListener: script.XScriptListener,
            ): void;
        }

        /** data returned by docking handler */
        interface DockingData {
            /** specifies that the window should be floating (TRUE) or docked (FALSE) */
            bFloating: boolean;

            /** specifies the position and size where the window would be placed if the user releases the mouse */
            TrackingRectangle: Rectangle;
        }

        /** specifies a docking event. */
        interface DockingEvent extends lang.EventObject {
            /**
             * specifies if the docking procedure is interactive which means that the user is currently dragging the window to a new position if this member is
             * `FALSE` the window will be docked or undocked immediately using the returned tracking rectangle
             */
            bInteractive: boolean;

            /** specifies if the layout should be adjusted immediately */
            bLiveMode: boolean;

            /** specifies the current mouse position in frame coordinates */
            MousePos: Point;

            /** specifies the current tracking rectangle */
            TrackingRectangle: Rectangle;
        }

        /** specifies an end docking event. */
        interface EndDockingEvent extends lang.EventObject {
            /** specifies that the docking procedure was canceled */
            bCancelled: boolean;

            /** specifies if the window is now floating `TRUE` or docked `FALSE` */
            bFloating: boolean;

            /** specifies the new bounding rectangle of the window */
            WindowRectangle: Rectangle;
        }

        /** specifies an end pop-up mode event. */
        interface EndPopupModeEvent extends lang.EventObject {
            /**
             * specifies how the pop-up mode was ended `TRUE` means the window should be teared-off and positioned at FloatingPosition `FALSE` means the window was
             * closed
             */
            bTearoff: boolean;

            /** specifies the new position of the floating window in frame coordinates if bTearoff is `TRUE` */
            FloatingPosition: Point;
        }

        /**
         * specifies an event from the mouse.
         * @see MouseEvent
         * @since OOo 2.0
         */
        interface EnhancedMouseEvent extends MouseEvent {
            /** contains the object on the location of the mouse. */
            Target: uno.XInterface;
        }

        /**
         * specifies a keyboard focus event.
         *
         * There are two levels of focus change events: permanent and temporary. Permanent focus change events occur when focus is directly moved from one
         * component to another, such as through calls to requestFocus() or as the user uses the Tab key to traverse components. Temporary focus change events
         * occur when focus is gained or lost for a component as the indirect result of another operation, such as window deactivation or a scrollbar drag. In
         * this case, the original focus state will automatically be restored once that operation is finished, or for the case of window deactivation, when the
         * window is reactivated. Both permanent and temporary focus events are delivered using the FOCUS_GAINED and FOCUS_LOST event ids; the levels may be
         * distinguished in the event using the isTemporary() method.
         */
        interface FocusEvent extends lang.EventObject {
            /**
             * specifies the reason for the focus change as an arithmetic-or combination of {@link FocusChangeReason} .
             * @see FocusChangeReason
             */
            FocusFlags: number;

            /** contains the window which gets the focus on a lose focus event. */
            NextFocus: uno.XInterface;

            /** specifies if this focus change event is a temporary change. */
            Temporary: boolean;
        }

        /**
         * describes the characteristics of a font.
         *
         * For example, this can be used to select a font.
         */
        interface FontDescriptor {
            /**
             * specifies the character width.
             *
             * Depending on the specified width, a font that supports this width may be selected.
             *
             * The value is expressed as a percentage.
             */
            CharacterWidth: number;

            /**
             * specifies the character set which is supported by the font.
             *
             * Use one value out of the constant group {@link com.sun.star.awt.CharSet} .
             */
            CharSet: number;

            /**
             * specifies the general style of the font.
             *
             * Use one value out of the constant group {@link com.sun.star.awt.FontFamily} .
             */
            Family: number;

            /** specifies the height of the font in the measure of the destination. */
            Height: number;

            /** For requesting, it specifies if there is a kerning table available. For selecting, it specifies if the kerning table is to be used. */
            Kerning: boolean;

            /** specifies the exact name of the font. */
            Name: string;

            /**
             * specifies the rotation of the font.
             *
             * The unit of measure is degrees; 0 is the baseline.
             */
            Orientation: number;

            /**
             * specifies the pitch of the font.
             *
             * Use one value out of the constant group {@link com.sun.star.awt.FontPitch} .
             */
            Pitch: number;

            /** specifies the slant of the font. */
            Slant: FontSlant;

            /**
             * specifies the kind of strikeout.
             *
             * Use one value out of the constant group {@link com.sun.star.awt.FontStrikeout} .
             */
            Strikeout: number;

            /** specifies the style name of the font. */
            StyleName: string;

            /**
             * specifies the technology of the font representation.
             *
             * One or more values out of the constant group {@link com.sun.star.awt.FontType} can be combined by an arithmetical or-operation.
             */
            Type: number;

            /**
             * specifies the kind of underlining.
             *
             * Use one value out of the constant group {@link com.sun.star.awt.FontUnderline} .
             */
            Underline: number;

            /**
             * specifies the thickness of the line.
             *
             * Depending on the specified weight, a font that supports this thickness may be selected.
             *
             * The value is expressed as a percentage.
             */
            Weight: number;

            /** specifies the width of the font in the measure of the destination. */
            Width: number;

            /**
             * specifies if only words get underlined.
             *
             * `TRUE` means that only non-space characters get underlined, `FALSE` means that the spacing also gets underlined.
             *
             * This property is only valid if the property {@link com.sun.star.awt.FontDescriptor.Underline} is not {@link FontUnderline.NONE} .
             */
            WordLineMode: boolean;
        }

        /**
         * Describes a gradient between two colors. Many aspects of the gradient are undefined, like the algorithm and color space to use to interpolate between
         * the colors and what "intensity" means.
         */
        interface Gradient {
            /** angle of the gradient in 1/10 degree. */
            Angle: number;

            /** per cent of the total width where just the start color is used. */
            Border: number;

            /** specifies the color at the end point of the gradient. */
            EndColor: util.Color;

            /** specifies the intensity at the end point of the gradient. */
            EndIntensity: number;

            /** specifies the color at the start point of the gradient. */
            StartColor: util.Color;

            /** Specifies the intensity at the start point of the gradient. What that means is undefined. */
            StartIntensity: number;

            /** Specifies the number of steps of change color. What that means is undefined. */
            StepCount: number;

            /** specifies the style of the gradient. */
            Style: GradientStyle;

            /**
             * Specifies the X-coordinate, where the gradient begins, whatever that means. Possibly means the **center** of the ELLIPTICAL, SQUARE and RECT style
             * gradients?
             */
            XOffset: number;

            /** Specifies the Y-coordinate, where the gradient begins. See previous field. */
            YOffset: number;
        }

        /**
         * the root event class for all component-level input events.
         *
         * Input events are delivered to listeners before they are processed normally by the source where they originated.
         * @see WindowEvent
         */
        interface InputEvent extends lang.EventObject {
            /**
             * contains the modifier keys which were pressed while the event occurred.
             *
             * Zero or more constants from the {@link com.sun.star.awt.KeyModifier} group.
             */
            Modifiers: number;
        }

        /** specifies an event occurred to an item of a menu, a list box etc. */
        interface ItemEvent extends lang.EventObject {
            /** specifies which item is newly highlighted. */
            Highlighted: number;

            /** specifies the id of the item. */
            ItemId: number;

            /** specifies which item is newly selected. */
            Selected: number;
        }

        /** is the event broadcasted by a XListItems implementation for changes in its item list. */
        interface ItemListEvent extends lang.EventObject {
            /**
             * the URL of the image of the item
             *
             * If the event being notified did not touch the image of an item, this member is empty. For instance, upon invocation of {@link XItemList.setItemText()}
             * , only `ItemText` will be set, and `ItemImageURL` will be empty.
             */
            ItemImageURL: com.sun.star.beans.Optional<string>;

            /**
             * specifies the position of the item which is affected by the event
             *
             * In case the event is not related to a single item, but to the complete list, the value of this member is undefined.
             */
            ItemPosition: number;

            /**
             * the text of the item.
             *
             * If the event being notified did not touch the text of an item, this member is empty. For instance, upon invocation of {@link XItemList.setItemImage()}
             * , only `ItemImageURL` will be set, and `ItemText` will be empty.
             */
            ItemText: com.sun.star.beans.Optional<string>;
        }

        /**
         * specifies a key event.
         * @see InputEvent
         */
        interface KeyEvent extends InputEvent {
            /** contains the Unicode character generated by this event or 0. */
            KeyChar: string;

            /**
             * contains the integer code representing the key of the event.
             *
             * This is a constant from the constant group {@link Key} .
             */
            KeyCode: number;

            /**
             * contains the function type of the key event.
             *
             * This is a constant from the constant group {@link KeyFunction} .
             */
            KeyFunc: number;
        }

        /**
         * Describes a key stroke for hotkeys etc.
         * @since OOo 1.1.2
         */
        interface KeyStroke {
            /** contains the Unicode character generated by this event or 0. */
            KeyChar: string;

            /**
             * contains the integer code representing the key of the event.
             *
             * This is a constant from the constant group {@link com.sun.star.awt.Key} .
             */
            KeyCode: number;

            /**
             * contains the function type of the key event.
             *
             * This is a constant from the constant group {@link com.sun.star.awt.KeyFunction} .
             */
            KeyFunc: number;

            /**
             * contains the modifier keys which were pressed while the event occurred.
             *
             * Zero or more constants from the group {@link com.sun.star.awt.KeyModifier} .
             */
            Modifiers: number;
        }

        /** specifies a menu event. */
        interface MenuEvent extends lang.EventObject {
            /** contains the item ID. */
            MenuId: number;
        }

        /**
         * specifies an event from the mouse.
         *
         * This event is also used for pop-up menu requests on objects. See {@link PopupTrigger} for details.
         * @see XMouseListener
         * @see XMouseMotionListener
         * @see InputEvent
         */
        interface MouseEvent extends InputEvent {
            /**
             * contains the pressed mouse buttons.
             *
             * Zero ore more constants from the {@link com.sun.star.awt.MouseButton} group.
             */
            Buttons: number;

            /** contains the number of mouse clicks associated with event. */
            ClickCount: number;

            /**
             * specifies if this event is a pop-up menu trigger event.
             *
             * If this member is `TRUE` , the event describes a request for a pop-up menu, also known as context menu, on an object.
             *
             * In this case, X and Y describe the position where the request was issued. If those members are `-1` , then the request was issued using the keyboard,
             * by pressing the operating-system dependent key combination for this purpose.
             * @see XMouseListener.mousePressed
             */
            PopupTrigger: boolean;

            /** contains the x coordinate location of the mouse. */
            X: number;

            /** contains the y coordinate location of the mouse. */
            Y: number;
        }

        /**
         * specifies the paint event for a component.
         *
         * This event is a special type which is used to ensure that paint/update method calls are serialized along with the other events delivered from the
         * event queue.
         * @see WindowEvent
         */
        interface PaintEvent extends lang.EventObject {
            /**
             * contains the number of paint events that follows this event if it is a multiple {@link PaintEvent} . You can collect the {@link PaintEvent} until
             * Count is zero.
             */
            Count: number;

            /** contains the rectangle area which needs to be repainted. */
            UpdateRect: Rectangle;
        }

        /** specifies a 2-dimensional point using the Cartesian coordinate system. */
        interface Point {
            /** specifies the x-coordinate. */
            X: number;

            /** specifies the y-coordinate. */
            Y: number;
        }

        /** specifies a rectangular area by position and size. */
        interface Rectangle {
            /** specifies the height. */
            Height: number;

            /** specifies the width. */
            Width: number;

            /** specifies the x-coordinate. */
            X: number;

            /** specifies the y-coordinate. */
            Y: number;
        }

        interface RoadmapItem {
            /** determines whether a control is enabled or disabled. */
            Enabled: boolean;

            /**
             * The ID uniquely identifies the roadmap item. When the {@link RoadmapItem} is inserted into the Roadmap via "insertByIndex" the default value of the ID
             * is the first available absolute digit that has not yet been assigned to other existing RoadmapItems.
             */
            ID: number;

            /**
             * When "Interactive" is true the {@link RoadmapItem} supports a certain "HyperLabel; functionality": Moving the mouse pointer over the {@link
             * RoadmapItem} will change it to a Refhand and underline the Label for the time the mouse pointer resides over the {@link RoadmapItem} . Clicking with
             * mouse pointer will then notify the Roadmap Container. The property Interactive" is readonly because it is adapted from the container of the {@link
             * RoadmapItem} .
             */
            Interactive: boolean;

            /** The Label of the {@link RoadmapItem} does not include its Prefix that is automatically set after the following algorithm: (Index + 1) + ". " + Label */
            Label: string;
        }

        /** specifies a numerical range. */
        interface Selection {
            /** specifies the upper limit of the range. */
            Max: number;

            /** specifies the lower limit of the range. */
            Min: number;
        }

        /** describes the general metrics of a certain font. */
        interface SimpleFontMetric {
            /**
             * specifies the portion of a lower case character that rises above the height of the character "x" of the font.
             *
             * For example, the letters "b", "d", "h", "k" and "l" have an ascent unequal to 0.
             *
             * The ascent is measured in pixels, thus the font metric is device dependent.
             */
            Ascent: number;

            /**
             * specifies the portion of a letter falling below the baseline.
             *
             * For example, the letters "g", "p", and "y" have a descent unequal to 0.
             *
             * The descent is measured in pixels, thus the font metric is device dependent.
             */
            Descent: number;

            /** specifies the code of the first printable character in the font. */
            FirstChar: string;

            /** specifies the code of the last printable character in the font. */
            LastChar: string;

            /**
             * specifies the vertical space between lines of this font; it is also called internal line spacing.
             *
             * The leading is measured in pixels, thus the font metric is device dependent.
             */
            Leading: number;

            /**
             * specifies the slant of the characters (italic).
             *
             * The slant is measured in degrees from 0 to 359.
             */
            Slant: number;
        }

        /** specifies the 2-dimensional size of an area using width and height. */
        interface Size {
            /** specifies the height. */
            Height: number;

            /** specifies the width. */
            Width: number;
        }

