        namespace grid {
            /**
             * If you do not want to implement the {@link XGridColumnModel} yourself, use this service.
             * @since OOo 3.3
             */
            type DefaultGridColumnModel = XGridColumnModel;

            /**
             * If you do not want to implement the {@link XGridDataModel} yourself, use this service.
             *
             * The `DefaultGridDataModel` implementation is a dumb container of tabular data. You can add and remove rows, modify cell values, and the like.
             *
             * The implementation will implicitly increase its column count if you add a row which has more values than the current column count.
             * @since OOo 3.3
             */
            type DefaultGridDataModel = XMutableGridDataModel;

            /**
             * Represents a column as used by the {@link DefaultGridColumnModel}
             * @since OOo 3.3
             */
            type GridColumn = XGridColumn;

            /**
             * Exception is thrown to indicate that set data is invalid, e.g. type of data is unknown or data count doesn't match with column count.
             * @since OOo 3.3
             */
            type GridInvalidDataException = uno.RuntimeException;

            /**
             * Exception is thrown when data or column model isn't set.
             * @since OOo 3.3
             */
            type GridInvalidModelException = uno.RuntimeException;

            /**
             * An event used by a {@link XGridColumn} to notify changes in the column.
             * @since OOo 3.3
             */
            interface GridColumnEvent extends lang.EventObject {
                /** Contains the name of the attributes whose value changed. */
                AttributeName: string;

                /** Contains the index of the changed column */
                ColumnIndex: number;

                /** Contains the new value */
                NewValue: any;

                /** Contains the old value */
                OldValue: any;
            }

            /**
             * used to notify changes in the data represented by an {@link XMutableGridDataModel} .
             *
             * Effectively, a `GridDataEvent` denotes a continuous two-dimensional cell range within a grid's data model, which is affected by a certain change.
             * @see XMutableGridDataModel
             * @see XGridDataListener
             * @since OOo 3.3
             */
            interface GridDataEvent extends lang.EventObject {
                /**
                 * denotes the first column affected by a change.
                 *
                 * If `FirstColumn` is -1, the listener should assume that all rows of a grid's data model are affected.
                 */
                FirstColumn: number;

                /**
                 * denotes the first row affected by a change.
                 *
                 * If `FirstRow` is -1, the listener should assume that all rows of a grid's data model are affected.
                 */
                FirstRow: number;

                /** denotes the last column affected by a change */
                LastColumn: number;

                /** denotes the last row affected by a change */
                LastRow: number;
            }

            /**
             * An event used by a {@link XGridControl} to notify changes in its row selection.
             * @see XGridRowSelection
             * @see XGridSelectionListener
             */
            interface GridSelectionEvent extends lang.EventObject {
                /** denotes the indexes of the columns being selected at the time the event was fired. */
                SelectedColumnIndexes: SafeArray<number>;

                /** denotes the indexes of the rows being selected at the time the event was fired. */
                SelectedRowIndexes: SafeArray<number>;
            }

            /**
             * provides a default implementation of a {@link XSortableGridData} .
             *
             * This service must be created with a secondary grid data model, which all actual data requests are delegated to. But before providing this data to the
             * service's own clients, it is sorted, according to the sort order defined via the `XSortableGridData` interface.
             *
             * The service implementation is able to compare the default scalar types, plus strings.
             *
             * For determining the data type of a column which the data should be sorted by, the first non- `VOID` data encountered in this column is taken into
             * account. Further read requests to this column will assume that all non- `VOID` data is of the same type.
             *
             * Consequently, you cannot use this service with data sets containing heterogeneous data in a given column.
             *
             * All requests made via the {@link XMutableGridDataModel} are delegated to the `XMutableGridDataModel` instance passed in the service constructor.
             *
             * Note that changing the data might result in the sort order being destroyed. If you want to ensure that the data represented by the model is still
             * sorted after your modifications, you should call {@link XSortableGridData.sortByColumn()} , again.
             */
            interface SortableGridDataModel extends XSortableMutableGridDataModel {
                /**
                 * creates a new instance of the `SortableGridDataModel`
                 *
                 * For string comparison, a default {@link com.sun.star.i18n.Collator} , based on the system's locale, will be used.
                 * @param DelegatorModel the data model to which read requests are delegated.
                 * @throws com::sun::star::lang::IllegalArgumentException if the given `DelegatorModel` is `NULL`
                 */
                create(DelegatorModel: XMutableGridDataModel): void;

                /**
                 * creates a new instance of the ScortableDefaultGridDataModel, passing a collator to be used for string comparison.
                 * @param DelegatorModel is the data model to which read requests are delegated
                 * @param Collator is the collator to be used for string comparison
                 * @throws com::sun::star::lang::IllegalArgumentException if the given `DelegatorModel` is `NULL`
                 */
                createWithCollator(DelegatorModel: XMutableGridDataModel, Collator: i18n.XCollator): void;
            }

            /**
             * A control that displays a set of tabular data.
             *
             * **The Column Model**
             *
             * The horizontal structure of the grid is defined by the {@link XGridColumnModel} implemented in {@link DefaultGridColumnModel} The {@link XGridColumn}
             * implemented in {@link GridColumn} describes the properties and behavior of a single column. Use the {@link XGridColumnModel.addColumn()} to add a
             * column to the column model.
             *
             * **The Data Model**
             *
             * All row data are stored in the {@link XGridDataModel} . Use the {@link DefaultGridDataModel} to add XGridDataModel::addRow() or remove
             * XGridDataModel::removeRow() rows.
             *
             * The column and data model must be set at the {@link UnoControlGridModel.ColumnModel} and {@link UnoControlGridModel.GridDataModel} properties.
             *
             * **{@link Selection}**
             *
             * If you are interested in knowing when the selection changes implement a {@link XGridSelectionListener} and add the instance with the method {@link
             * XGridRowSelection.addSelectionListener()} . You than will be notified for any selection change.
             * @since OOo 3.3
             */
            interface UnoControlGrid extends UnoControl, XGridControl, XGridRowSelection {}

            /**
             * specifies the standard model of a {@link UnoControlGrid} control.
             * @since OOo 3.3
             */
            interface UnoControlGridModel extends UnoControlModel {
                /**
                 * specifies the color to be used when drawing the background of selected cells, while the control has the focus.
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                ActiveSelectionBackgroundColor: util.Color;

                /**
                 * specifies the color to be used when drawing the text of selected cells, while the control has the focus.
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                ActiveSelectionTextColor: util.Color;

                /**
                 * specifies the height of the column header row, if applicable.
                 *
                 * The height is specified in application font units - see {@link com.sun.star.util.MeasureUnit} .
                 *
                 * The value given here is ignored if {@link ShowColumnHeader} is `FALSE` .
                 *
                 * If the property is `VOID` , the grid control shall automatically determine a height which conveniently allows, according to the used font, to display
                 * one line of text.
                 */
                ColumnHeaderHeight: number;

                /**
                 * Specifies the {@link XGridColumnModel} that is providing the column structure.
                 *
                 * You can implement your own instance of {@link XGridColumnModel} or use the {@link DefaultGridColumnModel} .
                 *
                 * The column model is in the ownership of the grid model: When you set a new column model, or dispose the grid model, then the (old) column model is
                 * disposed, too.
                 *
                 * The default for this property is an empty instance of the {@link DefaultGridColumnModel} .
                 */
                ColumnModel: XGridColumnModel;

                /** specifies the font attributes of the text in the control. */
                FontDescriptor: FontDescriptor;

                /** specifies the {@link com.sun.star.text.FontEmphasis} value of the text in the control. */
                FontEmphasisMark: number;

                /** specifies the {@link com.sun.star.text.FontRelief} value of the text in the control. */
                FontRelief: number;

                /**
                 * Specifies the {@link XGridDataModel} that is providing the hierarchical data.
                 *
                 * You can implement your own instance of {@link XGridDataModel} or use the {@link DefaultGridDataModel} .
                 *
                 * The data model is in the ownership of the grid model: When you set a new data model, or dispose the grid model, then the (old) data model is disposed,
                 * too.
                 *
                 * The default for this property is an empty instance of the {@link DefaultGridDataModel} .
                 */
                GridDataModel: XGridDataModel;

                /**
                 * specifies the color to be used when drawing lines between cells
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 * @see UseGridLines
                 */
                GridLineColor: util.Color;

                /**
                 * specifies the color to be used when drawing the background of row or column headers
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                HeaderBackgroundColor: util.Color;

                /**
                 * specifies the color to be used when drawing the text within row or column headers
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                HeaderTextColor: util.Color;

                /** specifies the help text of the control. */
                HelpText: string;

                /** specifies the help URL of the control. */
                HelpURL: string;

                /**
                 * Specifies the vertical scrollbar mode.
                 *
                 * The default value is `FALSE`
                 */
                HScroll: boolean;

                /**
                 * specifies the color to be used when drawing the background of selected cells, while the control does not have the focus.
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                InactiveSelectionBackgroundColor: util.Color;

                /**
                 * specifies the color to be used when drawing the text of selected cells, while the control does not have the focus.
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                InactiveSelectionTextColor: util.Color;

                /**
                 * specifies the colors to be used as background for data rows.
                 *
                 * If this sequence is non-empty, the data rows will be rendered with alternating background colors: Assuming the sequence has `n` elements, each row
                 * will use the background color as specified by its number's remainder modulo `n` .
                 *
                 * If this sequence is empty, all rows will use the same background color as the control as whole.
                 *
                 * If this property has a value of `VOID` , rows will be painted in alternating background colors, every second row having a background color derived
                 * from the control's selection color.
                 */
                RowBackgroundColors: SafeArray<util.Color>;

                /**
                 * specifies the width of the row header column, if applicable.
                 *
                 * The width is specified in application font units - see {@link com.sun.star.util.MeasureUnit} .
                 *
                 * The value given here is ignored if {@link ShowRowHeader} is `FALSE` .
                 */
                RowHeaderWidth: number;

                /**
                 * Specifies the height of rows in the grid control.
                 *
                 * The height is specified in application font units - see {@link com.sun.star.util.MeasureUnit} .
                 */
                RowHeight: number;

                /**
                 * Specifies the selection mode that is enabled for this grid control.
                 *
                 * The default value is com::sun::star::view::SelectionType::SINGLE
                 */
                SelectionModel: view.SelectionType;

                /**
                 * Specifies whether the grid control should display a title row.
                 *
                 * The default value is `TRUE`
                 */
                ShowColumnHeader: boolean;

                /**
                 * Specifies whether the grid control should display a special header column.
                 *
                 * The default value is `FALSE`
                 */
                ShowRowHeader: boolean;

                /** Specifies that the control can be reached with the TAB key. */
                Tabstop: boolean;

                /**
                 * specifies the color to be used when drawing cell texts
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                TextColor: util.Color;

                /**
                 * specifies the color to be used when drawing text lines (underlining and strikethrough)
                 *
                 * If this property has a value of `VOID` , the grid control renderer will use some default color, depending on the control's style settings.
                 */
                TextLineColor: util.Color;

                /**
                 * controls whether or not to paint horizontal and vertical lines between the grid cells.
                 * @see GridLineColor
                 */
                UseGridLines: boolean;

                /** specifies the vertical alignment of the content in the control. */
                VerticalAlign: style.VerticalAlignment;

                /**
                 * Specifies the horizontal scrollbar mode.
                 *
                 * The default value is `FALSE`
                 */
                VScroll: boolean;
            }

            /**
             * The {@link XGridColumn} defines the properties and behavior of a column in a grid control.
             * @since OOo 3.3
             */
            interface XGridColumn extends lang.XComponent, util.XCloneable {
                /**
                 * Adds a listener for the {@link GridColumnEvent} posted after the grid changes.
                 * @param Listener the listener to add.
                 */
                addGridColumnListener(Listener: XGridColumnListener): void;

                /** specifies the current width of the column. */
                ColumnWidth: number;

                /**
                 * denotes the index of the data column which should be used to fetch this grid column's data
                 *
                 * A grid control has a column model and a data model, both containing a possibly different number of columns. The `DataColumnIndex` attribute defines
                 * the index of the column within the data model, which should be used to retrieve actual data.
                 *
                 * Using this, you can do runtime changes to the column model, i.e. insertion and removal of columns, without necessarily needing to adjust the data
                 * model, too.
                 *
                 * If `DataColumnIndex` is negative, the it will be ignored, then the column's index within its column model, as determined by the {@link Index}
                 * attribute, will be used.
                 */
                DataColumnIndex: number;

                /**
                 * specifies the flexibility of the column when it is automatically resized due to the grid control as a whole being resized.
                 *
                 * Specify `0` here if you do not want the column to be resized automatically.
                 *
                 * If a column has a flexibility greater than 0, it is set in relationship to the flexibility of all other such columns, and the respective widths of the
                 * columns are changed in the same relationship.
                 *
                 * Note that a column's flexibility is ignored if its {@link Resizeable} attribute is `FALSE` .
                 *
                 * A column's flexibility cannot be negative, attempts to set a negative value will raise an exception.
                 */
                Flexibility: number;

                /**
                 * is the help text associated with the column.
                 *
                 * A grid control will usually display a column's help text as tooltip.
                 */
                HelpText: string;

                /** Specifies the horizontal alignment of the content in the control. */
                HorizontalAlign: style.HorizontalAlignment;

                /**
                 * specifies an identifier of the column
                 *
                 * This identifier will not be evaluated by the grid control, or its model. It is merely for clients to identify particular columns.
                 */
                Identifier: any;

                /**
                 * denotes the index of the column within the grid column model it belongs to
                 *
                 * If the column is not yet part of a column model, `Index` is -1.
                 */
                Index: number;

                /** specifies the maximal width the column can have. */
                MaxWidth: number;

                /** specifies the minimal width the column can have. */
                MinWidth: number;

                /**
                 * Removes a listener previously added with addColumnListener().
                 * @param Listener the listener to remove.
                 */
                removeGridColumnListener(Listener: XGridColumnListener): void;

                /**
                 * controls whether or not the column's width is fixed or not.
                 *
                 * If this is `TRUE` , the user can interactively change the column's width. Also, the column is subject to auto-resizing, if its {@link Flexibility}
                 * attribute is greater `0` .
                 */
                Resizeable: boolean;

                /** A title is displayed in the column header row if {@link UnoControlGridModel.ShowColumnHeader()} is set to `TRUE` */
                Title: string;
            }

            /**
             * An instance of this interface is used by the {@link XGridColumnModel} to get notifications about column model changes.
             * @since OOo 3.3
             */
            interface XGridColumnListener extends lang.XEventListener {
                /** Invoked after a column was modified. */
                columnChanged(event: GridColumnEvent): void;
            }

            /**
             * An instance of this interface is used by the {@link UnoControlGrid} to retrieve the column structure that is displayed in the actual control.
             *
             * If you do not need your own model implementation, you can also use the {@link DefaultGridColumnModel} .
             * @since OOo 3.3
             */
            interface XGridColumnModel extends lang.XComponent, container.XContainer, util.XCloneable {
                /**
                 * Adds a column to the model.
                 *
                 * You should use the {@link createColumn()} member to create a new column. This gives implementations of the `XGridColumnModel` interface the
                 * possibility to provide own column implementations which extend the basic {@link GridColumn} type.
                 *
                 * As soon as the column has been inserted into the model, the model takes ownership of it. This means when the column is removed, or when the column
                 * model is disposed, the grid column is disposed as well.
                 * @param column the column to add to the model.
                 * @returns the index of new created column.
                 * @throws com::sun::star::lang::IllegalArgumentException if the given column is not a valid element for the column container, or if it is `NULL` .
                 */
                addColumn(column: XGridColumn): number;

                /**
                 * Returns the number of columns.
                 * @returns the number of columns.
                 */
                readonly ColumnCount: number;

                /**
                 * Returns all columns of the model.
                 * @returns all columns associated with the model in a sequence of {@link XGridColumn} .
                 */
                readonly Columns: SafeArray<XGridColumn>;

                /**
                 * creates a new column for use with the column model.
                 *
                 * The newly created column is not yet inserted into the column container, you need to call {@link addColumn()} after you initialized the column object.
                 */
                createColumn(): XGridColumn;

                /**
                 * Returns a specific column.
                 * @param index the position of the requested column.
                 * @returns the requested column.
                 */
                getColumn(index: number): XGridColumn;

                /**
                 * Returns the number of columns.
                 * @returns the number of columns.
                 */
                getColumnCount(): number;

                /**
                 * Returns all columns of the model.
                 * @returns all columns associated with the model in a sequence of {@link XGridColumn} .
                 */
                getColumns(): SafeArray<XGridColumn>;

                /**
                 * removes a column from the model
                 *
                 * The column object will be disposed upon removal.
                 * @param ColumnIndex denotes the index of the column to remove
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if `ColumnIndex` does not denote a valid column index.
                 */
                removeColumn(ColumnIndex: number): void;

                /**
                 * Fills the model with the given number of default columns
                 *
                 * Existing columns will be removed before adding new columns. Listeners at the column model will be notified one {@link
                 * com.sun.star.container.XContainerListener.elementRemoved()} event for each removed column, and one {@link
                 * com.sun.star.container.XContainerListener.elementInserted()} event for each insertion.
                 * @param elements the number of default columns that should be set.
                 */
                setDefaultColumns(elements: number): void;
            }

            /**
             * An interface to a control that displays a tabular data.
             * @see UnoControlGrid
             * @since OOo 3.3
             */
            interface XGridControl {
                /**
                 * returns the column index of the currently active cell
                 *
                 * If the grid control's does not contain any cells (which happens if the grid column model does not contain any columns, or if grid data model does not
                 * contain any rows), then `-1` is returned.
                 */
                readonly CurrentColumn: number;

                /**
                 * returns the row index of the currently active cell
                 *
                 * If the grid control's does not contain any cells (which happens if the grid column model does not contain any columns, or if grid data model does not
                 * contain any rows), then `-1` is returned.
                 */
                readonly CurrentRow: number;

                /**
                 * retrieves the column which a given point belongs to
                 * @param X the ordinate of the point, in pixel coordinates.
                 * @param Y the abscissa of the point, in pixel coordinates.
                 * @returns the index of the column which the point lies in, or -1 if no column is under the given point.
                 */
                getColumnAtPoint(X: number, Y: number): number;

                /**
                 * returns the column index of the currently active cell
                 *
                 * If the grid control's does not contain any cells (which happens if the grid column model does not contain any columns, or if grid data model does not
                 * contain any rows), then `-1` is returned.
                 */
                getCurrentColumn(): number;

                /**
                 * returns the row index of the currently active cell
                 *
                 * If the grid control's does not contain any cells (which happens if the grid column model does not contain any columns, or if grid data model does not
                 * contain any rows), then `-1` is returned.
                 */
                getCurrentRow(): number;

                /**
                 * retrieves the row which a given point belongs to
                 * @param X the ordinate of the point, in pixel coordinates.
                 * @param Y the abscissa of the point, in pixel coordinates.
                 * @returns the index of the row which the point lies in, or -1 if no row is under the given point.
                 */
                getRowAtPoint(X: number, Y: number): number;

                /**
                 * moves the cursor to the given cell
                 * @param ColumnIndex the column index of the cell to activate.
                 * @param RowIndex the row index of the cell to activate.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if either `ColumnIndex` or `RowIndex` are out of range.
                 * @throws com::sun::star::util::VetoException if moving the cursor to another cell is vetoed.
                 */
                goToCell(ColumnIndex: number, RowIndex: number): void;
            }

            /**
             * An instance of this interface is used by the {@link XGridDataModel} to get notifications about data model changes.
             *
             * Usually you must not implement this interface yourself, but you must notify it correctly if you implement the {@link XGridDataModel} yourself
             *
             * .
             * @since OOo 3.3
             */
            interface XGridDataListener extends lang.XEventListener {
                /** is called when existing data in a grid control's data model has been modified. */
                dataChanged(Event: GridDataEvent): void;

                /** is called when the title of one or more rows changed. */
                rowHeadingChanged(Event: GridDataEvent): void;

                /** is called when one or more rows of data have been inserted into a grid control's data model. */
                rowsInserted(Event: GridDataEvent): void;

                /** is called when one or more rows of data have been removed from a grid control's data model. */
                rowsRemoved(Event: GridDataEvent): void;
            }

            /**
             * An instance of this interface is used by the {@link UnoControlGrid} to retrieve the content data that is displayed in the actual control.
             *
             * If you do not need your own model implementation, you can also use the {@link DefaultGridDataModel} .
             * @since OOo 3.3
             */
            interface XGridDataModel extends lang.XComponent, util.XCloneable {
                /** denotes the number of columns for which the model can provide data */
                ColumnCount: number;

                /**
                 * retrieves the data for a given cell
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the column or row index do not denote a valid cell position.
                 */
                getCellData(Column: number, RowIndex: number): any;

                /**
                 * retrieves the tool tip to be displayed when the mouse hovers over a given cell
                 *
                 * At the moment, only string tool tips are supported.
                 *
                 * If `VOID` is returned here, the cell's content will be displayed as tip, but only if it does not fit into the cell.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the column or row index do not denote a valid cell position.
                 */
                getCellToolTip(Column: number, RowIndex: number): any;

                /**
                 * retrieves the data for a complete row
                 *
                 * This method is provided for performance and convenience reasons, it delivers the same result as subsequent calls to {@link getCellData()} would.
                 * @param RowIndex the index of the row whose data should is to be retrieved.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException of the given row index does not denote a valid row.
                 */
                getRowData(RowIndex: number): SafeArray;

                /**
                 * retrieves the heading of a given row
                 *
                 * A grid control will usually paint a row's title in the header column of the respective row.
                 *
                 * At the moment, only strings are supported as row headings.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the given index does not denote a valid row.
                 */
                getRowHeading(RowIndex: number): any;

                /** denotes the number of rows for which the model can provide data */
                RowCount: number;
            }

            /**
             * This interfaces provides access to the selection of row for {@link UnoControlGrid} .
             * @since LibreOffice 3.4
             */
            interface XGridRowSelection {
                /**
                 * Adds a listener for the {@link GridSelectionEvent} posted after the grid changes.
                 * @param listener the listener to add.
                 */
                addSelectionListener(listener: XGridSelectionListener): void;

                /** Deselects all selected rows. */
                deselectAllRows(): void;

                /**
                 * removes the selection for a given row
                 * @param RowIndex denotes the index of the row to deselect
                 */
                deselectRow(RowIndex: number): void;

                /**
                 * Returns the indices of all selected rows.
                 * @returns a sequence of indices.
                 */
                getSelectedRows(): SafeArray<number>;

                /**
                 * Returns whether rows are selected.
                 * @returns `TRUE` if and only if at least one row is selected.
                 */
                hasSelectedRows(): boolean;

                /**
                 * Returns whether a specific row is selected.
                 * @param RowIndex the index of a row. If the value does not denote a valid row index, i.e. is smaller than `0` or greater than the number of rows, this is
                 * @returns `TRUE` if and only if there is a row with the given index, and it is selected currently.
                 */
                isRowSelected(RowIndex: number): boolean;

                /**
                 * Removes a listener previously added with {@link addSelectionListener()} .
                 * @param listener the listener to remove.
                 */
                removeSelectionListener(listener: XGridSelectionListener): void;

                /** Selects all rows. */
                selectAllRows(): void;

                /**
                 * Returns the indices of all selected rows.
                 * @returns a sequence of indices.
                 */
                readonly SelectedRows: SafeArray<number>;

                /**
                 * selects a given row
                 * @param RowIndex denotes the index of the row to select
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if `RowIndex` does not denote a valid row index
                 */
                selectRow(RowIndex: number): void;
            }

            /** An instance of this interface is used by the {@link XGridRowSelection} to get notifications about selection changes. */
            interface XGridSelectionListener extends lang.XEventListener {
                /** Invoked after a selection was changed. */
                selectionChanged(gridSelectionEvent: GridSelectionEvent): void;
            }

            /** allows to modify the data represented by a {@link XGridDataModel} */
            interface XMutableGridDataModel extends XGridDataModel {
                /**
                 * registers listener to be notified of data changes in the model
                 * @param Listener specifies the listener to register
                 */
                addGridDataListener(Listener: XGridDataListener): void;

                /**
                 * appends a row to the model.
                 * @param Heading denotes the heading of the row.
                 * @param Data specifies the content of the row.
                 */
                addRow(Heading: any, Data: LibreOffice.SeqEquiv): void;

                /**
                 * appends multiple rows of data to the model.
                 * @param Headings denotes the headings of the to-be-added rows.
                 * @param Data specifies the data of the rows to be added.
                 * @throws com::sun::star::lang::IllegalArgumentException if `Titles` and `Data` are of different length.
                 */
                addRows(Headings: LibreOffice.SeqEquiv, Data: LibreOffice.SeqEquiv<LibreOffice.SeqEquiv>): void;

                /**
                 * inserts a row into the set of data rows
                 * @param Index denotes the position at which the row is to be inserted
                 * @param Heading denotes the heading of the row.
                 * @param Data specifies the content of the row.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if `Index` is smaller than `0` or greater than the number of rows in the model.
                 */
                insertRow(Index: number, Heading: any, Data: LibreOffice.SeqEquiv): void;

                /**
                 * inserts multiple rows of data into the model.
                 * @param Index denotes the position at which the rows are to be inserted
                 * @param Headings denotes the headings of the to-be-added rows.
                 * @param Data specifies the data of the rows to be added.
                 * @throws com::sun::star::lang::IllegalArgumentException if `Titles` and `Data` are of different length.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if `Index` is smaller than `0` or greater than the number of rows in the model.
                 */
                insertRows(
                    Index: number,
                    Headings: LibreOffice.SeqEquiv,
                    Data: LibreOffice.SeqEquiv<LibreOffice.SeqEquiv>,
                ): void;

                /** Removes all rows from the model. */
                removeAllRows(): void;

                /**
                 * revokes a listener which was previously registered via {@link addGridDataListener()}
                 * @param Listener specifies the listener to revoke.
                 */
                removeGridDataListener(Listener: XGridDataListener): void;

                /**
                 * removes a row of data from the model
                 * @param RowIndex the index of the row that should be removed.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the given index is invalid
                 */
                removeRow(RowIndex: number): void;

                /**
                 * updates the content of the given cell
                 * @param ColumnIndex the column index of the to-be-updated cell
                 * @param RowIndex the row index of the to-be-updated cell
                 * @param Value the new value of the cell.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the row or column index is invalid
                 */
                updateCellData(ColumnIndex: number, RowIndex: number, Value: any): void;

                /**
                 * updates the tooltip to be displayed for a given cell
                 * @see XGridDataModel.getCellToolTip
                 */
                updateCellToolTip(ColumnIndex: number, RowIndex: number, Value: any): void;

                /**
                 * updates the content of a given row.
                 *
                 * The change in the data model will be notified to registered listeners via {@link XGridDataListener.dataChanged()} . The {@link
                 * GridDataEvent.FirstColumn} and {@link GridDataEvent.LastColumn} will denote the smallest respectively largest column index from ColumnIndexes.
                 * @param ColumnIndexes contains the column indexes of the cells, which should be updated
                 * @param RowIndex contains the index of the row whose data is to be updated
                 * @param Values specifies the new values of the cells.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if one of the row indexes or the column index is invalid
                 * @throws com::sun::star::lang::IllegalArgumentException if the lengths of the `ColumnIndexes` and `Values` sequences are not equal.
                 */
                updateRowData(
                    ColumnIndexes: LibreOffice.SeqEquiv<number>,
                    RowIndex: number,
                    Values: LibreOffice.SeqEquiv,
                ): void;

                /**
                 * sets a new title for a given row.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if the given index does not denote a valid row.
                 */
                updateRowHeading(RowIndex: number, Heading: any): void;

                /**
                 * updates the tooltip for all cells of a given row
                 *
                 * Effectively this method is a shortcut for calling {@link updateCellToolTip()} multiple times in a row, for all cells of a given row.
                 * @see XGridDataModel.getCellToolTip
                 * @see updateCellToolTip
                 */
                updateRowToolTip(RowIndex: number, Value: any): void;
            }

            /** allows to sort the data represented by a {@link XGridDataModel} */
            interface XSortableGridData {
                /**
                 * returns the current sort order.
                 * @returns a structure describing the current sort order. com::sun::star::beans::Pair::First denotes the column by which the data is sorted, or -1 if the da
                 */
                readonly CurrentSortOrder: com.sun.star.beans.Pair<number, boolean>;

                /**
                 * returns the current sort order.
                 * @returns a structure describing the current sort order. com::sun::star::beans::Pair::First denotes the column by which the data is sorted, or -1 if the da
                 */
                getCurrentSortOrder(): com.sun.star.beans.Pair<number, boolean>;

                /** removes any possibly present sorting of the grid data */
                removeColumnSort(): void;

                /**
                 * sorts the rows represented by the model by a given column's data.
                 * @param ColumnIndex the index of the column whose data should be used as sort key
                 * @param SortAscending is `TRUE` if the data should be sorted ascending, `FALSE` otherwise.
                 * @throws com::sun::star::lang::IndexOutOfBoundsException if `ColumnIndex` does not denote a valid column.
                 */
                sortByColumn(ColumnIndex: number, SortAscending: boolean): void;
            }

            /** describes a grid control data model whose data can be modified and sorted. */
            interface XSortableMutableGridDataModel extends XMutableGridDataModel, XSortableGridData {}
        }

