        /** Sets the type of curves that are drawn for line charts. */
        const enum CurveStyle {
            /** Data points are connected via a parametric, interpolating B-spline curve. */
            B_SPLINES = 2,
            /** Data points are connected via a smoothed cubic spline curve. The data points themselves are part of to the curve. */
            CUBIC_SPLINES = 1,
            /** Lines between data points are not smoothed */
            LINES = 0,
            NURBS = 3,
            /**
             * Data points are connected via a 3-segmented stepped line. The lines is horizontal till the center of the X values.
             *
             * +--O
             *
             *             |
             *
             *             |
             *
             *             |
             *
             *          O--+
             */
            STEP_CENTER_X = 6,
            /**
             * Data points are connected via a 3-segmented stepped line. The lines is horizontal at the center of the Y values.
             *
             * O
             *
             *                |
             *
             *          +-----+
             *
             *          |
             *
             *          O
             */
            STEP_CENTER_Y = 7,
            /**
             * Data points are connected via a 2-segmented stepped line. The line ends horizontally.
             *
             * +------O
             *
             *         |
             *
             *         |
             *
             *         |
             *
             *         O
             */
            STEP_END = 5,
            /**
             * Data points are connected via a 2-segmented stepped line. The line starts horizontally.
             *
             * O
             *
             *                |
             *
             *                |
             *
             *                |
             *
             *          O-----+
             */
            STEP_START = 4,
        }

        const enum LegendPosition {
            /** The position of the legend is given by an offset value */
            CUSTOM = 4,
            /** In LTR mode this is the right-hand side <p>This usually is the default.</p> */
            LINE_END = 1,
            /** In LTR mode this is the left-hand side */
            LINE_START = 0,
            /** In LTR mode this is the bottom side */
            PAGE_END = 3,
            /** In LTR mode this is the top side */
            PAGE_START = 2,
        }

        /** Mode used for a pie chart template to determine the initial state of exploded pies. */
        const enum PieChartOffsetMode {
            /** All pies are exploded by a certain percentage. The default is 10 percent. */
            ALL_EXPLODED = 1,
            /**
             * Default, no pies are exploded.
             *
             * The symbol is invisible
             *
             * no transparency attribute is evaluated
             */
            NONE = 0,
        }

        const enum StackingDirection {
            NO_STACKING = 0,
            Y_STACKING = 1,
            Z_STACKING = 2,
        }

        /** determines what kind of symbol to use */
        const enum SymbolStyle {
            /**
             * The symbol is taken automatically. <p>This will typically be the nth standard symbol for the nth
             *
             * data series.</p>
             */
            AUTO = 1,
            /** uses the graphic given in {@link Symbol.Graphic} as symbol. */
            GRAPHIC = 4,
            /**
             * Default, no pies are exploded.
             *
             * The symbol is invisible
             *
             * no transparency attribute is evaluated
             */
            NONE = 0,
            /** uses the symbol given in the {@link com.sun.star.drawing.PolyPolygonBezierCoords} given in {@link Symbol.PolygonCoords} . */
            POLYGON = 3,
            /** uses one of the standard symbols. Which standard symbol is given in {@link Symbol.StandardSymbol} . */
            STANDARD = 2,
        }

        const enum TransparencyStyle {
            /** The property TransparencyGradient is evaluated, Transparency is ignored */
            GRADIENT = 2,
            /** The property Transparency is evaluated, TransparencyGradient is ignored */
            LINEAR = 1,
            /**
             * Default, no pies are exploded.
             *
             * The symbol is invisible
             *
             * no transparency attribute is evaluated
             */
            NONE = 0,
        }

