        interface DataPointProperties extends beans.PropertySet, drawing.FillProperties {
            /**
             * Is used for borders around filled objects. See `LineColor` .
             * @see com.sun.star.drawing.LineProperties
             */
            BorderColor: number;

            /**
             * Is used for borders around filled objects. See `LineDash` .
             * @see com.sun.star.drawing.LineProperties
             */
            BorderDash: drawing.LineDash;

            /**
             * The name of a dash that can be found in the {@link com.sun.star.container.XNameContainer} "com.sun.star.drawing.LineDashTable", that can be created
             * via the com::sun::star::uno::XMultiServiceFactory of the {@link ChartDocument} .
             */
            BorderDashName: string;

            /**
             * Is used for borders around filled objects. See `LineStyle` .
             * @see com.sun.star.drawing.LineProperties
             */
            BorderStyle: drawing.LineStyle;

            /**
             * Is used for borders around filled objects. See `LineTransparence` .
             * @see com.sun.star.drawing.LineProperties
             */
            BorderTransparency: number;

            /**
             * Is used for borders around filled objects. See `LineWidth` .
             * @see com.sun.star.drawing.LineProperties
             */
            BorderWidth: number;

            /**
             * points to a style that also supports this service (but not this property) that is used as default, if the PropertyState of a property is
             * `DEFAULT_VALUE` .This is the main color of a data point.
             *
             * For charts with filled areas, like bar-charts, this should map to the `FillColor` of the objects. For line-charts this should map to the `LineColor`
             * property.
             * @see com.sun.star.drawing.FillProperties
             * @see com.sun.star.drawing.LineProperties
             */
            Color: number;

            /**
             * If void, no error bars are shown for the data point in x-direction.
             *
             * The {@link com.sun.star.beans.XPropertySet} must support the service {@link ErrorBar} .
             */
            ErrorBarX: beans.XPropertySet;

            /**
             * If void, no error bars are shown for the data point in y-direction.
             *
             * The {@link com.sun.star.beans.XPropertySet} must support the service {@link ErrorBar} .
             */
            ErrorBarY: beans.XPropertySet;

            /** If `TRUE` , fills the background of a hatch with the color given in the {@link Color} property. */
            FillBackground: boolean;

            /**
             * specifies if the size is given in percentage or as an absolute value.
             *
             * If this is `TRUE` , the properties FillBitmapSizeX and FillBitmapSizeY contain the size of the tile in percent of the size of the original bitmap. If
             * this is `FALSE` , the size of the tile is specified with 1/100th mm.
             */
            FillBitmapLogicalSize: boolean;

            /** this enum selects how a area is filled with a single bitmap. */
            FillBitmapMode: drawing.BitmapMode;
            FillBitmapName: string;

            /**
             * This is the horizontal offset where the tile starts.
             *
             * It is given in percent in relation to the width of the bitmap.
             */
            FillBitmapOffsetX: number;

            /**
             * This is the vertical offset where the tile starts.
             *
             * It is given in percent in relation to the width of the bitmap.
             */
            FillBitmapOffsetY: number;

            /** Every second line of tiles is moved the given percent of the width of the bitmap. */
            FillBitmapPositionOffsetX: number;

            /** Every second row of tiles is moved the given percent of the width of the bitmap. */
            FillBitmapPositionOffsetY: number;

            /** The RectanglePoint specifies the position inside of the bitmap to use as the top left position for rendering. */
            FillBitmapRectanglePoint: drawing.RectanglePoint;

            /**
             * This is the width of the tile for filling.
             *
             * Depending on the property FillBitmapLogicalSize, this is either relative or absolute.
             */
            FillBitmapSizeX: number;

            /**
             * This is the height of the tile for filling.
             *
             * Depending on the property FillBitmapLogicalSize, this is either relative or absolute.
             */
            FillBitmapSizeY: number;

            /** This enumeration selects the style with which the area will be filled. */
            FillStyle: drawing.FillStyle;

            /**
             * describes the geometry of a 3 dimensional data point. Number is one of constant group {@link DataPointGeometry3D} .
             *
             * This is especially used for 3D bar-charts.
             *
             * CUBOID==0 CYLINDER==1 CONE==2 PYRAMID==3 CUBOID==else
             */
            Geometry3D: number;
            Gradient: awt.Gradient;
            GradientName: string;
            Hatch: drawing.Hatch;
            HatchName: string;
            Label: DataPointLabel;

            /**
             * specifies a relative position for the data label
             * @see com.sun.star.chart.DataLabelPlacement
             */
            LabelPlacement: number;

            /** specifies a string that is used to separate the parts of a data label (caption) */
            LabelSeparator: string;

            /**
             * Is only used for line-chart types.
             * @see com.sun.star.drawing.LineProperties
             */
            LineDash: drawing.LineDash;

            /**
             * The name of a dash that can be found in the {@link com.sun.star.container.XNameContainer} "com.sun.star.drawing.LineDashTable", that can be created
             * via the com::sun::star::uno::XMultiServiceFactory of the {@link ChartDocument} .
             */
            LineDashName: string;
            LineStyle: drawing.LineStyle;

            /**
             * Is only used for line-chart types.
             * @see com.sun.star.drawing.LineProperties
             */
            LineWidth: number;

            /** specifies a number format for the display of the value in the data label */
            NumberFormat: number;

            /**
             * describes a value by which a data point is moved from its default position in percent of the maximum allowed distance.
             *
             * This is especially useful for the explosion of pie-chart segments.
             */
            Offset: number;

            /** specifies a number format for the display of the percentage value in the data label */
            PercentageNumberFormat: number;

            /** A value between 0 and 100 indicating the percentage how round an edge should be. */
            PercentDiagonal: number;

            /**
             * The size of the page at the moment when the font size for data labels was set.
             *
             * This size is used to resize text in the view when the size of the page has changed since the font sizes were set (automatic text scaling).
             */
            ReferencePageSize: awt.Size;
            setPropertyValues(aProps: LibreOffice.SeqEquiv<beans.PropertyValue> | LibreOffice.SeqEquiv<string>): void;

            /** In case {@link ErrorBarX} and {@link ErrorBarY} both are set, and error bars are shown, a box spanning all error-indicators is rendered. */
            ShowErrorBox: boolean;
            Symbol: Symbol;

            /**
             * specifies if the text of a data label (caption) must be wrapped
             * @since LibreOffice 5.1
             */
            TextWordWrap: boolean;

            /**
             * This is the main transparency value of a data point.
             *
             * For charts with filled areas, like bar-charts, this should map to the `FillTransparence` of the objects. For line-charts this should map to the
             * `LineTransparence` property.
             * @see com.sun.star.drawing.FillProperties
             * @see com.sun.star.drawing.LineProperties
             */
            Transparency: number;

            /** This describes the transparency of the fill area as a gradient. */
            TransparencyGradient: awt.Gradient;
            TransparencyGradientName: string;
        }

        /**
         * reflects the model data of the object that has all the information for a DataRenderer to create a visible data series in a chart.
         *
         * It combines one or more DataSequences which are interpreted by evaluating their role-string.
         * @see DataSequenceRole
         */
        interface DataSeries
            extends
                beans.PropertySet,
                DataPointProperties,
                XDataSeries,
                data.XDataSink,
                data.XDataSource,
                XRegressionCurveContainer
        {
            /**
             * This property describes whether the series should be shown at the main value axis or at the secondary value axis. Having this property not set or
             * setting it to 0 means that this data series will be scaled at the primary y-axis ( of the coordinate system in which this series is hosted ).
             *
             * Setting this property to 1 means that this series should be scaled at the secondary y-axis. If there is no secondary axis the main axis should be used
             * for scaling instead.
             *
             * If you want to scale a series at a different x or z axis you need to create an additional coordinate system and host this series there.
             */
            AttachedAxisIndex: number;

            /**
             * This service will be used to render this data series.
             *
             * This service name can be used to determine which {@link DataSeries} are of the same type.
             *
             * The result of the DataSeries::DataSequenceRoles depends on the renderer service set here.
             *
             * a sequence of indexes denoting which data points have set properties that differ from the default.
             *
             * The default values are determined by the properties set at the {@link DataPointProperties} of the data series.
             *
             * If the sequence is empty, that means that all data points look alike. They are formatted using the property values set in the data series.
             *
             * The indexes in this sequence match the indexes used by the XIndexContainer.
             *
             * This property is especially useful for large data series with only some formatted data points, because you do not have to iterate over all elements.
             */
            AttributedDataPoints: SafeArray<number>;
            setPropertyValues(aProps: LibreOffice.SeqEquiv<beans.PropertyValue> | LibreOffice.SeqEquiv<string>): void;

            /** indicates whether this series should be stacked with respect to the previous series. */
            StackingDirection: StackingDirection;

            /** If `TRUE` , the data points of this series get different colors by default, like in a pie chart. */
            VaryColorsByPoint: boolean;
        }

