        /**
         * This {@link Shape} encapsulates a plugin.
         *
         * A plugin is a binary object that is plugged into a document to represent a media-type that is not handled natively by the application.
         */
        interface PluginShape extends Shape {
            /** This sequence contains parameters that are passed to the application that renders the plugin when it is initialized. */
            PluginCommands: SafeArray<beans.PropertyValue>;

            /** This property specifies the media-type to which this plugin should be registered. */
            PluginMimeType: string;

            /** This property specifies the url to the binary object. */
            PluginURL: string;
        }

        /**
         * This service is for a polyline shape.
         *
         * A polyline has one or more straight lines.
         */
        interface PolyLineShape
            extends Shape, LineProperties, PolyPolygonDescriptor, Text, ShadowProperties, RotationDescriptor
        {}

        /** specifies the coordinates for a poly polygon Bezier. */
        interface PolyPolygonBezierCoords {
            Coordinates: PointSequenceSequence;
            Flags: FlagSequenceSequence;
        }

        /**
         * This service describes a polypolygonbezier.
         *
         * A polypolygonbezier consists of multiple Bezier polygons combined in one.
         */
        interface PolyPolygonBezierDescriptor {
            /** These are the untransformed Bezier coordinates of this polygon. */
            Geometry: PolyPolygonBezierCoords;

            /** This is the type of this polygon. */
            PolygonKind: PolygonKind;

            /** These are the Bezier points of this polygon. */
            PolyPolygonBezier: PolyPolygonBezierCoords;
        }

        /** This service specifies a poly-polygon Bezier shape. */
        interface PolyPolygonBezierShape
            extends
                Shape,
                LineProperties,
                FillProperties,
                PolyPolygonBezierDescriptor,
                Text,
                ShadowProperties,
                RotationDescriptor
        {}

        /**
         * This service describes a poly-polygon.
         *
         * A poly-polygon consists of multiple polygons combined in one.
         */
        interface PolyPolygonDescriptor {
            /** These are the untransformed points of this polygon. */
            Geometry: PointSequenceSequence;

            /** This is the type of polygon. */
            PolygonKind: PolygonKind;

            /** These are the reference points for this polygon. */
            PolyPolygon: PointSequenceSequence;
        }

        /**
         * This service is for a polygon shape.
         *
         * A poly-polygon has 2 or more straight lines, with the first and last point connected by a straight line.
         */
        interface PolyPolygonShape
            extends
                Shape,
                LineProperties,
                FillProperties,
                PolyPolygonDescriptor,
                Text,
                ShadowProperties,
                RotationDescriptor
        {}

        /** specifies the coordinates of a 3-dimensional poly polygon. */
        interface PolyPolygonShape3D {
            SequenceX: DoubleSequenceSequence;
            SequenceY: DoubleSequenceSequence;
            SequenceZ: DoubleSequenceSequence;
        }

        /** specifies a 3-dimensional point. */
        interface Position3D {
            /** the position on the X-Axis in the 3D room in 100th of millimeters */
            PositionX: number;

            /** the position on the Y-Axis in the 3D room in 100th of millimeters */
            PositionY: number;

            /** the position on the Z-Axis in the 3D room in 100th of millimeters */
            PositionZ: number;
        }

        /** This service is for a rectangle {@link Shape} . */
        interface RectangleShape
            extends Shape, FillProperties, LineProperties, Text, ShadowProperties, RotationDescriptor
        {
            /** For {@link Shapes} with rounded corners, this is the radius of the corners. */
            CornerRadius: number;
        }

        /**
         * This abstract service specifies the general characteristics of an optional rotation and shearing for a {@link Shape} .
         *
         * This service is deprecated, instead please use the `Transformation` property of the service {@link Shape} .
         * @deprecated Deprecated
         */
        interface RotationDescriptor {
            /**
             * This is the angle for rotation of this {@link Shape} . The shape is rotated counter-clockwise around the center of the bounding box.
             *
             * This property contains an error, the rotation angle is mathematically inverted when You take into account that the Y-Axis of the coordinate system is
             * pointing down. Please use the `Transformation` property of the service {@link Shape} instead.
             * @deprecated Deprecated
             */
            RotateAngle: number;

            /**
             * This is the amount of shearing for this {@link Shape} . The shape is sheared counter-clockwise around the center of the bounding box
             * @deprecated Deprecated
             */
            ShearAngle: number;
        }

        /** This is a set of properties to describe the style for rendering a shadow. */
        interface ShadowProperties {
            /**
             * enables/disables the shadow of a {@link Shape} .
             *
             * The other shadow properties are only applied if this is set to `TRUE` .
             */
            Shadow: boolean;

            /** This is the color of the shadow of this {@link Shape} . */
            ShadowColor: util.Color;

            /** This defines the degree of transparence of the shadow in percent. */
            ShadowTransparence: number;

            /** This is the horizontal distance of the left edge of the {@link Shape} to the shadow. */
            ShadowXDistance: number;

            /** This is the vertical distance of the top edge of the {@link Shape} to the shadow. */
            ShadowYDistance: number;
        }

        /**
         * This abstract service specifies the general characteristics of all {@link Shapes} .
         * @see XShape
         * @see com.sun.star.lang.XComponent
         * @see com.sun.star.text.XText
         * @see ShapeDescriptor
         */
        interface Shape
            extends
                beans.XPropertySet,
                XShape,
                lang.XComponent,
                XShapeDescriptor,
                XGluePointsSupplier,
                beans.XTolerantMultiPropertySet
        {
            /** this property lets you get and set a hyperlink for this shape. */
            Hyperlink: string;

            /**
             * Grab bag of shape properties, used as a string-any map for interim interop purposes.
             * @since LibreOffice 4.2  This property is intentionally not handled by the ODF filter. Any member that should be handled there should be first moved out
             */
            InteropGrabBag: SafeArray<beans.PropertyValue>;

            /** This is the ID of the {@link Layer} to which this {@link Shape} is attached. */
            LayerID: number;

            /** This is the name of the {@link Layer} to which this {@link Shape} is attached. */
            LayerName: string;

            /** With this set to `TRUE` , this {@link Shape} cannot be moved interactively in the user interface. */
            MoveProtect: boolean;

            /** This is the name of this {@link Shape} . */
            Name: string;

            /** this property stores the navigation order of this shape. If this value is negative, the navigation order for this shapes page is equal to the z-order. */
            NavigationOrder: number;

            /** If this is `FALSE` , the {@link Shape} is not visible on printer outputs. */
            Printable: boolean;

            /**
             * contains the relative height of the object.
             *
             * It is only valid if it is greater than zero.
             * @since LibreOffice 4.3
             */
            RelativeHeight: number;

            /**
             * contains the relation of the relative height of the object.
             *
             * It is only valid if RelativeHeight is greater than zero.
             * @see com.sun.star.text.RelOrientation
             * @since LibreOffice 4.3
             */
            RelativeHeightRelation: number;

            /**
             * contains the relative width of the object.
             *
             * It is only valid if it is greater than zero.
             * @since LibreOffice 4.3
             */
            RelativeWidth: number;

            /**
             * contains the relation of the relative width of the object.
             *
             * It is only valid if RelativeWidth is greater than zero.
             * @see com.sun.star.text.RelOrientation
             * @since LibreOffice 4.3
             */
            RelativeWidthRelation: number;

            /**
             * this property stores xml attributes. They will be saved to and restored from automatic styles inside xml files.
             * @see com.sun.star.xml.AttributeContainer
             */
            ShapeUserDefinedAttributes: container.XNameContainer;

            /** With this set to `TRUE` , this {@link Shape} may not be sized interactively in the user interface. */
            SizeProtect: boolean;

            /** this property lets you get and set a style for this shape. */
            Style: style.XStyle;

            /**
             * this property lets you get and set the transformation matrix for this shape.
             *
             * The transformation is a 3x3 homogeneous matrix and can contain translation, rotation, shearing and scaling.
             */
            Transformation: HomogenMatrix3;

            /**
             * If this is `FALSE` , the {@link Shape} is not visible on screen outputs. Please note that the {@link Shape} may still be visible when printed, see
             * {@link Printable} .
             */
            Visible: boolean;

            /** is used to query or change the ZOrder of this {@link Shape} . */
            ZOrder: number;
        }

        /** Create preview bitmaps for single slides. */
        interface SlideRenderer extends XSlideRenderer {
            /** Create a new {@link SlideRenderer} object. */
            create(): void;
        }

        /**
         * A slide sorter shows previews for a set of slides, typically all slides in a document, and allows the selection, reordering, creation, and deletion of
         * slides.
         *
         * In the drawing framework a slide sorter is regarded as a view.
         */
        interface SlideSorter extends XSlideSorterBase {
            /**
             * Create a new slide sorter object.
             * @param xViewId The resource id of the new slide sorter.
             * @param xController The access point to an impress document.
             * @param xParentWindow The parent window which will be completely covered by the new slide sorter.
             */
            create(xViewId: framework.XResourceId, xController: frame.XController, xParentWindow: awt.XWindow): void;
        }

        /** This abstract service specifies the general characteristics of an optional text inside a {@link Shape} . */
        interface Text extends text.XText, TextProperties {}

        /** This is a set of properties to describe the style for rendering the text area inside a shape. */
        interface TextProperties
            extends
                style.CharacterProperties,
                style.CharacterPropertiesAsian,
                style.CharacterPropertiesComplex,
                style.ParagraphProperties,
                style.ParagraphPropertiesAsian,
                style.ParagraphPropertiesComplex
        {
            /** If this is `TRUE` , numbering is ON for the text of this {@link Shape} . */
            IsNumbering: boolean;

            /**
             * describes the numbering levels.
             *
             * The different rules accessible with this {@link com.sun.star.container.XIndexReplace} interface are sequences of property values as described in the
             * service {@link com.sun.star.style.NumberingRule} .
             */
            NumberingRules: container.XIndexReplace;

            /** This is the number of pixels the text is moved in each animation step. */
            TextAnimationAmount: number;

            /**
             * This number defines how many times the text animation is repeated.
             *
             * If this is set to zero, the repeat is endless.
             */
            TextAnimationCount: number;

            /** This is the delay in thousandths of a second between each of the animation steps. */
            TextAnimationDelay: number;

            /** This enumeration defines the direction in which the text moves. */
            TextAnimationDirection: TextAnimationDirection;

            /** This value defines the type of animation. */
            TextAnimationKind: TextAnimationKind;

            /** If this value is `TRUE` , the text is visible at the start of the animation. */
            TextAnimationStartInside: boolean;

            /** If this value is `TRUE` , the text is visible at the end of the animation. */
            TextAnimationStopInside: boolean;

            /** If this value is `TRUE` , the height of the {@link Shape} is automatically expanded/shrunk when text is added to or removed from the {@link Shape} . */
            TextAutoGrowHeight: boolean;

            /** If this value is `TRUE` , the width of the {@link Shape} is automatically expanded/shrunk when text is added to or removed from the {@link Shape} . */
            TextAutoGrowWidth: boolean;

            /** If this value is `TRUE` , the left edge of every line of text is aligned with the left edge of this {@link Shape} . */
            TextContourFrame: boolean;

            /** With this set to `TRUE` , the text inside of the {@link Shape} is stretched to fit into the {@link Shape} . */
            TextFitToSize: TextFitToSizeType;

            /** adjusts the horizontal position of the text inside of the {@link Shape} . */
            TextHorizontalAdjust: TextHorizontalAdjust;

            /**
             * This is the distance from the left edge of the {@link Shape} to the left edge of the text.
             *
             * This is only useful if {@link Text.TextHorizontalAdjust} is BLOCK or STRETCH or if Text::TextFitSize is `TRUE` .
             */
            TextLeftDistance: number;

            /**
             * This is the distance from the lower edge of the {@link Shape} to the lower edge of the text.
             *
             * This is only useful if {@link Text.TextVerticalAdjust} is BLOCK or if Text::TextFitSize is `TRUE` .
             */
            TextLowerDistance: number;

            /**
             * with this property you can set the maximum height for a shape with text. On edit, the auto grow feature will not grow the object higher than the value
             * of this property.
             */
            TextMaximumFrameHeight: number;

            /**
             * with this property you can set the maximum width for a shape with text. On edit, the auto grow feature will not grow the objects wider than the value
             * of this property.
             */
            TextMaximumFrameWidth: number;

            /**
             * with this property you can set the minimum height for a shape with text. On edit, the auto grow feature will not shrink the objects height smaller
             * than the value of this property.
             */
            TextMinimumFrameHeight: number;

            /**
             * with this property you can set the minimum width for a shape with text. On edit, the auto grow feature will not shrink the object width smaller than
             * the value of this property.
             */
            TextMinimumFrameWidth: number;

            /**
             * This is the distance from the right edge of the {@link Shape} to the right edge of the text.
             *
             * This is only useful if {@link Text.TextHorizontalAdjust} is BLOCK or STRETCH or if Text::TextFitSize is `TRUE` .
             */
            TextRightDistance: number;

            /**
             * This is the distance from the upper edge of the {@link Shape} to the upper edge of the text.
             *
             * This is only useful if {@link Text.TextVerticalAdjust} is BLOCK or if Text::TextFitSize is `TRUE` .
             */
            TextUpperDistance: number;

            /** adjusts the vertical position of the text inside of the {@link Shape} . */
            TextVerticalAdjust: TextVerticalAdjust;

            /** This value selects the writing mode for the text. */
            TextWritingMode: text.WritingMode;
        }

        /** This service is for a text shape. */
        interface TextShape extends Shape, FillProperties, LineProperties, ShadowProperties, Text, RotationDescriptor {
            /** This is the radius of the corners. */
            CornerRadius: number;
        }

