        namespace framework {
            /**
             * Abstraction of tool bars used by the drawing framework.
             * @see XToolBarController
             * @see XToolBarFactory
             */
            type XToolBar = XResource;

            /**
             * A view in the drawing framework is any object that paints into a pane.
             *
             * Typical examples are the Impress views that show a graphical representation of a document. But the task pane, which is primarily a container of
             * dialogs, is a view as well.
             *
             * Luckily the drawing framework does not need to know much about what a view is. It just needs to identify view objects and a typesafe way to reference
             * them.
             *
             * The URL prefix of views is `private:resource/view`
             */
            type XView = XResource;

            /**
             * This enum specifies how a resource is bound to an anchor. This can be direct or indirect.
             *
             * Example: Let r:a1:a2 denote a resource r which is bound to anchor a1:a2 which itself is a resource a1 bound to anchor a2. Then r:a1:a2 is bound
             * directly to a1:a2 and indirectly to a2.
             */
            const enum AnchorBindingMode {
                DIRECT = 0,
                INDIRECT = 1,
            }

            /** See {@link XPaneBorderPainter} and its addBorder() and removeBorder() methods for an explanation of the border type and its values. */
            const enum BorderType {
                INNER_BORDER = 0,
                OUTER_BORDER = 1,
                TOTAL_BORDER = 2,
            }

            /**
             * The ResourceActivationMode specifies, for example for the {@link com.sun.star.drawing.framework.XConfigurationController.requestResourceActivation()}
             * , whether a requested resource is to replace an existing resource of the same class or is to be activated additionally.
             */
            const enum ResourceActivationMode {
                /** A resource is requested in addition to already existing ones. This is used for example for panes. */
                ADD = 0,
                /** A resource is requested to replace an already existing one of the same class. This is used for example for views. */
                REPLACE = 1,
            }

            /**
             * The {@link BasicPaneFactory} is a resource factory that provides the panes used by the Draw and Impress applications.
             *
             * This factory provides the center, left, and right pane. For the left pane there are two URLS, `private:resource/floater/LeftImpressPane` and
             * `private:resource/floater/LeftDrawPane` , one for Impress, the other for Draw. The center pane and the right pane have the URLs
             * `private:resource/floater/CenterPane` and `private:resource/floater/RightPane` respectively.
             *
             * This factory is typically created indirectly by registering it in the configuration and have the {@link XModuleController} create it on demand.
             */
            interface BasicPaneFactory extends XResourceFactory {
                /** Give the controller to new instances so that they have access to the drawing framework controllers. */
                create(xController: frame.XController): void;
            }

            /**
             * The {@link BasicToolBarFactory} is a resource factory that provides (some of) the tool bars used by the Draw and Impress applications.
             *
             * The factory recognizes the following URLs: `private:resource/toolbar/ViewTabBar` for the tab bar that allows the switching between views. This short
             * list marks the implementation of this service clearly as being in transition.
             *
             * This factory is typically created indirectly by registering it in the configuration and have the {@link XModuleController} create it on demand.
             */
            interface BasicToolBarFactory extends XResourceFactory {
                /** Give the controller to new instances so that they have access to the drawing framework controllers. */
                create(xController: frame.XController): void;
            }

            /**
             * The {@link BasicViewFactory} is a view factory that provides the panes used by the Draw and Impress applications.
             *
             * The factory recognizes the following URLs: `private:resource/view/ImpressView` for the regular edit view of the Impress
             * application.`private:resource/view/GraphicView` for the regular edit view of the Draw application.`private:resource/view/OutlineView` for the outline
             * view.`private:resource/view/NotesView` for the notes view.`private:resource/view/HandoutView` for the handout view.`private:resource/view/SlideSorter`
             * for the slide sorter regardless of which pane it is used in.`private:resource/view/PresentationView` for the slide
             * show.`private:resource/view/TaskPane` for the task pane.
             */
            interface BasicViewFactory extends XResourceFactory {
                /** Give the controller to new instances so that they have access to the drawing framework controllers. */
                create(xController: frame.XController): void;
            }

            /**
             * This service provides the means for constructing new configurations.
             *
             * Most likely use is the {@link XConfigurationController.restoreConfiguration()} method.
             * @see XConfiguration for a description of the configuration.
             */
            interface Configuration extends XConfiguration {
                /**
                 * Create an empty configuration.
                 *
                 * This should not be necessary very often. Changes to an existing configuration are more likely.
                 */
                create(): void;
            }

            /**
             * Objects of this class are used for notifying changes of the configuration.
             *
             * They are broadcasted by the configuration controller which maintains the configuration. The set of types of configuration changes is not fixed and is
             * not maintained or documented in one place.
             *
             * The set of used members and the exact meaning of their values is not the same for all types. Therefore, the descriptions of the members are just
             * general guidelines. See {@link XConfigurationController} for a list of event types used by the basic drawing framework.
             */
            interface ConfigurationChangeEvent extends lang.EventObject {
                /** The current configuration, depending on the event type, either before or after the change. May be an empty reference. */
                Configuration: XConfiguration;

                /** The resource id that is part of the configuration change. */
                ResourceId: XResourceId;

                /** The resource object that corresponds to the {@link ResourceId} . May be an empty reference. */
                ResourceObject: uno.XInterface;

                /**
                 * The type of configuration change is a free-form string. This is the only member that is always set. The values of the other members depend on the
                 * configuration change type and may or may not be set.
                 */
                Type: string;

                /** Each listener is called with exactly the {@link UserData} that was given when the listener was registered. */
                UserData: any;
            }

            /**
             * See {@link XConfigurationController} for a description of the configuration controller.
             *
             * This service is used at the moment by the {@link XControllerManager} to create a configuration controller. This allows developers to replace the
             * default implementation of the configuration controller with their own. This may not be a useful feature. Furthermore the sub controllers may need a
             * tighter coupling than the interfaces allow. These are reasons for removing this service in the future and let the controller manager create the sub
             * controllers directly.
             */
            interface ConfigurationController extends XConfigurationController {
                create(xController: frame.XController): void;
            }

            /**
             * See {@link XModuleController} for a description of the module controller.
             *
             * See {@link ConfigurationController} for a comment why this service may be removed in the future.
             *
             * The {@link ModuleController} object for an application can be obtained via the {@link XControllerManager} interface.
             */
            interface ModuleController extends XModuleController {
                /** Create a new instance of a {@link ModuleController} as sub controller of the given XController object. */
                create(xController: frame.XController): void;
            }

            /**
             * The {@link ResourceId} service provides several constructors for resource ids.
             *
             * They mainly differ in how the anchor is specified.
             */
            interface ResourceId extends XResourceId {
                /**
                 * Create a resource id that has no anchor.
                 *
                 * This constructor can be used to create resource ids for panes.
                 */
                create(sResourceURL: string): void;

                /** Create an empty resource id. It does not specify a specific resource but describes the absence of one. */
                createEmpty(): void;

                /** Create a resource id for an anchor that is given as {@link XResourceId} object. This is the most general of the constructor variants. */
                createWithAnchor(sResourceURL: string, xAnchor: XResourceId): void;

                /**
                 * Create a resource id for a resource that is bound to an anchor that can be specified by a single URL.
                 *
                 * This constructor can be used to create resources ids for views where the anchor is a pane.
                 */
                createWithAnchorURL(sResourceURL: string, sAnchorURL: string): void;
            }

            /**
             * Descriptor of a tab bar button. Tab bar buttons are typically used to offer the user the choice between different views to be displayed in one pane.
             *
             * For identification only the {@link ResourceId} is used, so for some methods of the {@link XTabBar} interface only the {@link ResourceId} member is
             * evaluated.
             */
            interface TabBarButton {
                /**
                 * This label is displayed on the UI as button text.
                 *
                 * The label is expected to be localized.
                 */
                ButtonLabel: string;

                /** The localized help text that may be displayed in a tool tip. */
                HelpText: string;

                /**
                 * {@link XResourceId} object of the resource that is requested to be displayed when the tab bar button is activated.
                 *
                 * For some methods of the {@link XTabBar} interface only this member is evaluated. That is because only this member is used to identify a tab bar
                 * button.
                 */
                ResourceId: XResourceId;
            }

            /**
             * A configuration describes the resources of an application like panes, views, and tool bars and their relationships that are currently active or are
             * requested to be activated. Resources are specified by {@link ResourceId} structures rather than references so that not only the current configuration
             * but also a requested configuration can be represented.
             *
             * Direct manipulation of a configuration object is not advised with the exception of the {@link ConfigurationController} and objects that implement the
             * {@link XConfigurationChangeRequest} interface.
             * @see XConfigurationController
             */
            interface XConfiguration extends util.XCloneable {
                /**
                 * Add a resource to the configuration.
                 *
                 * This method should be used only by objects that implement the XConfigurationRequest interface or by the configuration controller.
                 * @param xResourceId The resource to add to the configuration. When the specified resource is already part of the configuration then this call is silently
                 * @throws IllegalArgumentException When an empty resource id is given then an IllegalArgumentException is thrown.
                 */
                addResource(xResourceId: XResourceId): void;

                /**
                 * Returns the list of resources that are bound directly and/or indirectly to the given anchor. A URL filter can reduce the set of returned resource ids.
                 * @param xAnchorId This anchor typically is either a pane or an empty {@link XResourceId} object. An empty reference is treated like an {@link XResourceId
                 * @param sTargetURLPrefix When a non-empty string is given then resource ids are returned only when their resource URL matches this prefix, i.e. when it b
                 * @param eSearchMode This flag defines whether to return only resources that are directly bound to the given anchor or a recursive search is to be made. N
                 * @returns The set of returned resource ids may be empty when there are no resource ids that match all conditions. The resources in the sequence are ordered
                 */
                getResources(
                    xAnchorId: XResourceId,
                    sTargetURLPrefix: string,
                    eSearchMode: AnchorBindingMode,
                ): SafeArray<XResourceId>;

                /**
                 * Returns whether the specified resource is part of the configuration.
                 *
                 * This is independent of whether the resource does really exist and is active, i.e. has a visible representation in the GUI.
                 * @param xResourceId The id of a resource. May be empty (empty reference or empty {@link XResourceId} object) in which case `FALSE` is returned.
                 * @returns Returns `TRUE` when the resource is part of the configuration and `FALSE` when it is not.
                 */
                hasResource(xResourceId: XResourceId): boolean;

                /**
                 * Remove a resource from the configuration.
                 *
                 * This method should be used only by objects that implement the XConfigurationRequest interface or by the configuration controller.
                 * @param xResourceId The resource to remove from the configuration. When the specified resource is not part of the configuration then this call is silentl
                 * @throws IllegalArgumentException When an empty resource id is given then an IllegalArgumentException is thrown.
                 */
                removeResource(xResourceId: XResourceId): void;
            }

            /** A listener for configuration changes is called when it has been registered at the configuration controller and a configuration change occurs. */
            interface XConfigurationChangeListener extends lang.XEventListener {
                /**
                 * The exact time of when a listener is called (before the change takes place, during the change, or when the change has been made) depends on the change
                 * event. The order in which listeners are called is the order in which they are registered (First registered, first called.)
                 */
                notifyConfigurationChange(aEvent: ConfigurationChangeEvent): void;
            }

            /**
             * A single explicit request for a configuration change.
             *
             * The requested change is committed to a configuration only when the {@link execute()} method is called. {@link Configuration} change requests are
             * executed asynchronously. This is done to avoid reentrance problems with objects that are registered as {@link XConfigurationChangeListener} and at the
             * same time make configuration change requests. When the requests were executed synchronously then the listeners would be notified of the changes while
             * their request call has not yet returned.
             *
             * This interface is typically used internally by the {@link XConfigurationController}
             * @see XConfigurationController
             */
            interface XConfigurationChangeRequest {
                /**
                 * Commit the configuration change request represented by the called object to the given configuration.
                 * @param xConfiguration This is the configuration to commit the requested change to.
                 */
                execute(xConfiguration: XConfiguration): void;
            }

            /**
             * The configuration controller is responsible for the management of the set of active resources.
             *
             * There are two configurations of resources: The current configuration contains the set of currently active resources.The requested configuration
             * describes what the current configuration should be. The requested configuration is changed usually by calling {@link requestResourceActivation()} and
             * {@link requestResourceDeactivation()} .
             *
             * When the two configurations differ then the current configuration is updated eventually to reflect the requested configuration. An update takes place
             * when the following three conditions are fulfilled.  1. when the last pending request for configuration changes has been processed, 2. when the {@link
             * update()} method is called. 3. when the configuration manager it is unlocked after formerly being locked.
             *
             * Requests for configuration changes are handled in a two step process:  1. First the requested configuration is updated iteratively: Every request that
             * is being made by calling {@link requestResourceActivation()} or {@link requestResourceDeactivation()} results in one or more function objects, that
             * each implement the {@link XConfigurationChangeRequest} interface. These are inserted into a queue. The request objects in the queue are processed
             * asynchronously one at a time in the order in which they are inserted. Only when one request object is processed a change to the requested
             * configuration is made. These changes are broadcasted to registered {@link XConfigurationChangeListener} objects. Listeners may decide to make requests
             * that then are added to the queue. For example when the view in the center pane is replaced by another view, some listeners may want to turn some side
             * panes on or off, or show other views in the side panes.
             *
             * This process goes on until the queue of request objects becomes empty. Until this point only the requested configuration has been modified. No
             * resources have been activated or deactivated.
             *
             *  2.
             *
             * The second update step activates or deactivates resources so that the current configuration (the one that comprises the actually active resources)
             * reflects the requested configuration.
             *
             * The order in which resources are activated or deactivated depends on the dependency between the resources. For example a view depends on the pane it
             * is displayed in. Resources that other resources depend on are activated first and deactivated last. The order is undefined for unrelated resources.
             *
             * Note that the second update step may not be able to activate (or even to deactivate) all the requested resources. Either because they are temporarily
             * or permanently unavailable. For example, during the start-up of a new Impress application the side panes are displayed with a visible delay because
             * they are not provided sooner by the underlying framework. Such unavailable resources are not forgotten but remain in the requested configuration.
             * Every time the configuration controller updates its current configuration these resources are requested once more.
             *
             * The configuration controller sends the following events: ResourceActivationRequested is sent when the activation of a resource has been requested and
             * the resource is not yet active in the requested configuration. The event is sent when the configuration change request is executed, not when the
             * {@link requestResourceActivation()} call is made.
             *
             * The {@link ConfigurationChangeEvent.ResourceId} member is set to the requested resource. The ResourceObject member is not set.
             *
             * ResourceDeactivationRequested is sent when the deactivation of a resource has been requested and the resource is active in the requested
             * configuration. The event is sent when the configuration change request is executed that is created when for example {@link
             * requestResourceDeactivation()} is called.
             *
             * The {@link ResourceId} member is set to the requested resource. The ResourceObject member is not set.
             *
             * ConfigurationUpdateStart is sent before the update of the current configuration starts.
             *
             * The requested configuration is available in the {@link ConfigurationChangeEvent.Configuration} member. The {@link ResourceId} and ResourceObject
             * members are not set.
             *
             * ConfigurationUpdateEnd is sent after the update of the current configuration ends.
             *
             * The requested configuration is available in the {@link ConfigurationChangeEvent.Configuration} member. The {@link ResourceId} and ResourceObject
             * members are not set.
             *
             * ResourceActivation is sent when a resource is activated, i.e. when a new object of a resource is created (or taken from a cache).
             *
             * The {@link ResourceId} and ResourceObject members are set to the {@link XResourceId} and object reference of the activated resource.
             *
             * ResourceDeactivation is sent when a resource is deactivated, i.e. when an object that previously was part of the configuration is removed from the
             * configuration.
             *
             * The {@link ResourceId} and ResourceObject members are set to {@link XResourceId} and object reference of the deactivated resource.
             */
            interface XConfigurationController
                extends
                    XConfigurationControllerRequestQueue,
                    XConfigurationControllerBroadcaster,
                    XResourceFactoryManager
            {
                /**
                 * Return a copy of the current configuration.
                 *
                 * Modifications to the returned configuration have no effect on the drawing framework.
                 */
                readonly CurrentConfiguration: XConfiguration;

                /**
                 * Return a copy of the current configuration.
                 *
                 * Modifications to the returned configuration have no effect on the drawing framework.
                 */
                getCurrentConfiguration(): XConfiguration;

                /**
                 * Return a copy of the requested configuration.
                 *
                 * Modifications to the returned configuration have no effect on the drawing framework.
                 */
                getRequestedConfiguration(): XConfiguration;

                /**
                 * Return the active resource specified by the given resource id.
                 * @param xResourceId A valid resource id. This should, but does not have to be, the resource id of an active resource.
                 * @returns When the given resource id specifies an active resource then that resource is returned. Otherwise an empty reference is returned.
                 */
                getResource(xResourceId: XResourceId): XResource;

                /**
                 * Lock the processing of configuration change requests.
                 *
                 * This is only necessary when more than one change request is being made in a row. It prevents an update being made (with all the visible UI changes)
                 * before all change requests are being made.
                 *
                 * Recursive {@link lock()} calls are recognized: the configuration controller is locked while {@link lock()} was called more often than {@link unlock()}
                 * .
                 */
                lock(): void;

                /**
                 * Return a copy of the requested configuration.
                 *
                 * Modifications to the returned configuration have no effect on the drawing framework.
                 */
                readonly RequestedConfiguration: XConfiguration;

                /**
                 * Request the activation of a resource.
                 *
                 * The request is processed asynchronously. Notifications about configuration changes are sent after this call returns.
                 * @param xResourceId The resource whose activation is requested.
                 * @param eMode  When eMode is REPLACE then, before adding the resource activation to the request queue, similar resources linked to the same anchor are re
                 */
                requestResourceActivation(xResourceId: XResourceId, eMode: ResourceActivationMode): void;

                /**
                 * Request the deactivation of a resource.
                 *
                 * The request is processed asynchronously. Notifications about configuration changes are sent after this call returns.
                 *
                 * Requesting the deactivation of a resource that is not active is not an error.
                 * @param xResourceId The resource whose deactivation is requested.
                 */
                requestResourceDeactivation(xResourceId: XResourceId): void;

                /**
                 * Replace the requested configuration with the given configuration and schedule an update of the current configuration.
                 *
                 * Together with the {@link getCurrentConfiguration()} and {@link getRequestedConfiguration()} methods this allows the saving and restoring of
                 * configurations. However, the given configuration can have other origins then these methods.
                 *
                 * The given configuration is transformed into a list of change requests so that the resulting requested configuration equals the given configuration.
                 * This has the advantage that not only the resource activations and deactivations but all configuration changes are properly broadcasted.
                 *
                 * Note that because of the configuration change notifications listeners can make more configuration change requests, so that the resulting requested
                 * configuration can be different from the given configuration.
                 * @param xConfiguration This typically is a configuration that was obtained with an earlier {@link getRequestedConfiguration()} call.
                 */
                restoreConfiguration(xConfiguration: XConfiguration): void;

                /**
                 * Unlock the processing of configuration change requests.
                 *
                 * When {@link unlock()} is called as many times as {@link lock()} and the queue of configuration change requests is not empty the configuration
                 * controller continues the processing of the change requests. An update of the current configuration will eventually being made.
                 */
                unlock(): void;

                /**
                 * Explicitly request an update of the current configuration.
                 *
                 * Call it when a resource is activated or deactivated without the control and knowledge of the drawing framework. Calling this method (from outside the
                 * drawing framework) should hardly every be necessary.
                 */
                update(): void;
            }

            /**
             * Manage the set of registered event listeners and the event notification for a configuration controller.
             *
             * The listeners are called in the order in which they are registered.
             */
            interface XConfigurationControllerBroadcaster {
                /**
                 * Add a new listener for configuration changes.
                 *
                 * The listener is notified only for the specified type of configuration changes. When the listener is interested in more than one event type this method
                 * has to be called multiple times. Alternatively it can register as universal listener that will be called for all event types. However, this option is
                 * provided primarily to support debugging and monitoring.
                 * @param xListener The new listener.
                 * @param sEventType The event type that the listener is interested in. The set of event types is not fixed and there can be no exhaustive list. The empty
                 * @param aUserData Arbitrary data that is passed to the listener when it is called for the specified event type. When one listener is registered for more
                 */
                addConfigurationChangeListener(
                    xListener: XConfigurationChangeListener,
                    sEventType: string,
                    aUserData: any,
                ): void;

                /** With this method other objects can send events to all the registered listeners. */
                notifyEvent(aEvent: ConfigurationChangeEvent): void;

                /**
                 * Remove a listener for configuration changes.
                 * @param xListener The listener that is to be removed.
                 */
                removeConfigurationChangeListener(xListener: XConfigurationChangeListener): void;
            }

            /**
             * The request queue of the configuration controller handles requests for changes to the current configuration.
             *
             * This interface allows callers to add requests to the back of the queue and to determine whether the queue is empty. Using this interface should
             * normally not be necessary for anyone else than the {@link XConfigurationController} . It may be removed in the future.
             */
            interface XConfigurationControllerRequestQueue {
                /**
                 * Return whether there are pending requests for configuration changes.
                 * @returns Returns `TRUE` when there is at least one request object in the queue that has not yet been processed. It returns `FALSE` when the queue is empty.
                 */
                hasPendingRequests(): boolean;

                /**
                 * Add a request for a configuration change to the request queue.
                 *
                 * This method should not be called from outside the drawing framework. Other sub controllers of the drawing framework are typical callers. They can add
                 * change requests that can not be made with the requestResourceActivation() and requestResourceDeactivation() methods.
                 * @param xRequest The configuration change represented by this request object must only be committed to the configuration when the {@link com.sun.star.dra
                 */
                postChangeRequest(xRequest: XConfigurationChangeRequest): void;
            }

            /**
             * The {@link XControllerManager} gives access to the controllers of the drawing framework.
             *
             * The {@link XControllerManager} interface is typically implemented by the same object that implements {@link com.sun.star.frame.XController} .
             */
            interface XControllerManager {
                /**
                 * Return the {@link XConfigurationController} object.
                 * @returns The returned reference is never empty.
                 */
                readonly ConfigurationController: XConfigurationController;

                /**
                 * Return the {@link XConfigurationController} object.
                 * @returns The returned reference is never empty.
                 */
                getConfigurationController(): XConfigurationController;

                /**
                 * Return the {@link XModuleController} object.
                 * @returns The returned reference is never empty.
                 */
                getModuleController(): XModuleController;

                /**
                 * Return the {@link XModuleController} object.
                 * @returns The returned reference is never empty.
                 */
                readonly ModuleController: XModuleController;
            }

            /**
             * The module controller is responsible for loading a module (ad-don, plugin, whatever the name) when it is first used.
             *
             * For this there is a list in the office configuration which associates resource URLs with service names which in turn are associated with modules (or
             * dlls). The path to the office configuration list is MultiPaneGUI/Framework/ResourceFactories in the Impress.xcu file.
             */
            interface XModuleController {
                /** When the specified resource is requested for the first time then create a new instance of the associated factory service. */
                requestResource(sResourceTypeURL: string): void;
            }

            /**
             * A pane is an abstraction of a window and is one of the resources managed by the drawing framework.
             *
             * Apart from the area that displays a view a pane may contain other parts like title, menu, closer button.
             *
             * The URL prefix of panes is `private:resource/floater`
             */
            interface XPane extends XResource {
                /**
                 * Return the com::sun::star::awt::XCanvas of the pane. The {@link com.sun.star.rendering.XCanvas} object is expected to be associated with the {@link
                 * com.sun.star.awt.XWindow} object returned by {@link getWindow()} .
                 * @returns When the {@link com.sun.star.rendering.XCanvas} interface is not supported then an empty reference is returned.
                 */
                readonly Canvas: rendering.XCanvas;

                /**
                 * Return the com::sun::star::awt::XCanvas of the pane. The {@link com.sun.star.rendering.XCanvas} object is expected to be associated with the {@link
                 * com.sun.star.awt.XWindow} object returned by {@link getWindow()} .
                 * @returns When the {@link com.sun.star.rendering.XCanvas} interface is not supported then an empty reference is returned.
                 */
                getCanvas(): rendering.XCanvas;

                /** Return the {@link com.sun.star.awt.XWindow} of the pane that is used to display a view. */
                getWindow(): awt.XWindow;

                /** Return the {@link com.sun.star.awt.XWindow} of the pane that is used to display a view. */
                readonly Window: awt.XWindow;
            }

            /**
             * An extension of the {@link XPane} interface that adds support for a) showing and hiding the windows that internally belong to the pane and b) setting
             * the accessibility object. This is typically an optional interface.
             */
            interface XPane2 {
                /** Return the accessibility object that is currently associated with the windows that implement the pane. */
                Accessible: accessibility.XAccessible;

                /** Return the accessibility object that is currently associated with the windows that implement the pane. */
                getAccessible(): accessibility.XAccessible;

                /**
                 * Return whether all windows that are used to implement the pane are visible.
                 * @returns `TRUE` when all windows of the pane are visible.
                 */
                isVisible(): boolean;

                /**
                 * Set the accessibility object for the pane. When there is more than one window used to implement the pane then the given accessibility object is
                 * usually set at the topmost window. However, the details are implementation dependent.
                 * @param xAccessible May be an empty reference.
                 */
                setAccessible(xAccessible: accessibility.XAccessible): void;

                /**
                 * Hide or show the pane. If there is more than one window used to implement the pane then it is left to the implementation if one, some, or all windows
                 * are hidden or shown as long as the pane becomes hidden or visible.
                 * @param bIsVisible When `TRUE` then show the pane. Hide it otherwise.
                 */
                setVisible(bIsVisible: boolean): void;
            }

            /**
             * Paint the border around a rectangular region, typically a pane.
             *
             * Calling objects have to be able to derive inner bounding boxes of the border from the outer ones and inner ones from outer ones. This conversion and
             * the painting of the border involves three rectangles. The inner and outer bounding box of the border. This is a logical bounding box which the paint
             * methods may paint over. The center box is the third rectangle. This is the actual border between outer and inner background color or bitmap and it is
             * used for placing the bitmaps that are used paint the border. The inner sides and corners are places relative to this center box, i.e. when not further
             * offsets are given then the upper left corner bitmap is painted with its lower right at the upper left of the center box.
             */
            interface XPaneBorderPainter {
                /**
                 * Enlarge the given rectangle by the size of the specified part of the border. This method can be used to convert an inner bounding box into the center
                 * box or the outer bounding box.
                 * @param sPaneBorderStyleName The pane style defines the sizes of the border.
                 * @param aRectangle This rectangle will be converted into a larger one. This should be the center box or the inner bounding box of the border.
                 * @param eBorderType The part of the border to add to the given rectangle. Use INNER_BORDER to convert an inner bounding box into the center box or TOTAL_
                 */
                addBorder(
                    sPaneBorderStyleName: string,
                    aRectangle: awt.Rectangle,
                    eBorderType: BorderType,
                ): awt.Rectangle;

                /**
                 * Return the offset of a call out anchor with respect to the outer border. This value is used when the call out is realized by a fixed bitmap in order
                 * to determine the size and/or location of the outer border for a given call out.
                 */
                getCalloutOffset(sPaneBorderStyleName: string): awt.Point;

                /**
                 * Paint the border around a pane.
                 * @param sPaneBorderStyleName The pane style to use for painting the border.
                 * @param xCanvas The canvas onto which the border is painted.
                 * @param aOuterBorderRectangle The outer bounding box of the border. Use addBorder to convert the bounding box of a pane (the inner bounding box of the bo
                 * @param aRepaintArea The area in which the border has to be repainted. The clip rectangle.
                 * @param sTitle The pane title. Supply an empty string for panes without title. It is the responsibility of the caller to supply a title only for pane bor
                 */
                paintBorder(
                    sPaneBorderStyleName: string,
                    xCanvas: rendering.XCanvas,
                    aOuterBorderRectangle: awt.Rectangle,
                    aRepaintArea: awt.Rectangle,
                    sTitle: string,
                ): void;

                /**
                 * Paint the border around a pane where the border includes a call out that is anchored at the given point. Most arguments have the same meaning as in
                 * the {@link paintBorder()} .
                 * @param sPaneBorderStyleName See description in {@link paintBorder} .
                 * @param xCanvas See description in {@link paintBorder} .
                 * @param aOuterBorderRectangle See description in {@link paintBorder} .
                 * @param aRepaintArea See description in {@link paintBorder} .
                 * @param sTitle See description in {@link paintBorder} .
                 * @param aCalloutAnchor The anchor point of the call out. It is usually located outside the border.
                 * @see paintBorder
                 */
                paintBorderWithCallout(
                    sPaneBorderStyleName: string,
                    xCanvas: rendering.XCanvas,
                    aOuterBorderRectangle: awt.Rectangle,
                    aRepaintArea: awt.Rectangle,
                    sTitle: string,
                    aCalloutAnchor: awt.Point,
                ): void;

                /**
                 * Shrink the given rectangle by the size of the specified part of the border. This method can be used to convert an outer bounding box into the center
                 * box or the inner bounding box.
                 * @param sPaneBorderStyleName The pane style defines the sizes of the border.
                 * @param aRectangle This rectangle will be converted into a smaller one that lies inside it. It should be the center box or the outer bounding box of the
                 * @param eBorderType The part of the border to remove from the given rectangle. Use OUTER_BORDER to convert an outer bounding box into the center box or T
                 */
                removeBorder(
                    sPaneBorderStyleName: string,
                    aRectangle: awt.Rectangle,
                    eBorderType: BorderType,
                ): awt.Rectangle;
            }

            /** An optional interface that is implemented by resources that are relocatable to different anchors. */
            interface XRelocatableResource {
                /**
                 * Replace the current anchor of the called resource with the given one.
                 * @param xNewAnchor The new anchor.
                 * @returns Returns `TRUE` when the relocation was successful.
                 */
                relocateToAnchor(xNewAnchor: XResource): boolean;
            }

            /** Base interface that provides functionality shared by all resource types of the drawing framework. */
            interface XResource {
                /** Return an {@link XResourceId} object for the called resource. The returned id unambiguously identifies the resource. */
                getResourceId(): XResourceId;

                /**
                 * Some resources must not be leafs, i.e. have to be anchor to at least one other resource. Most panes are examples for this. Views on the other hand are
                 * in most cases no anchors. So the typical pane will return `TRUE` and the typical view will return `FALSE` .
                 *
                 * The return value is used to determine whether a resource has to be deactivated when it has no children, either because none is requested or because
                 * none can be created.
                 */
                isAnchorOnly(): boolean;

                /** Return an {@link XResourceId} object for the called resource. The returned id unambiguously identifies the resource. */
                readonly ResourceId: XResourceId;
            }

            /**
             * Factory and possibly cache for creating and releasing resources.
             *
             * A resource factory is created and used by the {@link XConfigurationController} object.
             *
             * A factory may want to implement a cache to reuse previously released resources.
             */
            interface XResourceFactory {
                /**
                 * Create a resource for the given {@link XResourceId} object.
                 * @param xResourceId The resource URL of this id specifies the type of resource to create. The anchor can be used to obtain the associated object from the
                 * @returns Returns a resource object that has been just created or was taken from a cache. When the requested resource can not be created then an empty refe
                 * @throws InvalidArgumentException when the given URL is not supported by the factory.
                 */
                createResource(xResourceId: XResourceId): XResource;

                /**
                 * Call this method to tell a factory that the given resource is no longer in use. The factory can decide whether to destroy the resource or to keep it
                 * in a cache in order to reuse it later.
                 * @param xResource The given resource has to be one created by the same factory.
                 * @throws InvalidArgumentException when the given pane was not created by the same factory.
                 */
                releaseResource(xResource: XResource): void;
            }

            /**
             * The {@link XResourceFactoryManager} is part of the configuration controller and manages the set of registered resource factories.
             * @see XConfigurationController
             * @see XResourceFactory
             */
            interface XResourceFactoryManager {
                /**
                 * Register a new resource factory for the given URL.
                 *
                 * When one factory is responsible for more than one type of resource then this method has to be called for each type. If this method is called multiple
                 * times for the same URL then a previously registered factory is removed for the URL.
                 * @param sResourceURL The URL of the resource that the factory can create.
                 * @param xResourceFactory The resource factory object.
                 */
                addResourceFactory(sResourceURL: string, xResourceFactory: XResourceFactory): void;

                /**
                 * Return the resource factory that was previously registered for the given resource type. This method is typically called by one of the resource
                 * controllers.
                 * @param sResourceURL The URL of the resource type for which to return the resource factory.
                 * @returns When no resource factory was registered for the given resource type then an empty reference is returned.
                 */
                getResourceFactory(sResourceURL: string): XResourceFactory;

                /**
                 * Remove a resource factory for all resource types it has been registered for. Use {@link removeResourceFactoryForURL()} to remove a factory just for
                 * one resource type and to leave it registered for others.
                 * @param xResourceFactory The resource factory object to remove.
                 */
                removeResourceFactoryForReference(xResourceFactory: XResourceFactory): void;

                /**
                 * Remove a resource factory for one type of resource. When the factory has been registered for other URLs as well then it remains registered for them.
                 * Use the {@link removeResourceFactoryForReference()} to remove a factory completely.
                 * @param sResourceURL The URL for which to remove the resource factory.
                 */
                removeResourceFactoryForURL(sResourceURL: string): void;
            }

            /**
             * A resource id uses a set of URLs to unambiguously specify a resource of the drawing framework.
             *
             * Resources of the drawing framework are panes, views, tool bars, and command groups. One URL describes the type of the actual resource. A sequence of
             * URLs (typically one, sometimes two) specifies its anchor, the resource it is bound to. The anchor typically is a pane (for views), or it is empty (for
             * panes).
             *
             * The resource URL may be empty. In this case the anchor is empty, too. Such an empty resource id does not describe a resource but rather the absence of
             * one. Instead of an empty {@link XResourceId} object an empty reference can be used in many places.
             *
             * The resource URL may have arguments that are passed to the factory method on its creation. Arguments are only available through the {@link
             * getFullResourceURL()} . The {@link getResourceURL()} method strips them away.
             */
            interface XResourceId {
                /** Return a new {@link XResourceId} that represents the anchor resource. */
                readonly Anchor: XResourceId;

                /**
                 * Return the, possibly empty, list of anchor URLs. The URLs are ordered so that the one in position 0 is the direct anchor of the resource, while the
                 * one in position i+1 is the direct anchor of the one in position i.
                 */
                readonly AnchorURLs: SafeArray<string>;

                /** Return a copy of the called resource id. The caller becomes the owner of the new object. */
                clone(): XResourceId;

                /**
                 * Compare the called {@link XResourceId} object with the given one.
                 *
                 * The two resource ids A and B are compared so that if A<B (return value is -1) then either A and B are unrelated or A is a direct or indirect anchor of
                 * B.
                 *
                 * The algorithm for this comparison is quite simple. It uses a double lexicographic ordering. On the lower level individual URLs are compared via the
                 * lexicographic order defined on strings. On the higher level two resource ids are compared via a lexicographic order defined on the URLS. So when there
                 * are two resource ids A1.A2 (A1 being the anchor of A2) and B1.B2 then A1.A2<B1.B2 when A1<B1 or A1==B1 and A2<B2. Resource ids may have different
                 * lengths: A1 < B1.B2 when A1<B1 or A1==B1 (anchors first then resources linked to them.
                 * @param xId The resource id to which the called resource id is compared.
                 * @returns Returns 0 when the called resource id is equivalent to the given resource id. Returns `-1` or `+1` when the two compared resource ids differ.
                 */
                compareTo(xId: XResourceId): number;

                /** Return an URL object of the resource URL that may contain arguments. */
                readonly FullResourceURL: util.URL;

                /** Return a new {@link XResourceId} that represents the anchor resource. */
                getAnchor(): XResourceId;

                /**
                 * Return the, possibly empty, list of anchor URLs. The URLs are ordered so that the one in position 0 is the direct anchor of the resource, while the
                 * one in position i+1 is the direct anchor of the one in position i.
                 */
                getAnchorURLs(): SafeArray<string>;

                /** Return an URL object of the resource URL that may contain arguments. */
                getFullResourceURL(): util.URL;

                /** Return the type prefix of the resource URL. This includes all up to and including the second slash. */
                getResourceTypePrefix(): string;

                /** Return the URL of the resource. Arguments supplied on creation are stripped away. Use {@link getFullResourceURL()} to access them. */
                getResourceURL(): string;

                /** Return whether there is a non-empty anchor URL. When this method returns `FALSE` then {@link getAnchorURLs()} will return an empty list. */
                hasAnchor(): boolean;

                /**
                 * Return whether the anchor of the called resource id object represents the same resource as the given object.
                 *
                 * Note that not only the anchor of the given object is taken into account. The whole object, including the resource URL, is interpreted as anchor
                 * resource.
                 * @param xAnchorId The resource id of the anchor.
                 * @param eMode This mode specifies how the called resource has to be bound to the given anchor in order to have this function return `TRUE` . If eMode is
                 */
                isBoundTo(xAnchorId: XResourceId, eMode: AnchorBindingMode): boolean;

                /**
                 * Return whether the anchor of the called resource id object represents the same resource as the given anchor URL. This is a convenience variant of the
                 * {@link isBoundTo()} function that can also be seen as an optimization for the case that the anchor consists of exactly one URL.
                 * @param AnchorURL The resource URL of the anchor.
                 * @param eMode This mode specifies how the called resource has to be bound to the given anchor in order to have this function return. See the description
                 */
                isBoundToURL(AnchorURL: string, eMode: AnchorBindingMode): boolean;

                /** Return the type prefix of the resource URL. This includes all up to and including the second slash. */
                readonly ResourceTypePrefix: string;

                /** Return the URL of the resource. Arguments supplied on creation are stripped away. Use {@link getFullResourceURL()} to access them. */
                readonly ResourceURL: string;
            }

            /**
             * UI control for the selection of views in a pane.
             *
             * Every tab of a tab bar has, besides its localized title and help text, the URL of a view. A possible alternative would be to use a command URL instead
             * of the view URL.
             *
             * In the current Impress implementation a tab bar is only used for the center pane to switch between views in the center pane. Tab bars can make sense
             * for other panes as well, i.e. for showing either the slide sorter or the outline view in the left pane.
             *
             * Tab bar buttons are identified by their resource id. Note that because the resource anchors are all the same (the tab bar), it is the resource URL
             * that really identifies a button. There can not be two buttons with the same resource id.
             *
             * A better place for this interface (in an extended version) would be `com::sun::star::awt`
             * @see TabBarButton
             */
            interface XTabBar {
                /**
                 * Add a tab bar button to the right of another one.
                 * @param aButton The new tab bar button that is to be inserted. If a button with the same resource id is already present than that is removed before the n
                 * @param aAnchor The new button is inserted to the right of this button. When its {@link ResourceId} is empty then the new button is inserted at the left
                 */
                addTabBarButtonAfter(aButton: TabBarButton, aAnchor: TabBarButton): void;

                /**
                 * Add a tab bar button at the right most position.
                 * @param aButton The new tab bar button that is to be inserted.
                 */
                appendTabBarButton(aButton: TabBarButton): void;

                /**
                 * Return a sequence of all the tab bar buttons.
                 *
                 * Their order reflects the visible order in the tab bar.
                 *
                 * This method can be used when {@link addTabBarButtonAfter()} does not provide enough control as to where to insert a new button.
                 */
                getTabBarButtons(): SafeArray<TabBarButton>;

                /**
                 * Test whether the specified button exists in the tab bar.
                 * @param aButton The tab bar button whose existence is tested.
                 * @returns Returns `TRUE` when the button exists.
                 */
                hasTabBarButton(aButton: TabBarButton): boolean;

                /**
                 * Remove a tab bar button.
                 * @param aButton The tab bar button to remove. When there is no button with the specified resource id then this call is silently ignored.
                 */
                removeTabBarButton(aButton: TabBarButton): void;

                /**
                 * Return a sequence of all the tab bar buttons.
                 *
                 * Their order reflects the visible order in the tab bar.
                 *
                 * This method can be used when {@link addTabBarButtonAfter()} does not provide enough control as to where to insert a new button.
                 */
                readonly TabBarButtons: SafeArray<TabBarButton>;
            }
        }

