        /**
         * serves state information of objects which can be connected to controls (e.g. toolbox controls).
         *
         * Each state change is to be broadcasted to all registered status listeners. The first notification should be performed synchronously from {@link
         * XDispatch.addStatusListener()} ; if not, controls may flicker. State listener must be aware of this synchronous notification.
         *
         * The state consists of enabled/disabled and a short descriptive text of the function (e.g. "undo insert character"). It is to be broadcasted whenever
         * this state changes or the control should re-get the value for the URL it is connected to. Additionally, a context-switch-event is to be broadcasted
         * whenever the object may be out of scope, to force the state listener to requery the {@link XDispatch} .
         * @see Frame
         * @see FeatureStateEvent
         */
        interface XDispatch extends uno.XInterface {
            /**
             * registers a listener of a control for a specific URL at this object to receive status events.
             *
             * It is only allowed to register URLs for which this {@link XDispatch} was explicitly queried. Additional arguments ("#..." or "?...") will be ignored.
             *
             * Note: Notifications can't be guaranteed! This will be a part of interface {@link XNotifyingDispatch} .
             * @param Control listener that wishes to be informed
             * @param URL the URL (without additional arguments) the listener wishes to be registered for. A listener can be registered for more than one URL at the sa
             * @see XStatusListener
             * @see XDispatch.removeStatusListener()
             */
            addStatusListener(Control: XStatusListener, URL: util.URL): void;

            /**
             * dispatches (executes) an URL
             *
             * It is only allowed to dispatch URLs for which this {@link XDispatch} was explicitly queried. Additional arguments ("'#..." or "?...") are allowed.
             * @param URL fully parsed URL describing the feature which should be dispatched (=executed)
             * @param Arguments optional arguments for this request (see {@link com.sun.star.document.MediaDescriptor} ) They depend on the real implementation of the
             */
            dispatch(URL: util.URL, Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>): void;

            /**
             * unregisters a listener from a control.
             * @param Control listener that wishes to be unregistered
             * @param URL URL the listener was registered for. Additional arguments ("#..." or "?...") will be ignored.
             * @see XStatusListener
             * @see XDispatch.addStatusListener()
             */
            removeStatusListener(Control: XStatusListener, URL: util.URL): void;
        }

        /**
         * provides an easy way to dispatch functions useful at UI level.
         * @see XDispatch
         * @since OOo 1.1.2
         */
        interface XDispatchHelper extends uno.XInterface {
            /**
             * executes the dispatch.
             *
             * Listeners are not supported here!
             * @param DispatchProvider points to the provider, which should be asked for valid dispatch objects
             * @param URL describes the feature which should be supported by internally used dispatch object
             * @param TargetFrameName specifies the frame which should be the target for this request
             * @param SearchFlags optional search parameter for finding the frame if no special **TargetFrameName** was used
             * @param Arguments optional arguments for this request They depend on the real implementation of the dispatch object.
             * @returns A possible result of the executed internal dispatch. The information behind this `any` depends on the dispatch!
             * @see XDispatch.dispatch()
             */
            executeDispatch(
                DispatchProvider: XDispatchProvider,
                URL: string,
                TargetFrameName: string,
                SearchFlags: number,
                Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>,
            ): any;
        }

        /**
         * provides information about supported commands
         *
         * This interface can be used to retrieve additional information about supported commands. This interface is normally used by configuration
         * implementations to retrieve all supported commands. A dispatch information provider is normally supported by a {@link Frame} service.
         * @see Frame
         * @since OOo 2.0
         */
        interface XDispatchInformationProvider extends uno.XInterface {
            /**
             * returns additional information about supported commands of a given command group.
             * @param CommandGroup specifies a command group.
             * @returns name and group name of every command supported. A group ID which is not supported returns an empty com::sun::star::uno::Sequence.
             */
            getConfigurableDispatchInformation(CommandGroup: number): SafeArray<DispatchInformation>;

            /**
             * returns all supported command groups.
             * @returns a sequence of supported command groups.
             * @see CommandGroup
             */
            getSupportedCommandGroups(): SafeArray<number>;

            /**
             * returns all supported command groups.
             * @returns a sequence of supported command groups.
             * @see CommandGroup
             */
            readonly SupportedCommandGroups: SafeArray<number>;
        }

        /**
         * provides {@link XDispatch} interfaces for certain functions which are useful at the UI.
         * @see XDispatch
         */
        interface XDispatchProvider extends uno.XInterface {
            /**
             * searches for an {@link XDispatch} for the specified URL within the specified target frame.
             * @param URL describe the feature which should be supported by returned dispatch object
             * @param TargetFrameName specify the frame which should be the target for this request
             * @param SearchFlags optional search parameter for finding the frame if no special **TargetFrameName** was used
             * @returns the dispatch object which provides queried functionality ;  or `NULL` if no dispatch object is available
             * @see XFrame.findFrame()
             * @see XDispatchProvider.queryDispatches()
             */
            queryDispatch(URL: util.URL, TargetFrameName: string, SearchFlags: number): XDispatch;

            /**
             * actually this method is redundant to {@link XDispatchProvider.queryDispatch()} to avoid multiple remote calls.
             * @param Requests list of dispatch requests
             * @returns multiple dispatch interfaces for the specified descriptors at once  It's not allowed to pack it - because every request must match to its real re
             */
            queryDispatches(Requests: LibreOffice.SeqEquiv<DispatchDescriptor>): SafeArray<XDispatch>;
        }

        /**
         * makes it possible to register an {@link XDispatchProvider} which intercepts all requests of {@link XDispatch} to this instance.
         *
         * Note: Nobody can guarantee order of used interceptor objects if more than ones exist. Later registered ones will be used at first. But it's possible
         * to increase the chance for that by providing the optional interface {@link XInterceptorInfo} .
         * @see XDispatchProvider
         * @see XDispatch
         * @see XInterceptorInfo
         */
        interface XDispatchProviderInterception extends uno.XInterface {
            /**
             * registers an {@link XDispatchProviderInterceptor} , which will become the first interceptor in the chain of registered interceptors.
             * @param Interceptor the interceptor which wishes to be registered
             * @see XDispatchProviderInterception.releaseDispatchProviderInterceptor()
             */
            registerDispatchProviderInterceptor(Interceptor: XDispatchProviderInterceptor): void;

            /**
             * removes an {@link XDispatchProviderInterceptor} which was previously registered
             *
             * The order of removals is arbitrary. It is not necessary to remove the last registered interceptor first.
             * @param Interceptor the interceptor which wishes to be unregistered
             * @see XDispatchProviderInterception.registerDispatchProviderInterceptor()
             */
            releaseDispatchProviderInterceptor(Interceptor: XDispatchProviderInterceptor): void;
        }

        /**
         * makes it possible to intercept request of {@link XDispatch} .
         *
         * Can be registered as an interceptor by using interface {@link XDispatchProviderInterception} .
         * @see XDispatchProviderInterception
         */
        interface XDispatchProviderInterceptor extends XDispatchProvider {
            /**
             * access to the master {@link XDispatchProvider} of this interceptor
             * @returns the master of this interceptor
             * @see XDispatchProviderInterceptor.setMasterDispatchProvider()
             */
            getMasterDispatchProvider(): XDispatchProvider;

            /**
             * access to the slave {@link XDispatchProvider} of this interceptor
             * @returns the slave of this interceptor
             * @see XDispatchProviderInterceptor.setSlaveDispatchProvider()
             */
            getSlaveDispatchProvider(): XDispatchProvider;

            /**
             * access to the master {@link XDispatchProvider} of this interceptor
             * @returns the master of this interceptor
             * @see XDispatchProviderInterceptor.setMasterDispatchProvider()
             */
            MasterDispatchProvider: XDispatchProvider;

            /**
             * sets the master {@link XDispatchProvider} , which may forward calls to its {@link XDispatchProvider.queryDispatch()} to this dispatch provider.
             * @param NewSupplier the master of this interceptor
             * @see XDispatchProviderInterceptor.getMasterDispatchProvider()
             */
            setMasterDispatchProvider(NewSupplier: XDispatchProvider): void;

            /**
             * sets the slave {@link XDispatchProvider} to which calls to {@link XDispatchProvider.queryDispatch()} can be forwarded under control of this dispatch
             * provider.
             * @param NewDispatchProvider the new slave of this interceptor
             * @see XDispatchProviderInterceptor.getSlaveDispatchProvider()
             */
            setSlaveDispatchProvider(NewDispatchProvider: XDispatchProvider): void;

            /**
             * access to the slave {@link XDispatchProvider} of this interceptor
             * @returns the slave of this interceptor
             * @see XDispatchProviderInterceptor.setSlaveDispatchProvider()
             */
            SlaveDispatchProvider: XDispatchProvider;
        }

        /**
         * provides recording functionality of dispatches
         *
         * With such recorder it will be possible to record requests of type {@link XDispatch} by using additional interface {@link XRecordableDispatch} . The
         * result of that will be a a script which can be used to start the dispatch at later time again. Such recorder objects are available on a {@link
         * XDispatchRecorderSupplier} which is provided by the {@link Frame} service.
         * @see Frame
         * @see XDispatchRecorderSupplier
         * @since OOo 1.1.2
         */
        interface XDispatchRecorder extends uno.XInterface {
            /**
             * stops the recording process
             *
             * Must be called in pairs with {@link XDispatchRecorder.startRecording()} .
             * @see getRecordedMacro()
             */
            endRecording(): void;

            /**
             * returns the recorded source code
             *
             * This method must be used before {@link endRecording()} is called! Otherwise the macro will be released.
             * @returns the recorded data as a string which can be interpreted as a script
             */
            getRecordedMacro(): string;

            /**
             * records a single dispatch call identified by its command URL
             * @param URL the full parsed command URL
             * @param Arguments optional arguments for the command URL ;  (see {@link com.sun.star.document.MediaDescriptor} for further information)
             */
            recordDispatch(URL: util.URL, Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>): void;

            /**
             * records a single dispatch call identified by its command URL, but comments it out
             *
             * This way calls that failed on execution can be documented.
             * @param URL the full parsed command URL
             * @param Arguments optional arguments for the command URL ;  (see {@link com.sun.star.document.MediaDescriptor} for further information)
             */
            recordDispatchAsComment(URL: util.URL, Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>): void;

            /**
             * returns the recorded source code
             *
             * This method must be used before {@link endRecording()} is called! Otherwise the macro will be released.
             * @returns the recorded data as a string which can be interpreted as a script
             */
            readonly RecordedMacro: string;

            /**
             * initializes the recorder by passing the frame for which all macro statements shall be recorded
             * @param Frame it includes the document on which such requests shall be recorded
             */
            startRecording(Frame: XFrame): void;
        }

        /**
         * provides access to the record mechanism of dispatches
         *
         * With a {@link XDispatchRecorder} it's possible to record calls of {@link XDispatch.dispatch()} . The recorded data (may a script) can be used to
         * automate recorded dispatch and start it at later time again. This supplier provides access to the recorder and supports some functionality to work
         * with the macro recording mechanism in an easy manner.
         * @see XDispatchRecorder
         * @since OOo 1.1.2
         */
        interface XDispatchRecorderSupplier extends uno.XInterface {
            /**
             * dispatch given URL and record it if recording is enabled
             *
             * Parameter **Dispatcher** is used internally to make the dispatch. If recording isn't enabled it will be a normal {@link XDispatch.dispatch()} call.
             * Otherwise follow algorithm is used: If **Dispatcher** doesn't support the interface {@link XRecordableDispatch} a normal dispatch() call will be made
             * and depend from the result state of that the request will be recorded. In this case it's possible to record the incoming parameter ( **URL** and
             * **Arguments** ) only. Parameters of internal processes can't be recorded then and will be lost.If **Dispatcher** support the interface {@link
             * XRecordableDispatch} it will be used to dispatch and record all necessary parameters of the whole process.
             * @see XRecordableDispatch
             */
            dispatchAndRecord(
                URL: util.URL,
                Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>,
                Dispatcher: XDispatch,
            ): void;

            /**
             * provides access on the recorder of this supplier
             *
             * Returned recorder can be used to record dispatches manually or to get recorded data for further using e.g. saving. It is internally used too due to
             * the method {@link XDispatchRecorderSupplier.dispatchAndRecord()} .
             * @returns the dispatch recorder of this supplier
             * @see XDispatchRecorder
             */
            DispatchRecorder: XDispatchRecorder;

            /**
             * provides access on the recorder of this supplier
             *
             * Returned recorder can be used to record dispatches manually or to get recorded data for further using e.g. saving. It is internally used too due to
             * the method {@link XDispatchRecorderSupplier.dispatchAndRecord()} .
             * @returns the dispatch recorder of this supplier
             * @see XDispatchRecorder
             */
            getDispatchRecorder(): XDispatchRecorder;

            /**
             * set a dispatch recorder on this supplier
             *
             * Setting of a new recorder make it possible to change recording mode. May there can exist different implementations of a recorder (e.g. to generate
             * Java, Basic or other formats). Changing between local recording inside one {@link Frame} or global one by using more than ones can be forced too.
             * @param Recorder the new recorder for this supplier
             */
            setDispatchRecorder(Recorder: XDispatchRecorder): void;
        }

        /**
         * listener for results of {@link XNotifyingDispatch.dispatchWithNotification()}
         * @see XNotifyingDispatch
         */
        interface XDispatchResultListener extends lang.XEventListener {
            /**
             * indicates finished dispatch
             * @param Result contains the result of the dispatch action
             * @see DispatchResultEvent
             */
            dispatchFinished(Result: DispatchResultEvent): void;
        }

        /**
         * provides a high level API to organize document templates
         *
         * Template information are saved as links to the original content and organized in groups. This data should be persistent and can be updated by calling
         * special method {@link XDocumentTemplates.update()} . A real implementation of this interface can do that on top of an ucb content provider. Method
         * {@link XDocumentTemplates.getContent()} force that.
         */
        interface XDocumentTemplates extends uno.XInterface {
            /**
             * creates a new group
             * @param GroupName the name of the group to be created
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             */
            addGroup(GroupName: string): boolean;

            /**
             * creates the template with the given name in the given group using the given URL
             * @param GroupName specifies the group
             * @param TemplateName specifies the template
             * @param SourceURL specifies the position of template
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             * @see XDocumentTemplates.storeTemplate()
             */
            addTemplate(GroupName: string, TemplateName: string, SourceURL: string): boolean;

            /**
             * provides access to the root of internal used hierarchy
             *
             * This content can be used for accessing the groups directly.
             * @returns the ucb content for template configuration
             */
            readonly Content: ucb.XContent;

            /**
             * provides access to the root of internal used hierarchy
             *
             * This content can be used for accessing the groups directly.
             * @returns the ucb content for template configuration
             */
            getContent(): ucb.XContent;

            /**
             * remove an existing group
             * @param GroupName the name of the group to be removed
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             */
            removeGroup(GroupName: string): boolean;

            /**
             * remove a template from specified group
             * @param GroupName specifies the group which include the template
             * @param TemplateName specifies the template for delete
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             */
            removeTemplate(GroupName: string, TemplateName: string): boolean;

            /**
             * rename an existing group
             * @param OldGroupName the old name of the group
             * @param NewGroupName the new name of the group
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             */
            renameGroup(OldGroupName: string, NewGroupName: string): boolean;

            /**
             * rename a template inside specified group
             * @param GroupName specifies the group which include the template
             * @param OldTemplateName specifies the template for renaming
             * @param NewTemplateName specifies the new name for the template
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             */
            renameTemplate(GroupName: string, OldTemplateName: string, NewTemplateName: string): boolean;

            /**
             * creates the template with the given name in the given group using the data from the storable
             * @param GroupName specifies the group
             * @param TemplateName specifies the template
             * @param Storable specifies the target
             * @returns `TRUE` if operation was successful ; `FALSE` otherwise
             * @see XDocumentTemplates.addTemplate()
             */
            storeTemplate(GroupName: string, TemplateName: string, Storable: XStorable): boolean;

            /**
             * force an update for internal structures
             *
             * Because the templates are well known by links and not as direct content they can be outdated. An update force actualization of that to find wrong
             * links.
             */
            update(): void;
        }

        /**
         * use {@link com.sun.star.document.XExtendedFilterDetection} instead of this
         * @deprecated Deprecated
         */
        interface XExtendedFilterDetection extends uno.XInterface {
            /**
             * use {@link com.sun.star.document.XExtendedFilterDetection.detect()} instead of this
             * @deprecated Deprecated
             */
            detect(URL: string, Argumentlist: LibreOffice.SeqEquiv<beans.PropertyValue>): string;
        }

        /**
         * use {@link com.sun.star.document.XExtendedFilterDetection} instead of this
         * @deprecated Deprecated
         */
        interface XFilterDetect extends uno.XInterface {
            getContentType(URL: string): string;
            useExternBrowser(URL: string): boolean;
        }

        /**
         * a frame object can be considered to be an "anchor" object where a component can be attached to.
         *
         * A frame can be (it's not a must!) a part of a frame tree. If not this frame won't be accessible by using the API. This mode make sense for previews.
         * The root node of the tree can be a {@link Desktop} implementation.
         * @see Desktop
         */
        interface XFrame extends lang.XComponent {
            /**
             * activates this frame and thus the component within.
             *
             * At first the frame sets itself as the active frame of its creator by calling {@link XFramesSupplier.setActiveFrame()} , then it broadcasts an {@link
             * FrameActionEvent} with FrameAction::FRAME_ACTIVATED. The component within this frame may listen to this event to grab the focus on activation; for
             * simple components this can be done by the {@link FrameLoader} .
             *
             * Finally, most frames may grab the focus to one of its windows or forward the activation to a sub-frame.
             * @see XFrame.deactivate()
             * @see XFrame.isActive()
             */
            activate(): void;

            /**
             * registers an event listener, which will be called when certain things happen to the components within this frame or within sub-frames of this frame.
             *
             * E.g., it is possible to determine instantiation/destruction and activation/deactivation of components.
             * @param xListener specifies the listener which will be informed
             * @see XFrame.removeFrameActionListener()
             */
            addFrameActionListener(xListener: XFrameActionListener): void;

            /**
             * provides access to the component window
             *
             * Note: Don't dispose this window - the frame is the owner of it.
             * @returns the current visible component in this frame ;  or `NULL` if no one currently exist
             * @see XFrame.setComponent()
             */
            readonly ComponentWindow: awt.XWindow;

            /**
             * provides access to the container window of the frame.
             *
             * Normally this is used as the parent window of the component window.
             * @returns the container window of this frame
             * @see XFrame.initialize()
             */
            readonly ContainerWindow: awt.XWindow;

            /**
             * notifies the frame that the context of the controller within this frame changed (i.e. the selection).
             *
             * According to a call to this interface, the frame calls {@link XFrameActionListener.frameAction()} with FrameAction::CONTEXT_CHANGED to all listeners
             * which are registered using {@link XFrame.addFrameActionListener()} . For external controllers this event can be used to requery dispatches.
             * @see XFrameEventListener
             * @see FrameAction
             * @see XFrame.addFrameActionListener()
             */
            contextChanged(): void;

            /**
             * provides access to the controller
             *
             * Note: Don't dispose it - the frame is the owner of it. Use {@link XController.getFrame()} to dispose the frame after you the controller agreed with a
             * {@link XController.suspend()} call.
             * @returns the current controller within this frame ;  or `NULL` if no one currently exist
             * @see XFrame.setComponent()
             */
            readonly Controller: XController;

            /**
             * provides access to the creator (parent) of this frame
             * @returns the frame container that created and contains this frame.
             * @see XFrame.setCreator()
             */
            Creator: XFramesSupplier;

            /**
             * is called by the creator frame when another sub-frame gets activated.
             *
             * At first the frame deactivates its active sub-frame, if any. Then broadcasts a {@link FrameActionEvent} with FrameAction::FRAME_DEACTIVATING.
             * @see XFrame.activate()
             * @see XFrame.isActive()
             */
            deactivate(): void;

            /**
             * searches for a frame with the specified name.
             *
             * Frames may contain other frames (e.g., a frameset) and may be contained in other frames. This hierarchy is searched with this method. First some
             * special names are taken into account, i.e. "", "_self", "_top", "_blank" etc. **SearchFlags** is ignored when comparing these names with
             * **TargetFrameName** ; further steps are controlled by **SearchFlags** . If allowed, the name of the frame itself is compared with the desired one, and
             * then ( again if allowed ) the method is called for all children of the frame. Finally may be called for the siblings and then for parent frame (if
             * allowed).
             *
             * List of special target names: {{table here, see documentation}}
             *
             * If no frame with the given name is found, a new top frame is created; if this is allowed by a special flag {@link FrameSearchFlag.CREATE} . The new
             * frame also gets the desired name.
             * @param aTargetFrameName identify (a) a special target ("_blank","_self" ...) or(b) any well known frame to search it inside the current hierarchy
             * @param nSearchFlags optional parameter to regulate search if no special target was used for **TargetFrameName**
             * @see FrameSearchFlag
             */
            findFrame(aTargetFrameName: string, nSearchFlags: number): XFrame;

            /**
             * provides access to the component window
             *
             * Note: Don't dispose this window - the frame is the owner of it.
             * @returns the current visible component in this frame ;  or `NULL` if no one currently exist
             * @see XFrame.setComponent()
             */
            getComponentWindow(): awt.XWindow;

            /**
             * provides access to the container window of the frame.
             *
             * Normally this is used as the parent window of the component window.
             * @returns the container window of this frame
             * @see XFrame.initialize()
             */
            getContainerWindow(): awt.XWindow;

            /**
             * provides access to the controller
             *
             * Note: Don't dispose it - the frame is the owner of it. Use {@link XController.getFrame()} to dispose the frame after you the controller agreed with a
             * {@link XController.suspend()} call.
             * @returns the current controller within this frame ;  or `NULL` if no one currently exist
             * @see XFrame.setComponent()
             */
            getController(): XController;

            /**
             * provides access to the creator (parent) of this frame
             * @returns the frame container that created and contains this frame.
             * @see XFrame.setCreator()
             */
            getCreator(): XFramesSupplier;

            /**
             * access to the name property of this frame
             * @returns the programmatic name of this frame.
             * @see XFrame.setName()
             */
            getName(): string;

            /**
             * is called to initialize the frame within a window - the container window.
             *
             * This window will be used as parent for the component window and to support some UI relevant features of the frame service. Note: Re-parenting mustn't
             * supported by a real frame implementation! It's designed for initializing - not for setting.
             *
             * This frame will take over ownership of the window referred from **xWindow** . Thus, the previous owner is not allowed to dispose this window anymore.
             * @param xWindow the new container window
             * @see XFrame.getContainerWindow()
             */
            initialize(xWindow: awt.XWindow): void;

            /**
             * determines if the frame is active.
             * @returns `TRUE` for active or UI active frames ; `FALSE` otherwise
             * @see XFrame.activate()
             * @see XFrame.deactivate()
             */
            isActive(): boolean;

            /**
             * determines if the frame is a top frame.
             *
             * In general a top frame is the frame which is a direct child of a task frame or which does not have a parent. Possible frame searches must stop the
             * search at such a frame unless the flag {@link FrameSearchFlag.TASKS} is set.
             * @returns `TRUE` if frame supports top frame specification ; `FALSE` otherwise
             */
            isTop(): boolean;

            /**
             * access to the name property of this frame
             * @returns the programmatic name of this frame.
             * @see XFrame.setName()
             */
            Name: string;

            /**
             * unregisters an event listener
             * @param xListener specifies the listener which won't be informed any longer
             * @see XFrame.addFrameActionListener()
             */
            removeFrameActionListener(xListener: XFrameActionListener): void;

            /**
             * sets a new component into the frame or release an existing one from a frame.
             * @param xComponentWindow the window of the new component or `NULL` for release  A valid component window should be a child of the frame container window.
             * @param xController the controller of the new component or `NULL` for release  Simple components may implement a {@link com.sun.star.awt.XWindow} only. I
             * @returns `TRUE` if setting of new component or release of an existing one was successfully ; `FALSE` otherwise (especially, if an existing controller disa
             * @see XFrame.getComponentWindow()
             * @see XFrame.getContainerWindow()
             * @see XFrame.getController()
             */
            setComponent(xComponentWindow: awt.XWindow, xController: XController): boolean;

            /**
             * sets the frame container that created this frame.
             *
             * Only the creator is allowed to call this method. But creator doesn't mean the implementation which creates this instance ... it means the parent frame
             * of the frame hierarchy. Because; normally a frame should be created by using the API and is necessary for searches inside the tree (e.g. {@link
             * XFrame.findFrame()} )
             * @param Creator the creator (parent) of this frame
             * @see XFrame.getCreator()
             */
            setCreator(Creator: XFramesSupplier): void;

            /**
             * sets the name of the frame.
             *
             * Normally the name of the frame is set initially (e.g. by the creator). The name of a frame will be used for identifying it if a frame search was
             * started. These searches can be forced by: {@link XFrame.findFrame()}{@link XDispatchProvider.queryDispatch()}{@link
             * XComponentLoader.loadComponentFromURL()} Note: Special targets like "_blank", "_self" etc. are not allowed. That's why frame names shouldn't start
             * with a sign "_".
             * @param aName the new programmatic name of this frame
             * @see XFrame.findFrame()
             * @see XFrame.getName()
             * @see XDispatchProvider
             * @see XComponentLoader
             */
            setName(aName: string): void;
        }

        /** @since LibreOffice 4.1 */
        interface XFrame2
            extends
                XDispatchProvider,
                XDispatchInformationProvider,
                XDispatchProviderInterception,
                XFramesSupplier,
                task.XStatusIndicatorFactory
        {
            /**
             * provides access to the dispatch recorder of the frame
             *
             * Such recorder can be used to record dispatch requests. The supplier contains a dispatch recorder and provide the functionality to use it for any
             * dispatch object from outside which supports the interface {@link XDispatch} . A supplier is available only, if recording was enabled. That means: if
             * someone wishes to enable recoding on a frame they must set a supplier with a recorder object inside of it. Every user of dispatches has to check then if
             * such supplier is available at this frame property. If value of this property is `NULL` they must call {@link XDispatch.dispatch()} on the original
             * dispatch object. If it's a valid value they must use the supplier by calling its method {@link XDispatchRecorderSupplier.dispatchAndRecord()} with the
             * original dispatch object as argument.
             *
             * Note: ;  It's not recommended to cache an already gotten supplier. Because there exist no possibility to check for enabled/disabled recording then.
             * @since OOo 1.1.2
             */
            DispatchRecorderSupplier: XDispatchRecorderSupplier;

            /**
             * Provides access to the {@link LayoutManager} of the frame. This is actually of type {@link XLayoutManager} , but this API is still experimental
             * (unpublished).
             */
            LayoutManager: uno.XInterface;

            /**
             * if possible it sets/gets the UI title on/from the frame container window
             *
             * It depends from the type of the frame container window. If it is a system task window all will be OK. Otherwise the title can't be set.
             * Setting/getting of the pure value of this property must be possible in every case. Only showing on the UI can be fail.
             */
            Title: string;

            /** contains user defined attributes. */
            UserDefinedAttributes: container.XNameContainer;
        }

        /**
         * has to be provided if an object wants to receive events when several things happen to components within frames of the desktop frame tree.
         *
         * E.g., you can receive events of instantiation/destruction and activation/deactivation of components.
         * @see XFrame.addFrameActionListener()
         * @see XFrame.removeFrameActionListener()
         */
        interface XFrameActionListener extends lang.XEventListener {
            /**
             * is called whenever any action occurs to a component within a frame.
             * @param Action describes the detected frame action for which the listener can react
             */
            frameAction(Action: FrameActionEvent): void;
        }

        /**
         * load components into a frame
         *
         * It's an asynchronous loading. For synchronous processes use {@link XSynchronousFrameLoader} instead of this one. The generic load algorithm of the
         * office supports both ones - but preferred the synchronous interface.
         * @see XFrame
         */
        interface XFrameLoader extends uno.XInterface {
            /**
             * cancels the loading process.
             *
             * After returning from this call, neither the frame nor the load-event-listener specified in {@link XFrameLoader.load()} may be called back. Because
             * only the owner of this process who called load method before can cancel this process. And they don't need any notification about that. On the other
             * hand - nobody then this owner themselves can be registered as an {@link XLoadEventListener} here.
             */
            cancel(): void;

            /**
             * starts the loading of the specified resource into the specified {@link Frame} .
             * @param Frame specifies the loading target
             * @param URL describes the resource of loading component Support of special protocols are implementation details and depends from the environment.
             * @param Arguments optional arguments for loading (see {@link com.sun.star.document.MediaDescriptor} for further information)
             * @param Listener this listener will be informed about success
             * @see XLoadEventListener
             */
            load(
                Frame: XFrame,
                URL: string,
                Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>,
                Listener: XLoadEventListener,
            ): void;
        }

        /**
         * use service {@link FrameLoaderFactory} instead of this
         * @deprecated Deprecated
         */
        interface XFrameLoaderQuery extends uno.XInterface {
            /**
             * use member {@link com.sun.star.container.XNameAccess.getElementNames()} provided by service {@link FrameLoaderFactory} instead of this
             * @deprecated Deprecated
             */
            readonly AvailableFilterNames: SafeArray<string>;

            /**
             * use member {@link com.sun.star.container.XNameAccess.getElementNames()} provided by service {@link FrameLoaderFactory} instead of this
             * @deprecated Deprecated
             */
            getAvailableFilterNames(): SafeArray<string>;

            /**
             * use member {@link com.sun.star.container.XNameAccess.getByName()} provided by service {@link FrameLoaderFactory} instead of this
             * @deprecated Deprecated
             */
            getLoaderProperties(sFilterName: string): SafeArray<beans.PropertyValue>;

            /**
             * use member {@link com.sun.star.container.XContainerQuery} provided by service {@link FrameLoaderFactory} instead of this
             * @deprecated Deprecated
             */
            searchFilter(sURL: string, seqArguments: LibreOffice.SeqEquiv<beans.PropertyValue>): string;
        }

        /**
         * manages and creates frames.
         *
         * Frames may contain other frames (by implementing an {@link XFrames} interface) and may be contained in other frames.
         * @see XFrame
         * @see Frame
         */
