        /**
         * has to be provided if an object wants to receive an event when the master environment (e.g., desktop) is terminated.
         * @see XDesktop.terminate()
         * @see XDesktop.addTerminateListener()
         * @see XDesktop.removeTerminateListener()
         */
        interface XTerminateListener extends lang.XEventListener {
            /**
             * is called when the master environment is finally terminated. No veto will be accepted then.
             * @param Event describe the source of the event (e.g., the desktop)
             */
            notifyTermination(Event: lang.EventObject): void;

            /**
             * is called when the master environment (e.g., desktop) is about to terminate.
             *
             * Termination can be intercepted by throwing {@link TerminationVetoException} . Interceptor will be the new owner of desktop and should call {@link
             * XDesktop.terminate()} after finishing its own operations.
             * @param Event describe the source of the event (e.g., the desktop)
             * @throws TerminationVetoException listener can disagree with this query by throwing this veto exception
             */
            queryTermination(Event: lang.EventObject): void;
        }

        /** extend interface {@link XTerminateListener} so a listener will be informed in case termination process was canceled by other reasons. */
        interface XTerminateListener2 extends XTerminateListener {
            /**
             * is called when the master environment (e.g., desktop) was canceled in it's terminate request.
             *
             * Termination can be intercepted by throwing {@link TerminationVetoException} . But if a listener was queried for termination .. doesn't throw a veto
             * exception ... it doesn't know if termination will be real next time. Because any other listener can throw those exception too ... and so it can happen
             * that after {@link queryTermination()} no {@link notifyTermination()} will occur. But these listener don't know if its allowed to start new processes
             * then. Using this optional(!) interface will make it possible to be informed about canceled termination requests also.
             * @param Event describe the source of the event (e.g., the desktop)
             */
            cancelTermination(Event: lang.EventObject): void;
        }

