        /**
         * This service is implemented by the chart presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface ChartShape extends Shape, drawing.OLE2Shape {}

        /**
         * A custom presentation can show the pages of its presentation in a customized order.
         *
         * Such a presentation can use certain pages more than once, but it does not necessarily use all of the pages.
         */
        interface CustomPresentation extends container.XIndexContainer, container.XNamed {}

        /** This is a container for custom presentations. */
        interface CustomPresentationAccess extends container.XNameContainer, lang.XSingleServiceFactory {}

        /**
         * This service is implemented by the date and time presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface DateTimeShape extends Shape, drawing.TextShape {}

        /** describes properties that apply to the whole presentation document. */
        interface DocumentSettings extends document.Settings, document.HeaderFooterSettings, beans.XPropertySet {
            /** enables or disables the printing of the drawing pages */
            IsPrintDrawing: boolean;

            /** enables or disables the fitting of the page to the printable area during print */
            IsPrintFitPage: boolean;

            /** enables or disables the printing of the handout pages */
            IsPrintHandout: boolean;

            /** enables or disables the printing of draw pages that are marked hidden */
            IsPrintHiddenPages: boolean;

            /** enables or disables the printing of the notes pages */
            IsPrintNotes: boolean;

            /** enables or disables the printing of the outline pages */
            IsPrintOutline: boolean;

            /** if this is true and the paper size for printing is larger than the paper size of the printer than the content is tiled over multiple pages. */
            IsPrintTilePage: boolean;

            /** is the number format used for page number fields */
            PageNumberFormat: number;

            /**
             * If this is true, the distance between two paragraphs is the sum of ParaTopMargin of the previous and ParaBottomMargin of the next paragraph. If false,
             * only the greater of the two is chosen.
             */
            ParagraphSummation: boolean;
        }

        /**
         * This is the service provided by a {@link com.sun.star.drawing.DrawPage} inside a {@link PresentationDocument} .
         * @see PresentationDocument
         */
        interface DrawPage extends drawing.DrawPage, document.LinkTarget {
            /**
             * specifies how the page change is triggered.
             *
             * If this is 0, the user must click to start each object animation and to change the page. If set to 1, the page is automatically switched. If it is set
             * to 2, all object effects run automatically, but the user has to click on the page to change it.
             */
            Change: number;

            /** defines the format that is used to format a date and time text field on this page. This is only used if `IsDateTimeFixed` is `FALSE` . */
            DateTimeFormat: number;

            /** defines the text that is displayed in a date and time textfield rendered on this page. This value is only used if `IsDateTimeFixed` is `TRUE` . */
            DateTimeText: string;

            /**
             * If the property com::sun::star::drawing::DrawPage::Change is set to 1, this is the time in seconds this page is shown before switching to the next
             * page.
             */
            Duration: number;

            /** This is the effect that is used to fade in this page. */
            Effect: FadeEffect;

            /** defines the text that is displayed in a footer textfield rendered on this page. */
            FooterText: string;

            /** defines the text that is displayed in a header textfield rendered on this page. */
            HeaderText: string;

            /**
             * If the property com::sun::star::drawing::DrawPage::Change is set to 1, this is the time in seconds this page is shown before switching to the next
             * page, also permitting sub-second precision here.
             */
            HighResDuration: number;

            /** defines if a date and time text field shows a fixed string value or the current date on this page. */
            IsDateTimeFixed: boolean;

            /** defines if a date and time presentation shape from the master page is visible on this page. */
            IsDateTimeVisible: boolean;

            /** defines if a footer presentation shape from the master page is visible on this page. */
            IsFooterVisible: boolean;

            /** defines if a header presentation shape from the master page is visible on this page. */
            IsHeaderVisible: boolean;

            /** defines if a page number presentation shape from the master page is visible on this page. */
            IsPageNumberVisible: boolean;

            /** If this property is not ZERO, this number specifies a presentation layout for this page. */
            Layout: number;

            /** defines the speed of the fade-in effect of this page. */
            Speed: AnimationSpeed;
        }

