        /**
         * This component integrates an outline view to a presentation document into the desktop.
         *
         * In an outline view, the textual contents of presentation text objects from all presentation pages are presented as a continuous outline text.
         * @since OOo 1.1.2
         */
        interface OutlineView extends frame.Controller, awt.XWindow, beans.XPropertySet {
            /** This is the area that is currently visible. */
            VisibleArea: awt.Rectangle;
        }

        /**
         * This service is implemented by the page presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface PageShape extends Shape, drawing.PageShape {}

        /**
         * an event has a source that causes an event to be fired and a trigger that defines under which condition an event should be raised and an offset if the
         * event should be raised a defined amount of time after the event is triggered.
         */
        interface ParagraphTarget {
            Paragraph: number;
            Shape: drawing.XShape;
        }

        /** This service is a presentation that is available from a {@link PresentationDocument} via the {@link XPresentationSupplier} interface. */
        interface Presentation extends XPresentation, beans.XPropertySet {
            /** enables/disables the shape animations. */
            AllowAnimations: boolean;

            /** If this string is not empty, it contains the name of a customized show that is used for the presentation. */
            CustomShow: string;

            /** If this string is not empty, it contains the name of the page where the presentation is started. */
            FirstPage: string;

            /** If this property is set to `TRUE` , the window of the presentation is always on top of all other windows. */
            IsAlwaysOnTop: boolean;

            /**
             * If this property is `TRUE` , all pages are changed automatically.
             *
             * This overrides the properties of the pages.
             */
            IsAutomatic: boolean;

            /** If this property is set to `TRUE` , the presentation is repeated endlessly. */
            IsEndless: boolean;

            /** If this property is set to `TRUE` , the presentation runs in full-screen mode. */
            IsFullScreen: boolean;

            /**
             * With this property, you can set the presentation to live mode.
             *
             * Implementations that have no live mode capability may ignore this property and always return false.
             */
            IsLivePresentation: boolean;

            /** If this property is `TRUE` , the mouse is visible during the presentation. */
            IsMouseVisible: boolean;

            /**
             * is the duration of the black screen after the presentation has finished.
             *
             * If this is set to `0` , no black screen is shown.
             */
            Pause: number;

            /** If this is set to `TRUE` , the Navigator is opened at the start of the presentation. */
            StartWithNavigator: boolean;

            /**
             * If this is `TRUE` , a pen is shown during presentation.
             *
             * You can draw on the presentation with this pen.
             */
            UsePen: boolean;
        }

        /**
         * enhances the {@link Presentation} service to give access to a {@link XPresentation2} interface.
         * @since OOo 3.0
         */
        interface Presentation2 extends Presentation, XPresentation2 {}

        /** This is the service provided by a presentation document. */
        interface PresentationDocument
            extends
                drawing.GenericDrawingDocument,
                XPresentationSupplier,
                XCustomPresentationSupplier,
                document.XLinkTargetSupplier
        {
            addEventListener(Listener: document.XEventListener | lang.XEventListener): void;
            removeEventListener(Listener: document.XEventListener | lang.XEventListener): void;
        }

        /** This component integrates a view to a slide show of a presentation document into the desktop. */
        interface PresentationView extends frame.Controller, awt.XWindow, drawing.XDrawView, beans.XPropertySet {
            /** This is the drawing page that is currently visible. */
            CurrentPage: drawing.XDrawPage;

            /** This is the area that is currently visible. */
            VisibleArea: awt.Rectangle;
        }

        /**
         * This component integrates a preview view to a slide show of a presentation document into the desktop.
         * @since OOo 1.1.2
         */
        interface PreviewView extends frame.Controller, awt.XWindow, drawing.XDrawView, beans.XPropertySet {
            /** This is the drawing page that is currently visible. */
            CurrentPage: drawing.XDrawPage;

            /** This is the area that is currently visible. */
            VisibleArea: awt.Rectangle;
        }

        /**
         * this service is supported from all shapes inside a {@link PresentationDocument} .
         *
         * This usually enhances objects of type {@link com.sun.star.drawing.Shape} with presentation properties.
         */
        interface Shape {
            /** is a generic URL for the property OnClick. */
            Bookmark: string;

            /**
             * This is the color for dimming this shape.
             *
             * This color is used if the property com::sun::star::drawing::Shape::DimPrev is `TRUE` and com::sun::star::drawing::Shape::DimHide is `FALSE` .
             */
            DimColor: util.Color;

            /** If this property and the property com::sun::star::drawing::Shape::DimPrev are both `TRUE` , the shape is hidden instead of dimmed to a color. */
            DimHide: boolean;

            /**
             * If this property is `TRUE` , this shape is dimmed to the color of property com::sun::star::drawing::Shape::DimColor after executing its animation
             * effect.
             */
            DimPrevious: boolean;

            /** selects the animation effect of this shape. */
            Effect: AnimationEffect;

            /** If this is a default presentation object and if it is empty, this property is `TRUE` . */
            IsEmptyPresentationObject: boolean;

            /**
             * If this is a presentation object, this property is `TRUE` .
             *
             * {@link Presentation} objects are objects like {@link TitleTextShape} and {@link OutlinerShape} .
             */
            IsPresentationObject: boolean;

            /** selects an action performed after the user clicks on this shape. */
            OnClick: ClickAction;

            /**
             * If this property is `TRUE` , the sound of this shape is played in full.
             *
             * The default behavior is to stop the sound after completing the animation effect.
             */
            PlayFull: boolean;

            /**
             * This is the position of this shape in the order of the shapes which can be animated on its page.
             *
             * The animations are executed in this order, starting at the shape with the PresentationOrder "one." You can change the order by changing this number.
             * Setting it to "one" makes this shape the first shape in the execution order for the animation effects.
             */
            PresentationOrder: number;

            /** This is the URL to a sound file that is played while the animation effect of this shape is running. */
            Sound: string;

            /** If this property is set to `TRUE` , a sound is played while the animation effect is executed. */
            SoundOn: boolean;

            /** This is the speed of the animation effect. */
            Speed: AnimationSpeed;

            /** This is the animation effect for the text inside this shape. */
            TextEffect: AnimationEffect;

            /** specifies an "OLE2" verb for the ClickAction VERB in the property com::sun::star::drawing::Shape::OnClick. */
            Verb: number;
        }

        /**
         * This service is implemented by the slide number presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface SlideNumberShape extends Shape, drawing.TextShape {}

        /**
         * This component integrates a slides view to a presentation document into the desktop.
         *
         * In a slides view, the pages of a presentation document are displayed to the user as thumbnails and can be arranged and cut/copied to/from the
         * clipboard.
         * @since OOo 1.1.2
         */
        interface SlidesView extends frame.Controller, awt.XWindow, beans.XPropertySet {
            /** This is the area that is currently visible. */
            VisibleArea: awt.Rectangle;
        }

        /**
         * This service is implemented by the subtitle presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface SubtitleShape extends Shape, drawing.TextShape {}

        /**
         * This service is implemented by the title and subtitle presentation shape.
         *
         * {@link Presentation} shapes can be used in a presentation page layouts and their position and size is by default set by the presentation shapes on the
         * {@link com.sun.star.drawing.MasterPage} .
         */
        interface TitleTextShape extends Shape, drawing.TextShape {}

        /**
         * must be supported to provide access to customized presentations of a presentation document.
         * @see XCustomPresentation
         * @see XCustomPresentationAccess
         */
        interface XCustomPresentationSupplier extends uno.XInterface {
            /** @returns the {@link CustomPresentation} . */
            readonly CustomPresentations: container.XNameContainer;

            /** @returns the {@link CustomPresentation} . */
            getCustomPresentations(): container.XNameContainer;
        }

        /** returns the handout master page for this document */
        interface XHandoutMasterSupplier extends uno.XInterface {
            /** returns the {@link DrawPage} . */
            getHandoutMasterPage(): drawing.XDrawPage;

            /** returns the {@link DrawPage} . */
            readonly HandoutMasterPage: drawing.XDrawPage;
        }

        /** With this interface you can control any object that implements a {@link Presentation} . */
        interface XPresentation extends uno.XInterface {
            /** The presentation is stopped and the full-screen mode will end. */
            end(): void;

            /** Starts the presentation from the beginning and shows the actual running time to the user. */
            rehearseTimings(): void;

            /** The presentation is shown in full-screen and started from the beginning. */
            start(): void;
        }

        /**
         * enhances the {@link XPresentation} interface to give access to a {@link XSlideShowController} and to start a presentation with arguments.
         * @since OOo 3.0
         */
        interface XPresentation2 extends XPresentation, beans.XPropertySet {
            /** if the slide show is running, this returns a controller object to control the running slide show. */
            readonly Controller: XSlideShowController;

            /** if the slide show is running, this returns a controller object to control the running slide show. */
            getController(): XSlideShowController;

            /** returns true if the slide show is currently running */
            isRunning(): boolean;

            /** start the slide show with the given arguments. All arguments override the values from {@link Presentation} . */
            startWithArguments(Arguments: LibreOffice.SeqEquiv<beans.PropertyValue>): void;
        }

        /**
         * describes a page from a presentation.
         * @see com.sun.star.drawing.DrawPage
         */
        interface XPresentationPage extends drawing.XDrawPage {
            /**
             * return the note page from the current page in the presentation, the name for the note page in the user interface note view, and one of the views from
             * a presentation page.
             */
            getNotesPage(): drawing.XDrawPage;

            /**
             * return the note page from the current page in the presentation, the name for the note page in the user interface note view, and one of the views from
             * a presentation page.
             */
            readonly NotesPage: drawing.XDrawPage;
        }

        /** controls a presentation directly. This supplier will do this. */
        interface XPresentationSupplier extends uno.XInterface {
            /** @returns an interface to control a presentation. */
            getPresentation(): XPresentation;

            /** @returns an interface to control a presentation. */
            readonly Presentation: XPresentation;
        }

        /**
         * Listener interface to receive shape-specific events.
         * @since OOo 2.4
         */
        interface XShapeEventListener extends lang.XEventListener {
            /**
             * Notify a clicked shape.
             *
             * This method notifies the listener that a shape was clicked.
             * @param xShape The shape that was clicked upon.
             * @param aOriginalEvent The original mouse click event that generated this notification.
             */
            click(xShape: drawing.XShape, aOriginalEvent: awt.MouseEvent): void;
        }

        /**
         * Slide show interface to perform slide show presentations.
         *
         * This interface provides the necessary methods to run and control a slide show from a given set of XDrawPage slides. The slide show can be displayed
         * simultaneously on multiple targets.
         *
         * Note: To control a running slide show inside a presentation, please use {@link XPresentation2} and {@link XSlideShowController} .
         * @since OOo 3.0
         */
        interface XSlideShow extends uno.XInterface {
            /**
             * Add a shape event listener.
             *
             * This method adds a listener to the slide show, which will get notified when a mouse click is performed on the given shape. This can be used by clients
             * of the slide show to trigger external actions, such as jumps to different slides.
             * @param xListener Listener to add.
             * @param xShape The {@link Shape} to register a listener for.
             */
            addShapeEventListener(xListener: XShapeEventListener, xShape: drawing.XShape): void;

            /**
             * Add a slide show listener.
             *
             * This method adds a listener to the slide show, which will get notified when a registered shape is clicked upon, or a new slide is about to be
             * displayed. Note that the listeners will **not** be notified, when the slide change is directly requested by one of the nextSlide(), previousSlide() or
             * {@link displaySlide()} methods.
             * @param xListener Listener to add.
             */
            addSlideShowListener(xListener: XSlideShowListener): void;

            /**
             * Add a view to the slide show.
             *
             * This method adds a view to the slide show. After successful completion of this method, the slide show will be visible on the added view, scaled
             * according to the view's output area.
             * @param xView The view to add
             * @returns `TRUE` , if the view has been successfully added. Otherwise, `FALSE` is returned (e.g. if the view is already added).
             */
            addView(xView: XSlideShowView): boolean;

            /**
             * Query the currently displayed slide.
             * @returns the instance of the current slide. If there's no slide show running at the moment, this method returns an empty reference.
             */
            readonly CurrentSlide: drawing.XDrawPage;

            /**
             * Jump to the given slide.
             *
             * This method ends all effects on the current slide, displays a possible slide transition, followed by the given slide. If the current slide is equal to
             * the requested slide here, this method does nothing (this especially means, that any currently active effects will remain running).
             * @param xSlide The slide to display.
             * @param xDrawPages For future use.
             * @param AnimationNode The animation node determine the animations to display.
             * @param aProperties Sequence of property values, which influence the way the slide is displayed. Currently, the following values are recognized: name: Pr
             */
            displaySlide(
                xSlide: drawing.XDrawPage,
                xDrawPages: drawing.XDrawPagesSupplier,
                AnimationNode: animations.XAnimationNode,
                aProperties: LibreOffice.SeqEquiv<beans.PropertyValue>,
            ): void;

            /**
             * Query the currently displayed slide.
             * @returns the instance of the current slide. If there's no slide show running at the moment, this method returns an empty reference.
             */
            getCurrentSlide(): drawing.XDrawPage;

            /**
             * Trigger the next effect of the slide show.
             *
             * This method triggers the next effect on the currently displayed slide. If there is currently no slide show running, this method does nothing. If there
             * are no more effects on the current slide, a possible slide transition effect is issued and the next slide is displayed.
             * @returns `TRUE` , if the next effect was successfully triggered. This method returns `FALSE` , if there is no show running, the last effect on the last sl
             */
            nextEffect(): boolean;

            /**
             * Change the pause state of the slide show.
             *
             * This method either pauses the slide show (all currently running effects are stopped), or starts a previously stopped show again (all paused effects
             * start again).
             * @param bPauseShow When `TRUE` , the show is paused. When `FALSE` , and the show was paused, it starts running at the paused position again.
             * @returns `TRUE` , if the requested action was successfully performed.
             */
            pause(bPauseShow: boolean): boolean;

            /**
             * Undo the last effect in the main sequence of the slide show.
             *
             * The current slide is displayed as if the last user-triggered effect has never been triggered. If there is no previous effect on the current slide then
             * slideEnded(true) is called at the registered {@link XSlideShowListener} objects, which can then trigger a change to the previous slide. Note that this
             * command is executed asynchronously. Multiple calls to {@link update()} may be necessary to complete its execution. If there is currently no slide show
             * running, this method does nothing.
             * @returns `TRUE` , if the previous effect was successfully triggered. This method returns `FALSE` , if there is no show running, the first effect on the fi
             */
            previousEffect(): boolean;

            /**
             * Register drawn polygons in presentation mode
             * @param xDocFactory
             */
            registerUserPaintPolygons(xDocFactory: lang.XMultiServiceFactory): void;

            /**
             * Revoke a previously registered shape event listener.
             * @param xListener Listener interface to revoke from being called.
             * @param xShape for which the listener should be revoked.
             */
            removeShapeEventListener(xListener: XShapeEventListener, xShape: drawing.XShape): void;

            /**
             * Revoke a previously registered slide show listener.
             * @param xListener Listener interface to revoke from being called.
             */
            removeSlideShowListener(xListener: XSlideShowListener): void;

            /**
             * Remove view from the slide show.
             *
             * This method removes the given view from the slide show. After successful completion of this method, the slide show will cease to display on this view.
             * @param xView View to remove
             * @returns `TRUE` , if the view was successfully removed, `FALSE` otherwise (e.g. if the view was not added in the first place).
             */
            removeView(xView: XSlideShowView): boolean;

            /**
             * Change a property of the slide show.
             * @param aShowProperty Property values, which influence the way the slides are shown. Note that this might possibly be a subset of what is supported on sh
             */
            setProperty(aShowProperty: beans.PropertyValue): boolean;

            /**
             * Set a special mouse cursor for a shape.
             *
             * This method requests the slide show to display a special cursor, whenever the mouse is hovering over the given shape.
             * @param xShape The {@link Shape} to display a special mouse cursor.
             * @param nPointerShape Type of mouse cursor to display. Must be one of the {@link com.sun.star.awt.SystemPointer} values.
             */
            setShapeCursor(xShape: drawing.XShape, nPointerShape: number): void;

            /**
             * Start a shape-intrinsic animation or activity.
             *
             * This method starts an animation or activity intrinsic to the given shape. Shape-intrinsic activities are things like video playback for multimedia
             * shapes, sounds, GIF animations and drawing layer animations (flipping between shapes in a group, or scroll text).
             * @param xShape The shape to start the activity for
             */
            startShapeActivity(xShape: drawing.XShape): boolean;

            /**
             * Stop a shape-intrinsic animation or activity.
             *
             * This method stops an animation or activity intrinsic to the given shape. Shape-intrinsic activities are things like video playback for multimedia
             * shapes, sounds, GIF animations and drawing layer animations (flipping between shapes in a group, or scroll text).
             * @param xShape The shape to stop the activity for
             */
            stopShapeActivity(xShape: drawing.XShape): boolean;

            /**
             * Update the animations.
             *
             * This method updates all currently active slide animations. The {@link XSlideShow} implementations do not render animations automatically, but must be
             * called from their clients. This allows for various update mechanisms to be employed, ranging from a dedicated rendering thread, over timer-based
             * updates, to rendering in an idle function. Either way, the client of this interface decide about the details.
             * @param nNextTimeout Via this value, the implementation can return a timeout value, denoting the maximal time span that must not be exceeded from the ret
             * @returns `TRUE` , if further update calls are required. If `FALSE` is returned, no further update calls are necessary, until anyone of the other interface
             */
            update(nNextTimeout: [number]): boolean;
        }

        /**
         * interface to control a running slide show.
         * @see XPresentation2
         * @since OOo 3.0
         */
        interface XSlideShowController {
            /**
             * activates the user interface of this slide show.
             * @see deactivate()
             * @see isActive()
             */
            activate(): void;

            /** adds a listener that receives events while the slide show is running. */
            addSlideShowListener(Listener: XSlideShowListener): void;

            /** If this attribute is set to `TRUE` , the window of the slide show is always on top of all other windows. */
            AlwaysOnTop: boolean;

            /**
             * pauses the slide show and blanks the screen in the given color.
             *
             * Change attribute Pause to false to unpause the slide show.
             */
            blankScreen(Color: number): void;

            /** returns slide that is currently displayed */
            readonly CurrentSlide: drawing.XDrawPage;

            /** returns the index of the current slide. */
            readonly CurrentSlideIndex: number;

            /**
             * can be called to deactivate the user interface of this slide show.
             *
             * A deactivated
             * @see activate()
             * @see isActive()
             */
            deactivate(): void;

            /** returns slide that is currently displayed */
            getCurrentSlide(): drawing.XDrawPage;

            /** returns the index of the current slide. */
            getCurrentSlideIndex(): number;

            /** the index for the slide that is displayed next. */
            getNextSlideIndex(): number;

            /**
             * gives access to the slides that will be shown in this slide show.
             *
             * Slides are returned in the order they will be displayed in the presentation which can be different than the orders of slides in the document. Not all
             * slides must be present and each slide can be used more than once.
             * @param Index specifies the position in the list of slides that are displayed in this slide show. The first index is 0.
             * @returns the slide at the specified index.
             * @throws com::sun::star::lang::IndexOutOfBoundException if the index is not valid.
             */
            getSlideByIndex(Index: number): drawing.XDrawPage;

            /**
             * @returns the number of slides in this slide show.
             * @see getSlideByIndex
             */
            getSlideCount(): number;

            /**
             * returns the actual {@link XSlideShow} instance that runs the slide show. ;  Normally all navigation should be done using this controller and not the
             * {@link XSlideShow} itself.
             */
            getSlideShow(): XSlideShow;

            /** goto the given textual bookmark */
            gotoBookmark(Bookmark: string): void;

            /** goto and display first slide */
            gotoFirstSlide(): void;

            /**
             * goto and display last slide.
             *
             * Remaining effects on the current slide will be skipped.
             */
            gotoLastSlide(): void;

            /**
             * start next effects that wait on a generic trigger.
             *
             * If no generic triggers are waiting the next slide will be displayed.
             */
            gotoNextEffect(): void;

            /**
             * goto and display next slide.
             *
             * Remaining effects on the current slide will be skipped.
             */
            gotoNextSlide(): void;

            /**
             * undo the last effects that where triggered by a generic trigger.
             *
             * If there is no previous effect that can be undone then the previous slide will be displayed.
             */
            gotoPreviousEffect(): void;

            /**
             * goto and display previous slide.
             *
             * Remaining effects on the current slide will be skipped.
             */
            gotoPreviousSlide(): void;

            /**
             * jumps to the given slide.
             *
             * The slide can also be a slide that would normally not be shown during the current slide show.
             * @throws com::sun::star::lang::IllegalArgumentException if the given page is not a valid slide of the document for which this slide show is started. Also
             */
            gotoSlide(Page: drawing.XDrawPage): void;

            /** jumps to the slide at the given index. */
            gotoSlideIndex(Index: number): void;

            /**
             * determines if the slide show is active.
             * @returns `TRUE` for UI active slide show ; `FALSE` otherwise
             */
            isActive(): boolean;

            /** returns `TRUE` if the slide show was started to run endlessly. */
            isEndless(): boolean;

            /** Returns `TRUE` if the slide show was started in full-screen mode. */
            isFullScreen(): boolean;

            /**
             * returns `TRUE` if the slide show is currently paused.
             * @see pause()
             * @see resume()
             */
            isPaused(): boolean;

            /**
             * returns true if the slide show is still running. If this returns false, this component is already disposed. You can start a new slide show and get a
             * new instance of {@link XSlideShowController} from {@link XPresentation2}
             */
            isRunning(): boolean;

            /** If this attribute is `TRUE` , the mouse is visible during the slide show. */
            MouseVisible: boolean;

            /** the index for the slide that is displayed next. */
            readonly NextSlideIndex: number;

            /**
             * pauses the slide show. All effects are paused.
             *
             * The slide show continues on next user input or if {@link resume()} is called.
             */
            pause(): void;

            /** This attribute changes the color of the pen. */
            PenColor: number;

            /**
             * This attribute changes the width of the pen.
             * @since LibreOffice 4.2
             */
            PenWidth: number;

            /** removes a listener. */
            removeSlideShowListener(Listener: XSlideShowListener): void;

            /** resumes a paused slide show. */
            resume(): void;

            /**
             * @returns the number of slides in this slide show.
             * @see getSlideByIndex
             */
            readonly SlideCount: number;

            /**
             * returns the actual {@link XSlideShow} instance that runs the slide show. ;  Normally all navigation should be done using this controller and not the
             * {@link XSlideShow} itself.
             */
            readonly SlideShow: XSlideShow;

            /** stop all currently played sounds */
            stopSound(): void;

            /**
             * If this is `TRUE` , a pen is shown during presentation.
             *
             * You can draw on the presentation with this pen.
             */
            UsePen: boolean;
        }

        /**
         * Listener interface to receive global slide show events.
         * @see XShapeEventListener
         * @since OOo 3.0
         */
        interface XSlideShowListener extends animations.XAnimationListener {
            /**
             * Notifies that a hyperlink has been clicked.
             * @param hyperLink hyperlink URL
             */
            hyperLinkClicked(hyperLink: string): void;

            /** Notify that the slide show is paused */
            paused(): void;

            /** Notify that the slide show is resumed from a paused state */
            resumed(): void;

            /** Notify that the last animation from the main sequence of the current slide has ended. */
            slideAnimationsEnded(): void;

            /**
             * Notify that the current slide has ended, e.g. the user has clicked on the slide. Calling displaySlide() twice will not issue this event.
             * @param reverse For the default order (forward) this flag is `FALSE` . When the main sequence was traversed in reverse order then this flag is `TRUE` .
             */
            slideEnded(reverse: boolean): void;

            /** Notify that the slide transition of the current slide ended. */
            slideTransitionEnded(): void;

            /** Notify that a new slide starts to become visible. */
            slideTransitionStarted(): void;
        }

        /**
         * View interface to display slide show presentations on.
         *
         * This interface provides the necessary methods to enable an {@link XSlideShow} interface to display a presentation. The slide show can be displayed
         * simultaneously on multiple views
         * @since OOo 2.4
         */
        interface XSlideShowView extends uno.XInterface {
            /**
             * Add a mouse listener to the view.
             *
             * This method registers a listener with the view, which will get called every time the mouse is clicked on the view.
             * @param xListener Listener interface to call when the mouse is clicked on the view.
             */
            addMouseListener(xListener: awt.XMouseListener): void;

            /**
             * Add a mouse motion listener to the view.
             *
             * This method registers a listener with the view, which will get called every time the mouse is moved on the view.
             * @param xListener Listener interface to call when the mouse is moved on the view.
             */
            addMouseMotionListener(xListener: awt.XMouseMotionListener): void;

            /**
             * Add a listener to get notified when this view needs a repaint.
             *
             * This method registers a listener with the view, which will get called every time the view needs an update of their screen representation.
             * @param xListener Listener interface to call when the view needs a repaint.
             */
            addPaintListener(xListener: awt.XPaintListener): void;

            /**
             * Add a listener to get notified when the transformation matrix changes.
             *
             * This method registers a listener with the view, which will get called every time the transformation matrix changes.
             * @param xListener Listener interface to call when the transformation matrix changes.
             */
            addTransformationChangedListener(xListener: util.XModifyListener): void;

            /**
             * Get view canvas.
             *
             * This method gets the underlying XCanvas to display on this view.
             * @returns XSpriteCanvas to display on. Must be valid, and the same object, as long as this view is added to any slide show.
             */
            readonly Canvas: rendering.XSpriteCanvas;

            /** Get rectangle defining area inside of canvas device which this slide show view uses. */
            readonly CanvasArea: awt.Rectangle;

            /**
             * This method clears the whole view area.
             *
             * The slide show uses this method to fully erase the view content. Since the slide show has no notion of view size, this is the only reliable way to
             * wholly clear the view.
             */
            clear(): void;

            /**
             * Get view canvas.
             *
             * This method gets the underlying XCanvas to display on this view.
             * @returns XSpriteCanvas to display on. Must be valid, and the same object, as long as this view is added to any slide show.
             */
            getCanvas(): rendering.XSpriteCanvas;

            /** Get rectangle defining area inside of canvas device which this slide show view uses. */
            getCanvasArea(): awt.Rectangle;

            /**
             * Query the current transformation matrix for this view.
             *
             * This method returns the transformation matrix of the view. When notified via the transformation change listener, the show will be displayed using the
             * new transformation.
             * @returns the view transformation matrix. Note that the slide show itself will paint all slides as one-by-one boxes, one therefore has to at least provide
             */
            getTransformation(): geometry.AffineMatrix2D;

            /**
             * Query the current translation offset used to fill the physical screen while keeping aspect ratio.
             *
             * This method returns the translation offset of the view of the view.
             * @returns the slideshowview will be transformed in order to fill the physical screen while keeping the aspect ratio. In order to do so, we need to add a bl
             */
            getTranslationOffset(): geometry.IntegerSize2D;

            /**
             * Revoke a previously registered mouse listener.
             * @param xListener Listener interface to revoke from being called.
             */
            removeMouseListener(xListener: awt.XMouseListener): void;

            /**
             * Revoke a previously registered mouse move listener.
             * @param xListener Listener interface to revoke from being called.
             */
            removeMouseMotionListener(xListener: awt.XMouseMotionListener): void;

            /**
             * Revoke a previously registered paint listener.
             * @param xListener Listener interface to revoke from being called.
             */
            removePaintListener(xListener: awt.XPaintListener): void;

            /**
             * Revoke a previously registered transformation matrix change listener.
             * @param xListener Listener interface to revoke from being called.
             */
            removeTransformationChangedListener(xListener: util.XModifyListener): void;

            /**
             * Change the mouse cursor currently in effect.
             *
             * This method changes the mouse cursor currently in effect, for this view.
             * @param nPointerShape New mouse cursor shape to display for this view. Must be from the {@link com.sun.star.awt.SystemPointer} constant group.
             */
            setMouseCursor(nPointerShape: number): void;

            /**
             * Query the current transformation matrix for this view.
             *
             * This method returns the transformation matrix of the view. When notified via the transformation change listener, the show will be displayed using the
             * new transformation.
             * @returns the view transformation matrix. Note that the slide show itself will paint all slides as one-by-one boxes, one therefore has to at least provide
             */
            readonly Transformation: geometry.AffineMatrix2D;

            /**
             * Query the current translation offset used to fill the physical screen while keeping aspect ratio.
             *
             * This method returns the translation offset of the view of the view.
             * @returns the slideshowview will be transformed in order to fill the physical screen while keeping the aspect ratio. In order to do so, we need to add a bl
             */
            readonly TranslationOffset: geometry.IntegerSize2D;
        }

        /**
         * Transition interface to render custom transitions over time.
         * @since OOo 2.4
         */
        interface XTransition extends uno.XInterface {
            /**
             * Update transition on screen to given time state.
             * @param t Time on the transition timeline to display. Must be in the [0,1] range.
             */
            update(t: number): void;
            viewChanged(
                view: XSlideShowView,
                leavingBitmap: rendering.XBitmap,
                enteringBitmap: rendering.XBitmap,
            ): void;
        }

        /**
         * {@link TransitionFactory} interface to request optional custom Transition instances for slide show transitions.
         *
         * This interface provides the necessary methods to query and create optional transition effects for a {@link SlideShow}
         * @since OOo 2.4
         */
        interface XTransitionFactory extends uno.XInterface {
            /**
             * Actually create a transition for the given transition id
             * @param transitionType Main type of transition (
             * @param transitionSubType Subtype for the transition (
             * @param view Slide show view to display on
             * @param leavingBitmap Bitmap of the slide that's going to leave the screen
             * @param enteringBitmap Bitmap of the slide that's going to enter the screen
             * @see com.sun.star.animations.TransitionType)
             * @see com.sun.star.animations.TransitionSubType)
             */
            createTransition(
                transitionType: number,
                transitionSubType: number,
                view: XSlideShowView,
                leavingBitmap: rendering.XBitmap,
                enteringBitmap: rendering.XBitmap,
            ): XTransition;

            /** Checks whether this instance provides an implementation for given transition id. */
            hasTransition(transitionType: number, transitionSubType: number): boolean;
        }

