        /**
         * provides access to the application-wide registered databases.
         *
         * This interface provides a mere wrapper around the respective configuration data, this way hiding the concrete configuration structure from its
         * clients. You should, if possible at all, use this interface, instead of modifying or querying the configuration data directly.
         * @since OOo 3.3
         */
        interface XDatabaseRegistrations {
            /** registers a listener which is notified of changes in the registered databases */
            addDatabaseRegistrationsListener(Listener: XDatabaseRegistrationsListener): void;

            /**
             * changes the location of a given database registration
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty, or the given location is invalid.
             * @throws com::sun::star::container::NoSuchElementException if there is no database registered under this name
             * @throws com::sun::star::lang::IllegalAccessException if the registration data for this database is read-only
             */
            changeDatabaseLocation(Name: string, NewLocation: string): void;

            /**
             * returns the location of the database registered under the given name
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty
             * @throws com::sun::star::container::NoSuchElementException if there is no database registered under this name
             */
            getDatabaseLocation(Name: string): string;

            /** returns the names of all registered databases */
            getRegistrationNames(): SafeArray<string>;

            /**
             * determines whether a database is registered under the given name.
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty
             */
            hasRegisteredDatabase(Name: string): boolean;

            /**
             * determines whether the registration data for a database given by name is read-only.
             *
             * In this case, attempts to revoke this registration will fail.
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty
             * @throws com::sun::star::container::NoSuchElementException if there is no database registered under this name
             */
            isDatabaseRegistrationReadOnly(Name: string): boolean;

            /**
             * registers a database, given by location, under a given name
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty, or the given location is invalid.
             * @throws com::sun::star::container::ElementExistException if there already is a databases registered under the given name.
             */
            registerDatabaseLocation(Name: string, Location: string): void;

            /** returns the names of all registered databases */
            readonly RegistrationNames: SafeArray<string>;

            /** revokes a previously registered listener */
            removeDatabaseRegistrationsListener(Listener: XDatabaseRegistrationsListener): void;

            /**
             * revokes the registration of a database, given by name
             * @throws com::sun::star::lang::IllegalArgumentException if the given name is empty
             * @throws com::sun::star::container::NoSuchElementException if there is no database registered under this name
             * @throws com::sun::star::lang::IllegalAccessException if the registration data for this database is read-only
             */
            revokeDatabaseLocation(Name: string): void;
        }

        /**
         * implemented by components which want to be notified of changes in the application-wide registered databases.
         * @see XDatabaseRegistrations
         * @since OOo 3.3
         */
        interface XDatabaseRegistrationsListener extends lang.XEventListener {
            /**
             * called when a the location of a registered database changed
             *
             * Note that this talks about registration data only. That is, if the actual file denoted by the database registration is moved, this is in no way
             * monitored or reported. Only (successful) calls to {@link XDatabaseRegistrations.changeDatabaseLocation()} are reported here.
             */
            changedDatabaseLocation(Event: DatabaseRegistrationEvent): void;

            /** called when a database has been registered */
            registeredDatabaseLocation(Event: DatabaseRegistrationEvent): void;

            /** called when a database registration has been revoked */
            revokedDatabaseLocation(Event: DatabaseRegistrationEvent): void;
        }

        /**
         * simplifies the accessing of data sources and their corresponding database document.
         *
         * The interface can be used to access the data source of the database document.
         * @see OfficeDatabaseDocument
         */
        interface XDocumentDataSource {
            /**
             * provides access to the one and only {@link OfficeDatabaseDocument} which the data source is based on.
             *
             * The component returned by this attribute is an {@link OfficeDatabaseDocument} .
             *
             * Though there is a 1-to-1 relationship between database documents and data sources, each of the two can exist without its counterpart, but create this
             * counterpart on request only. As a consequence, the document obtained via this attribute might be newly created, which implies that the caller is now
             * responsible for it. In particular, the caller is responsible for calling {@link com.sun.star.util.XCloseable.close()} on the document as soon as it's
             * not needed anymore.
             *
             * Additionally, if the caller does long-lasting processing on the document, it's advised to add itself as {@link com.sun.star.util.XCloseListener} to
             * the document, to prevent closing as long as the processing lasts.
             */
            DatabaseDocument: XOfficeDatabaseDocument;
        }

