        interface XSerialNumberAdapter extends uno.XInterface {
            /** Convert the SerialNumber to a sequence */
            toSequence(SerialNumber: string): SafeArray<number>;

            /** Convert the SerialNumber to a string */
            toString(SerialNumber: LibreOffice.SeqEquiv<number>): string;
        }

