        /**
         * provides methods to find the used area of the entire sheet.
         *
         * The used area is the smallest cell range that contains all cells of the spreadsheet with any contents (values, text, formulas) or visible formatting
         * (borders and background color).
         * @see com.sun.star.sheet.SheetCellCursor
         */
        interface XUsedAreaCursor extends uno.XInterface {
            /**
             * points the cursor to the end of the used area.
             * @param bExpand `TRUE` = expands the current cursor range, `FALSE` = sets size of the cursor to a single cell.
             */
            gotoEndOfUsedArea(bExpand: boolean): void;

            /**
             * points the cursor to the start of the used area.
             * @param bExpand `TRUE` = expands the current cursor range, `FALSE` = sets size of the cursor to a single cell.
             */
            gotoStartOfUsedArea(bExpand: boolean): void;
        }

        /** enables a {@link SpreadsheetView} to freeze columns and rows of the view. */
        interface XViewFreezable extends uno.XInterface {
            /**
             * freezes panes with the specified number of columns and rows.
             *
             * To freeze only horizontally, specify nRows as 0. To freeze only vertically, specify nColumns as 0.
             */
            freezeAtPosition(nColumns: number, nRows: number): void;

            /**
             * returns `TRUE` if the view has frozen panes.
             *
             * Only one of {@link XViewSplitable.getIsWindowSplit()} and {@link XViewFreezable.hasFrozenPanes()} can be `TRUE` .
             */
            hasFrozenPanes(): boolean;
        }

        /**
         * represents a pane in a view of a spreadsheet document.
         * @see com.sun.star.sheet.SpreadsheetViewPane
         */
        interface XViewPane extends uno.XInterface {
            /** returns the first column that is visible in the pane. */
            FirstVisibleColumn: number;

            /** returns the first row that is visible in the pane. */
            FirstVisibleRow: number;

            /** returns the first column that is visible in the pane. */
            getFirstVisibleColumn(): number;

            /** returns the first row that is visible in the pane. */
            getFirstVisibleRow(): number;

            /** returns the address of the cell range that consists of the cells which are visible in the pane. */
            getVisibleRange(): table.CellRangeAddress;

            /** sets the first column that is visible in the pane. */
            setFirstVisibleColumn(nFirstVisibleColumn: number): void;

            /** sets the first row that is visible in the pane. */
            setFirstVisibleRow(nFirstVisibleRow: number): void;

            /** returns the address of the cell range that consists of the cells which are visible in the pane. */
            readonly VisibleRange: table.CellRangeAddress;
        }

        /**
         * enables access to the panes in a view.
         * @deprecated Deprecated
         */
        interface XViewPanesSupplier extends uno.XInterface {
            /** returns the collection of panes in the view. */
            getViewPanes(): container.XIndexAccess;

            /** returns the collection of panes in the view. */
            readonly ViewPanes: container.XIndexAccess;
        }

        /**
         * enables a {@link SpreadsheetView} to split the view.
         * @deprecated Deprecated
         */
        interface XViewSplitable extends uno.XInterface {
            /**
             * returns `TRUE` if the view is split into individual panes.
             *
             * Only one of {@link XViewSplitable.getIsWindowSplit()} and {@link XViewFreezable.hasFrozenPanes()} can be `TRUE` .
             */
            getIsWindowSplit(): boolean;

            /** returns the column before which the view is split. */
            getSplitColumn(): number;

            /** returns the horizontal position in pixels where the view is split. */
            getSplitHorizontal(): number;

            /** returns the row before which the view is split. */
            getSplitRow(): number;

            /** returns the vertical position in pixels where the view is split. */
            getSplitVertical(): number;

            /**
             * returns `TRUE` if the view is split into individual panes.
             *
             * Only one of {@link XViewSplitable.getIsWindowSplit()} and {@link XViewFreezable.hasFrozenPanes()} can be `TRUE` .
             */
            readonly IsWindowSplit: boolean;

            /**
             * splits the view at the specified position.
             *
             * To split only horizontally, specify **nPixelY** as 0. To split only vertically, specify **nPixelX** as 0.
             */
            splitAtPosition(nPixelX: number, nPixelY: number): void;

            /** returns the column before which the view is split. */
            readonly SplitColumn: number;

            /** returns the horizontal position in pixels where the view is split. */
            readonly SplitHorizontal: number;

            /** returns the row before which the view is split. */
            readonly SplitRow: number;

            /** returns the vertical position in pixels where the view is split. */
            readonly SplitVertical: number;
        }

