        /** specifies the base service of text frames, graphic objects, and embedded objects */
        interface BaseFrame
            extends BaseFrameProperties, TextContent, drawing.XShape, beans.XPropertySet, container.XNamed
        {
            /** contains the name of the frame style that is applied to this object. */
            FrameStyleName: string;
        }

        /** specifies the properties that are provided by all text frames, graphic objects, embedded objects and frame styles. */
        interface BaseFrameProperties extends xml.UserDefinedAttributesSupplier {
            /**
             * contains the text frame the current frame is anchored to.
             *
             * The value is valid only if the AnchorType is TextContentAnchorType::AT_FRAME.
             */
            AnchorFrame: XTextFrame;

            /**
             * contains the number of the page where the objects are anchored.
             *
             * The value is valid only if the AnchorType is TextContentAnchorType::AT_PAGE.
             */
            AnchorPageNo: number;

            /** contains the color of the background of the object. */
            BackColor: util.Color;

            /** contains the name of the file filter for the background graphic. */
            BackGraphicFilter: string;

            /** determines the position of the background graphic. */
            BackGraphicLocation: style.GraphicLocation;

            /** contains the URL for the background graphic. */
            BackGraphicURL: string;

            /** If TRUE, the "BackColor" is ignored. */
            BackTransparent: boolean;

            /** contains the distance from the border to the object. */
            BorderDistance: number;

            /**
             * contains the bottom border of the object.
             * @see BaseFrame.com.sun.star.table.BorderLine
             */
            BottomBorder: table.BorderLine;

            /** contains the distance from the bottom border to the object. */
            BottomBorderDistance: number;

            /** contains the bottom margin of the object. */
            BottomMargin: number;

            /** determines if the content is protected. */
            ContentProtected: boolean;

            /**
             * contains description for the object
             *
             * The long description text can be entered to describe a object in more detail to users with screen reader software. The description is visible as an
             * alternative tag for accessibility tools.
             * @since OOo 3.2
             */
            Description: string;

            /**
             * If the property {@link FillStyle} is set to FillStyle::GRADIENT, this describes the gradient used.
             * @since LibreOffice 4.1
             */
            FillGradient: awt.Gradient;

            /**
             * If the property {@link FillStyle} is set to FillStyle::GRADIENT, this is the name of the gradient used.
             * @since LibreOffice 4.1
             */
            FillGradientName: string;

            /**
             * This enumeration selects the style the area will be filled with.
             *
             * Currently only set for gradients.
             * @since LibreOffice 4.1
             */
            FillStyle: drawing.FillStyle;

            /**
             * Grab bag of frame properties, used as a string-any map for interim interop purposes.
             * @since LibreOffice 4.2  This property is intentionally not handled by the ODF filter. Any member that should be handled there should be first moved out
             */
            FrameInteropGrabBag: SafeArray<beans.PropertyValue>;

            /**
             * contains the height of the object (1/100 mm).
             *
             * It is only valid if {@link TextEmbeddedObject.RelativeHeight} is zero.
             */
            Height: number;

            /**
             * determines the horizontal orientation of the object.
             * @see BaseFrame.HoriOrientation
             */
            HoriOrient: number;

            /**
             * contains the horizontal position of the object (1/100 mm).
             *
             * It is only valid if "HoriOrient" is HoriOrientation_NONE.
             */
            HoriOrientPosition: number;

            /**
             * determines the environment of the object to which the orientation is related.
             * @see BaseFrame.RelOrientation
             */
            HoriOrientRelation: number;

            /** contains the name of the hyperlink that is set at the object. */
            HyperLinkName: string;

            /** contains the name of the target for a hyperlink that is set at the object. */
            HyperLinkTarget: string;

            /** contains the URL of a hyperlink that is set at the object. */
            HyperLinkURL: string;

            /** determines whether the height follows the width. */
            IsSyncHeightToWidth: boolean;

            /** determines whether the width follows the height. */
            IsSyncWidthToHeight: boolean;

            /**
             * returns the actual size of the object.
             *
             * Since to obtain the correct actual size of the object not only the layouting for the frame needs to be finished but the whole document needs to be
             * formatted as well. Thus if that was not done previously it may take some while to retrieve this value.
             * @since OOo 2.0.4
             */
            LayoutSize: awt.Size;

            /**
             * contains the left border of the object.
             * @see BaseFrame.com.sun.star.table.BorderLine
             */
            LeftBorder: table.BorderLine;

            /** contains the distance from the left border to the object. */
            LeftBorderDistance: number;

            /** contains the left margin of the object. */
            LeftMargin: number;

            /** determines if the object is opaque or transparent for text. */
            Opaque: boolean;

            /** determines if the object is mirrored on even pages. */
            PageToggle: boolean;

            /** determines if the position is protected. */
            PositionProtected: boolean;

            /** determines if the object is included in printing. */
            Print: boolean;

            /**
             * contains the relative height of the object.
             *
             * It is only valid if it is greater than zero.
             */
            RelativeHeight: number;

            /**
             * contains the relation of the relative height of the object.
             *
             * It is only valid if RelativeHeight is greater than zero.
             * @see com.sun.star.text.RelOrientation
             * @since LibreOffice 4.3
             */
            RelativeHeightRelation: number;

            /**
             * contains the relative width of the object.
             *
             * It is only valid if it is greater than zero.
             */
            RelativeWidth: number;

            /**
             * contains the relation of the relative width of the object.
             *
             * It is only valid if RelativeWidth is greater than zero.
             * @see com.sun.star.text.RelOrientation
             * @since LibreOffice 4.3
             */
            RelativeWidthRelation: number;

            /**
             * contains the right border of the object.
             * @see BaseFrame.com.sun.star.table.BorderLine
             */
            RightBorder: table.BorderLine;

            /** contains the distance from the right border to the object. */
            RightBorderDistance: number;

            /** contains the right margin of the object. */
            RightMargin: number;

            /** determines if the object gets an image map from a server. */
            ServerMap: boolean;

            /** contains the type of the shadow of the object. */
            ShadowFormat: table.ShadowFormat;

            /**
             * This defines the degree of transparence of the shadow in percent.
             *
             * This is the same as setting the Color member of the {@link ShadowFormat} property to an ARGB color.
             * @since LibreOffice 4.2
             */
            ShadowTransparence: number;

            /**
             * contains the size of the object.
             * @see BaseFrame.Height
             * @see BaseFrame.Width
             */
            Size: awt.Size;

            /** determines if the size is protected. */
            SizeProtected: boolean;

            /**
             * determines the type of the surrounding text.
             * @deprecated Deprecated
             */
            Surround: WrapTextMode;

            /** determines if the text of the paragraph in which the object is anchored, wraps around the object. */
            SurroundAnchorOnly: boolean;

            /**
             * contains short title for the object
             *
             * This short title is visible as an alternative tag in HTML format. Accessibility tools can read this text.
             * @since OOo 3.2
             */
            Title: string;

            /**
             * contains the top border of the object.
             * @see BaseFrame.com.sun.star.table.BorderLine
             */
            TopBorder: table.BorderLine;

            /** contains the distance from the top border to the object. */
            TopBorderDistance: number;

            /** contains the top margin of the object. */
            TopMargin: number;

            /**
             * determines the vertical orientation of the object.
             * @see BaseFrame.VertOrientation
             */
            VertOrient: number;

            /**
             * contains the vertical position of the object (1/100 mm).
             *
             * It is only valid if {@link TextEmbeddedObject.VertOrient} is {@link VertOrientation.NONE} .
             */
            VertOrientPosition: number;

            /**
             * determines the environment of the object to which the orientation is related.
             * @see BaseFrame.RelOrientation
             */
            VertOrientRelation: number;

            /**
             * contains the width of the object (1/100 mm).
             *
             * It is only valid if {@link TextEmbeddedObject.RelativeWidth} is zero.
             */
            Width: number;

            /**
             * determines the influence of the text wrap on the positioning of the shape
             *
             * The value of this property is only evaluated for the positioning of the shape, if the text document setting ConsiderTextWrapOnObjPos is `TRUE` . Valid
             * values are given by {@link WrapInfluenceOnPosition}
             * @since OOo 2.0
             */
            WrapInfluenceOnPosition: number;
        }

        /**
         * specifies the basic service of different indexes within a document.
         * @see com.sun.star.text.DocumentIndex
         * @see com.sun.star.text.ContentIndex
         * @see com.sun.star.text.UserDefinedIndex
         * @see com.sun.star.text.IllustrationsIndex
         * @see com.sun.star.text.TableIndex
         * @see com.sun.star.text.ObjectIndex
         */
        interface BaseIndex extends XDocumentIndex, util.XRefreshable {
            /** specifies the color of the background. */
            BackColor: util.Color;

            /** contains the name of the filter of the graphic file that is displayed as background graphic */
            BackGraphicFilter: string;

            /**
             * determines the position of the background graphic.
             * @see GraphicLocation
             */
            BackGraphicLocation: style.GraphicLocation;

            /** contains the URL of a graphic file that is displayed as background graphic */
            BackGraphicURL: string;

            /** If `TRUE` , the background color value in "BackColor" is not visible. */
            BackTransparent: boolean;

            /** the text section containing the content of the index */
            ContentSection: XTextSection;

            /**
             * determines if the content of the document index is created from the complete document content or from the current chapter only.
             *
             * It is not available in the bibliography
             */
            CreateFromChapter: boolean;

            /** the text section containing the header of the index */
            HeaderSection: XTextSection;

            /** determines if the index is protected. */
            IsProtected: boolean;

            /**
             * returns the interface of the level format of the index.
             *
             * The description of the format of the levels depends on the type of the document index.
             * @see DocumentIndexLevelFormat
             */
            LevelFormat: container.XIndexReplace;

            /** contains the name of the paragraph style that is applied to the heading. */
            ParaStyleHeading: string;

            /** contains the name of the paragraph style that is applied to the 1st level. */
            ParaStyleLevel1: string;

            /** contains the name of the paragraph style that is applied to the 10th level. */
            ParaStyleLevel10: string;

            /** contains the name of the paragraph style that is applied to the 2nd level. */
            ParaStyleLevel2: string;

            /** contains the name of the paragraph style that is applied to the 3rd level. */
            ParaStyleLevel3: string;

            /** contains the name of the paragraph style that is applied to the 4th level. */
            ParaStyleLevel4: string;

            /** contains the name of the paragraph style that is applied to the 5th level. */
            ParaStyleLevel5: string;

            /** contains the name of the paragraph style that is applied to the 6th level. */
            ParaStyleLevel6: string;

            /** contains the name of the paragraph style that is applied to the 7th level. */
            ParaStyleLevel7: string;

            /** contains the name of the paragraph style that is applied to the 8th level. */
            ParaStyleLevel8: string;

            /** contains the name of the paragraph style that is applied to the 9th level. */
            ParaStyleLevel9: string;

            /** contains the name of the paragraph style that is applied to the separator level. */
            ParaStyleSeparator: string;

            /** contains the column interface. */
            TextColumns: XTextColumns;

            /** contains the title of the index. */
            Title: string;
        }

        /**
         * is a {@link TextRange} which is explicitly marked as an index entry. This is the base service of index marks for {@link DocumentIndex} , {@link
         * ContentIndex} , and {@link UserIndex} .
         */
        interface BaseIndexMark extends TextContent {
            /**
             * the string that will be inserted into the corresponding index. If AlternativeText is empty then the string that is marked by the {@link TextRange} is
             * inserted into the index.
             */
            AlternativeText: string;
        }

        /**
         * specifies service of bibliography within a text document.
         * @see com.sun.star.text.BaseIndex
         */
        interface Bibliography extends BaseIndex {
            /** contains the locale of the index. */
            Locale: lang.Locale;

            /** contains the name of the sort algorithm that is used to sort the entries. */
            SortAlgorithm: string;
        }

        /** A bookmark is a {@link TextContent} , which is like a jump target or a label. */
        interface Bookmark extends TextContent, container.XNamed {}

        /** This service specifies a collection of {@link Bookmarks} . */
        interface Bookmarks extends container.XNameAccess, container.XIndexAccess {}

        /**
         * represents a singe cell within a text table.
         * @see com.sun.star.text.TextTable
         */
        interface Cell extends CellProperties, table.CellProperties, table.XCell, XText {}

        /**
         * service that holds all cell properties of a text table cell in a text document.
         * @see com.sun.star.text.Cell
         */
        interface CellProperties extends xml.UserDefinedAttributesSupplier, beans.XPropertySet {
            /** contains the background color. */
            BackColor: util.Color;

            /** contains the name of the graphic filter of the background graphic. */
            BackGraphicFilter: string;

            /** determines the position of the background graphic. */
            BackGraphicLocation: style.GraphicLocation;

            /** contains the URL to the background graphic. */
            BackGraphicURL: string;

            /** determines whether the background is transparent. */
            BackTransparent: boolean;

            /** contains the bottom border line. */
            BottomBorder: table.BorderLine;

            /** contains the distance of the bottom border. */
            BottomBorderDistance: number;

            /** contains the cell name, see SwXTextTable::getCellByName for more information */
            CellName: string;

            /** determines whether the cell is write protected or not. */
            IsProtected: boolean;

            /** contains the left border line. */
            LeftBorder: table.BorderLine;

            /** contains the distance of the left border. */
            LeftBorderDistance: number;

            /** contains the number format. */
            NumberFormat: number;

            /** contains the right border line. */
            RightBorder: table.BorderLine;

            /** contains the distance of the right border. */
            RightBorderDistance: number;

            /** contains the text section the text table is contained in if there is any. */
            TextSection: XTextSection;

            /** contains the top border line. */
            TopBorder: table.BorderLine;

            /** contains the distance of the top border. */
            TopBorderDistance: number;

            /**
             * the vertical orientation of the text inside of the table cells in this row.
             * @see VertOrientation
             */
            VertOrient: number;
        }

        /**
         * area of cells within a text table.
         * @see com.sun.star.text.TextTable
         */
        interface CellRange
            extends
                style.CharacterProperties,
                style.CharacterPropertiesAsian,
                style.CharacterPropertiesComplex,
                style.ParagraphProperties,
                style.ParagraphPropertiesAsian,
                style.ParagraphPropertiesComplex,
                table.XCellRange,
                sheet.XCellRangeData,
                chart.XChartDataArray
        {
            /** contains color of the background. */
            BackColor: util.Color;

            /** contains the filter name of the background graphic. */
            BackGraphicFilter: string;

            /** determines the location of the background graphic. */
            BackGraphicLocation: style.GraphicLocation;

            /** contains the URL of the background graphic. */
            BackGraphicURL: string;

            /** determines if the background color is transparent. */
            BackTransparent: boolean;

            /** determines if the first column of the table should be treated as axis labels when a chart is to be created. */
            ChartColumnAsLabel: boolean;

            /** determines if the first row of the table should be treated as axis labels when a chart is to be created. */
            ChartRowAsLabel: boolean;

            /** contains the number format. */
            NumberFormat: number;
        }

        /**
         * extends a {@link TextFrame} which shares the same {@link Text} with other {@link ChainedTextFrame} instances that will make the text flow through the
         * chained frames. The text flows in the next frame if there is no space left in the current frame.
         */
        interface ChainedTextFrame extends TextFrame {
            /**
             * name of the previous frame in the chain
             *
             * An empty string indicates that there is no previous frame.
             */
            ChainNextName: string;

            /**
             * name of the next frame in the chain
             *
             * An empty string indicates that there is no next frame.
             */
            ChainPrevName: string;
        }

        /**
         * describes the rules for chapter numbering in a text document.
         *
         * Some of the properties that are available in the interface are ignored here.
         *
         * The type of numbering can only be: NUM_CHARS_UPPER_LETTER, NUM_CHARS_LOWER_LETTER, NUM_ROMAN_UPPER, NUM_ROMAN_LOWER, NUM_ARABIC, or NUM_NUMBER_NONE
         *
         * In the {@link com.sun.star.style.NumberingAlignment} only the field {@link com.sun.star.style.NumberingAlignment.Alignment} is applied.
         *
         * Depending on the numbering types, the parameters for bullets or bit maps may be ignored. The character style name for the numbering symbol is also
         * ignored.
         */
        interface ChapterNumberingRule extends style.NumberingRule {
            /**
             * contains the name of the paragraph style that marks this heading level.
             *
             * It is necessary that each style name appears only once in the sequence of numbering rules.
             */
            HeadingStyleName: string;
        }

        /**
         * specifies service of content indexes within a document.
         * @see com.sun.star.text.BaseIndex
         */
        interface ContentIndex extends BaseIndex {
            /** contains `TRUE` if the document index marks are included in this index. */
            CreateFromMarks: boolean;

            /** determines if the document index is created from outlines. */
            CreateFromOutline: boolean;

            /** determines the depth of outline levels that are included into the content index. */
            Level: number;

            /**
             * contains the interface to access the paragraph style names that are included in this index.
             * @see DocumentIndexParagraphStyles
             */
            LevelParagraphStyles: container.XIndexReplace;
        }

        /** is a {@link TextRange} which is explicitly marked as an index entry for a {@link ContentIndex} . */
        interface ContentIndexMark extends TextContent, BaseIndexMark {
            /** contains the level into which the index mark will be inserted into the content index. */
            Level: number;
        }

        /** provides default settings of a text component for paragraph and character properties. */
        interface Defaults
            extends
                style.CharacterProperties,
                style.ParagraphProperties,
                style.CharacterPropertiesAsian,
                style.CharacterPropertiesComplex,
                style.ParagraphPropertiesAsian,
                style.ParagraphPropertiesComplex,
                beans.XPropertySet
        {
            /** default tab-distance to be used. */
            TabStopDistance: number;
        }

        /**
         * is a {@link TextField} which is not specified by itself, but dependent on a {@link TextFieldMaster} .
         * @see TextFieldMaster
         */
        interface DependentTextField extends TextField, XDependentTextField {}

        /**
         * specifies service of content indexes within a document.
         * @see com.sun.star.text.BaseIndex
         */
        interface DocumentIndex extends BaseIndex {
            /** contains all index marks that are related to this index. */
            DocumentIndexMarks: SafeArray<XDocumentIndexMark>;

            /** determines if the similarity of index entries is checked case sensitively. */
            IsCaseSensitive: boolean;

            /** contains the locale of the index. */
            Locale: lang.Locale;

            /** determines the name of the character style that is applied to the number of a page where main index entry is located. */
            MainEntryCharacterStyleName: string;

            /** contains the name of the sort algorithm that is used to sort the entries. */
            SortAlgorithm: string;

            /** determines if alphabetical separators are generated. */
            UseAlphabeticalSeparators: boolean;

            /** determines if same entries on different pages are combined into one index entry. */
            UseCombinedEntries: boolean;

            /** determines if following page numbers are displayed using a dash. */
            UseDash: boolean;

            /** determines if a index entry is generated for each primary/secondary key. */
            UseKeyAsEntry: boolean;

            /** determines if following page numbers are displayed using a "pp.". */
            UsePP: boolean;

            /** determines if all entries start with a capital letter. */
            UseUpperCase: boolean;
        }

        /** provides access to all indexes in a document. */
        interface DocumentIndexes extends container.XNameAccess, container.XIndexAccess {}

        /** is a {@link TextRange} which is explicitly marked as an index entry for a {@link DocumentIndex} . */
        interface DocumentIndexMark extends TextContent, BaseIndexMark {
            /** determines if this entry is a main entry. In a document index this entry will be emphasized by assigning a character style to it. */
            IsMainEntry: boolean;

            /** contains the primary key of the index entry. It is used to build a hierarchical document index. */
            PrimaryKey: string;

            /** contains the secondary key of the index entry. It is used to build a hierarchical document index. */
            SecondaryKey: string;
        }

        /**
         * is a {@link TextRange} which is explicitly marked as an index entry for a {@link DocumentIndex} . For Asian languages the user can provide an
         * additional string which is used for sorting. If the user does not provide these strings, they are not considered for sorting.
         * @since OOo 1.1.2
         */
        interface DocumentIndexMarkAsian {
            /** contains the reading of the primary key of the index entry. It is used to build a hierarchical document index. */
            PrimaryKeyReading: string;

            /** contains the reading the secondary key of the index entry. It is used to build a hierarchical document index. */
            SecondaryKeyReading: string;

            /** contains the reading of the string which has been chosen for the index entry. */
            TextReading: string;
        }

        /** describes properties that apply to the whole text document. */
        interface DocumentSettings extends document.Settings, PrintSettings, beans.XPropertySet {
            /**
             * specifies if paragraph and table spacing is added at the bottom of table cells
             *
             * This property controls, if the spacing of the last paragraph respectively table of a table cell is added at the bottom of this table cells If `TRUE`
             * (default for documents since OpenOffice.org 2.0), the spacing of the last paragraph respectively table of a table cell is added at the bottom of this
             * table cell. If `FALSE` (typically for documents till OpenOffice.org 1.1), the spacing of the last paragraph respectively table of a table cell isn't
             * added at the bottom of this table cell.
             * @since OOo 2.0
             */
            AddParaSpacingToTableCells: boolean;

            /**
             * specifies if spacing between paragraphs and tables is to be added.
             *
             * If between two paragraphs, two tables, or a paragraph and a table, you have defined spacing above and below each object, usually only the larger one
             * of the two spaces is used. If the spacing between the objects are to be added this property has to be `TRUE` .
             */
            AddParaTableSpacing: boolean;

            /**
             * specifies if top paragraph spacing is applied to paragraphs on the first page of text documents.
             *
             * If `TRUE` , the paragraph or table spacing to the top will also be effective at the beginning of a page or column if the paragraph or table is
             * positioned on the first page of the document. The same applies for a page break.
             */
            AddParaTableSpacingAtStart: boolean;

            /**
             * specifies the alignment of tab stops in text documents.
             *
             * If `TRUE` centered and right-aligned paragraphs containing tabs are formatted as a whole in the center or aligned to the right. If `FALSE` , only the
             * text to the right of the last tab, for example, is aligned to the right, while the text to the left remains where it is.
             */
            AlignTabStopPosition: boolean;

            /**
             * specifies if charts in text documents are updated automatically.
             *
             * This has no effect if "FieldAutoUpdate" is `FALSE` .
             */
            ChartAutoUpdate: boolean;

            /**
             * specifies if the text wrap of floating screen objects are considered in a specified way in the positioning algorithm.
             *
             * This property controls how floating screen objects (Writer fly frames and drawing objects) are positioned. If `TRUE` , the object positioning
             * algorithm will consider the text wrap style, set at the floating screen object. The attribute {@link BaseFrameProperties.WrapInfluenceOnPosition}
             * specifies how the text wrap is considered. If `FALSE` (default value), the former object positioning algorithm (known from OpenOffice.org 1.1) is
             * applied.
             * @since OOo 2.0
             */
            ConsiderTextWrapOnObjPos: boolean;

            /**
             * specifies if the document has been created as a label document.
             *
             * This property indicates that the document contains multiple text frames and that the content of one frame is duplicated into the other frames by
             * internally linked text sections.
             */
            IsLabelDocument: boolean;

            /**
             * specifies if Math objects should automatically vertically aligned to match the baseline of the surrounding text.
             *
             * If activated formula object that are anchored 'As Character' will be vertically aligned to have their baseline match with the one from the text.
             * @since OOo 3.4
             */
            MathBaselineAlignment: boolean;

            /**
             * specifies if the contents of links in the global document are saved or not.
             *
             * This property applies only for master documents.
             *
             * **Note** : This name is a bit misleading, it should be something like `SaveLinkedDocumentContent` .
             */
            SaveGlobalDocumentLinks: boolean;

            /**
             * specifies if the former (till OpenOffice.org 1.1) or the new line spacing formatting is applied.
             *
             * This property controls how a set line spacing at a paragraph influences the formatting of the text lines and the spacing between paragraphs. If `TRUE`
             * , the formatting till OpenOffice.org 1.1 is applied. This means, that a proportional line spacing is applied above and below a text line and that the
             * maximum of the line spacing value between two paragraph is added respectively reckoned up with the paragraph spacing (adding or reckoning up is
             * controlled by document option AddParaTableSpacing). If `FALSE` (default for documents since OpenOffice.org 2.0), a proportional line spacing is only
             * applied below a text line and it's always added to the paragraph spacing between two paragraphs.
             * @since OOo 2.0
             */
            UseFormerLineSpacing: boolean;

            /**
             * specifies if the former (till OpenOffice.org 1.1) or the new object positioning is applied.
             *
             * This property controls how floating screen objects (Writer fly frames and drawing objects are positioned. If `TRUE` , the object positioning till
             * OpenOffice.org 1.1 is applied. This means, that the top of a paragraph, at which a floating screen object orients its vertical position, includes the
             * lower spacing and the line spacing of the previous paragraph. If `FALSE` (default for documents since OpenOffice.org 2.0), the top of a paragraph, at
             * which a floating screen object orients its vertical position, doesn't include the lower spacing and the line spacing of the previous paragraph.
             * @since OOo 2.0
             */
            UseFormerObjectPositioning: boolean;
        }

        /** This service specifies a footnote or an endnote in a {@link TextDocument} . */
        interface Footnote extends XFootnote, XText {
            /**
             * contains an internal identifier for the use as SequenceNumber property in reference fields.
             * @see com.sun.star.text.textfield.GetReference.
             */
            ReferenceId: number;
        }

        /** provides access to the settings of footnotes or endnotes in a (text) document. */
        interface FootnoteSettings {
            /**
             * contains the name of the character style that is used for footnote/endnote anchor in the text.
             * @since OOo 2.0
             */
            AnchorCharStyleName: string;

            /**
             * contains the string at the restart of the footnote text after a break.
             *
             * For footnotes only.
             */
            BeginNotice: string;

            /** contains the name of the character style that is used for the label in front of the footnote/endnote text. */
            CharStyleName: string;

            /**
             * contains the string at the end of a footnote part in front of a break.
             *
             * For footnotes only.
             */
            EndNotice: string;

            /**
             * contains the type of the counting of the footnote numbers.
             *
             * For footnotes only.
             * @see FootnoteNumbering
             */
            FootnoteCounting: number;

            /** contains the numbering type for the numbering of the footnotes/endnotes. */
            NumberingType: number;

            /** contains the page style that is used for the page that contains the footnote/endnote texts */
            PageStyleName: string;

            /** contains the paragraph style that is used for the footnote/endnote text. */
            ParaStyleName: string;

            /**
             * If `TRUE` , the footnote text is shown at the end of the document.
             *
             * For footnotes only.
             */
            PositionEndOfDoc: boolean;

            /** contains the prefix for the footnote/endnote symbol. */
            Prefix: string;

            /** contains the first number of the automatic numbering of footnotes/endnotes. */
            StartAt: number;

            /** contains the suffix for the footnote/endnote symbol. */
            Suffix: string;
        }

        /**
         * A text document is a model component which contains text structured by paragraphs.
         *
         * Each paragraph and each portion of text can be fitted with some attributes (technically properties).
         *
         * Its declared as generic text document, because its function is needed by different derived services (TextDocument/WebDocument/GlobalDocument).
         *
         * In addition, all text objects can be searched.
         */
        interface GenericTextDocument
            extends
                document.OfficeDocument,
                lang.XMultiServiceFactory,
                XTextDocument,
                util.XSearchable,
                util.XRefreshable,
                tiledrendering.XTiledRenderable,
                XFootnotesSupplier,
                XEndnotesSupplier,
                util.XReplaceable,
                XPagePrintable,
                XReferenceMarksSupplier,
                XChapterNumberingSupplier,
                beans.XPropertySet,
                XTextGraphicObjectsSupplier,
                XTextEmbeddedObjectsSupplier,
                XTextTablesSupplier,
                style.XStyleFamiliesSupplier,
                XBookmarksSupplier,
                XDocumentIndexesSupplier,
                XTextFieldsSupplier,
                XTextFramesSupplier,
                XTextSectionsSupplier,
                util.XNumberFormatsSupplier
        {
            addEventListener(Listener: document.XEventListener | lang.XEventListener): void;

            /** contains the count of all characters in the document. */
            CharacterCount: number;

            /** contains the identifier of the default locale of the document. */
            CharLocale: lang.Locale;

            /**
             * specifies the concordance file taken into account when creating an index.
             *
             * When no concordance file should be used the string is empty. Used for text documents only.
             * @since OOo 1.1.2
             */
            IndexAutoMarkFileURL: string;

            /** contains the count of all paragraphs in the document. */
            ParagraphCount: number;

            /**
             * specifies if change recording is active.
             * @since OOo 1.1.2
             */
            RecordChanges: boolean;
            removeEventListener(Listener: document.XEventListener | lang.XEventListener): void;

            /**
             * specifies the first 4 digit year to be used when years are given in 2 digits.
             *
             * Example: if set to 1930 Oct-12-29 will be interpreted as Oct-12-2029 Oct-12-30 will be interpreted as Oct-12-1930 Oct-12-02 will be interpreted as
             * Oct-12-2002
             * @since OOo 1.1.2
             */
            TwoDigitYear: number;

            /**
             * contains the count of all words in the document.
             * @see WordSeparator
             */
            WordCount: number;

            /**
             * contains a string that consists of characters that mark the separation of words in counting the words in a document.
             *
             * I.e. slash and backslash. Whitespace (tab stop, space, paragraph break, line break) always separate words.
             * @see WordCount
             */
            WordSeparator: string;
        }

        /** specifies a service that provides access to the settings of a text module. */
        interface GlobalSettings extends view.XPrintSettingsSupplier, view.XViewSettingsSupplier {}

        /**
         * describes the cropping of graphic objects. Cropping means to show only parts of the object.
         *
         * Negative values cut the visible area; positive values extend the visible area by filling it with background color. The absolute sum of top and bottom
         * crop must be smaller than the objects original height. The absolute sum of the left and right crop must be smaller than the object's original width.
         *
         * If this property is applied to a graphic object, then this object will correct these values if necessary.
         */
        interface GraphicCrop {
            /** contains the bottom value to cut (if negative) or to extend (if positive) */
            Bottom: number;

            /** contains the left value to cut (if negative) or to extend (if positive) */
            Left: number;

            /** contains the right value to cut (if negative) or to extend (if positive) */
            Right: number;

            /** contains the top value to cut (if negative) or to extend (if positive) */
            Top: number;
        }

        /**
         * describes the horizontal orientation of an object.
         *
         * If `HorizontalOrientation == HORI_NONE` , then the value "XPos" describes the distance from the left border of the context. Otherwise "XPos" is
         * ignored.
         *
         * The following flags are used to adapt the position of the object to odd and even pages. If "PositionToggle" is set, then the horizontal position is
         * mirrored.
         */
        interface HoriOrientationFormat {
            /** determines the horizontal alignment of an object. The values refer to com::sun::star::HoriOrientation. */
            HorizontalOrientation: number;

            /**
             * determines the reference position of the horizontal alignment.
             * @see com.sun.star.text.RelOrientation
             */
            HorizontalRelation: number;

            /** determines if the orientation toggles between left and right pages. */
            PositionToggle: boolean;

            /** contains the distance from the left border. Only valid if the property HorizontalOrientation contains the value HORI_NONE. */
            XPos: number;
        }

        /**
         * specifies service of illustration indexes within a document.
         * @see com.sun.star.text.BaseIndex
         */
        interface IllustrationsIndex extends BaseIndex {
            CreateFromLabels: boolean;
            LabelCategory: string;
            LabelDisplayType: number;
        }

        /**
         * is a {@link TextContent} that can be used to attach RDF metadata to a range of text.
         * @since OOo 3.2
         */
        interface InContentMetadata
            extends TextContent, rdf.XMetadatable, container.XEnumerationAccess, container.XChild
        {}

        /** is thrown whenever a method gets a {@link TextContent} as an actual argument when the text content cannot be used for that operation. */
        interface InvalidTextContentException extends uno.Exception {
            /** contains the interface of the text content that caused the exception. */
            TextContent: XTextContent;
        }

        /** provides access to the settings of the line numbering. */
        interface LineNumberingProperties {
            /** The name of the character style that is used for the line number. */
            CharStyleName: string;

            /** If `TRUE` , empty lines are counted. */
            CountEmptyLines: boolean;

            /** If `TRUE` , lines in frames are included in counting. */
            CountLinesInFrames: boolean;

            /** specifies the distance between the line number and the start or end of the text area. */
            Distance: number;

            /** Line numbers are shown on every **Interval** th line. */
            Interval: number;

            /** If `TRUE` , line numbering is used. */
            IsOn: boolean;

            /** specifies the type of the numbering. */
            NumberingType: number;

            /** specifies the position of the line number (constant LineNumberPositions left/right/inside/outside). */
            NumberPosition: number;

            /**
             * specifies if the line numbering should start from the beginning at each page.
             *
             * If set to `FALSE` the line numbering will be continuous.
             * @since OOo 2.0
             */
            RestartAtEachPage: boolean;

            /** The line separator is shown every **SeparatorInterval** th line. */
            SeparatorInterval: number;

            /** specifies the string that is used for the line separator. */
            SeparatorText: string;
        }

        /**
         * Gives access to mail merge functionality.
         * @since OOo 1.1.2
         */
        interface MailMerge
            extends task.XJob, util.XCancellable, beans.XPropertySet, XMailMergeBroadcaster, sdb.DataAccessDescriptor
        {
            /**
             * contains the connection to the database.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            ActiveConnection: sdbc.XConnection;

            /**
             * contains the name of the data base column that contains the e-Mail address to the e-Mail to.
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            AddressFromColumn: string;

            /**
             * contains the name of the document filter to save the attached mail merge document. This property is only valid if "SendAsAttachment" is set to `TRUE`
             * .
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            AttachmentFilter: string;

            /**
             * contains the name of the attachment. This property is only valid if "SendAsAttachment" is set to `TRUE` .
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            AttachmentName: string;

            /**
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            BlindCopiesTo: SafeArray<string>;

            /**
             * contains the database command.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            Command: string;

            /**
             * determines the type of the database command as described in {@link com.sun.star.sdb.CommandType}
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            CommandType: number;

            /**
             * contains a list of e-Mail addresses to
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            CopiesTo: SafeArray<string>;

            /**
             * contains the name of the data source that is to be used for merging.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            DataSourceName: string;

            /**
             * contains the URL of a text document that is to be processed.
             *
             * If this property is not set an empty document is created.
             */
            DocumentURL: string;

            /**
             * returns if escape processing is on or off.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            EscapeProcessing: boolean;

            /**
             * determines whether file names of created files are generated using the content of a database column.
             *
             * This property is only evaluated for file output.
             */
            FileNameFromColumn: boolean;

            /**
             * contains the name of the column to generate the output file names.
             *
             * If FileNameFromColumn is true the content of the related column is added to the OutputURL.
             *
             * If "OutputURL" or "FileNamePrefix" are empty the missing value is generated from the location or title of the source documents.
             *
             * This property is only evaluated for file output.
             */
            FileNamePrefix: string;

            /**
             * contains a filter expression for an SQL statement.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            Filter: string;

            /**
             * Contains the password of the incoming mail server. It is necessary to set this if the mail server configuration is set to "SMTP after POP"
             * authentication and the password is not already stored in the configuration for security reasons.
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            InServerPassword: string;

            /**
             * contains the text of the mail body. This property is only valid if the property "SendAsAttachment" is set to `TRUE`
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            MailBody: string;

            /**
             * provides access to the model of the document to be processed.
             *
             * This property will automatically be set to the documents model if a document URL was set.
             */
            Model: frame.XModel;

            /**
             * determines the destination of the mail merge action.
             * @see com.sun.star.text.MailMergeType
             */
            OutputType: number;

            /**
             * contains the path where generated files are created.
             *
             * If "OutputURL" or "FileNamePrefix" are empty the missing value is generated from the location or title of the source documents.
             *
             * This property is only evaluated for file output.
             */
            OutputURL: string;

            /**
             * Contains the password of the outgoing mail server. It is necessary to set this if the password is not already stored in the configuration for security
             * reasons.
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            OutServerPassword: string;

            /**
             * contains the properties that are defined in < {@link com.sun.star.view.PrintOptions} >.
             *
             * This property is only evaluated for printer output.
             * @since OOo 2.0
             */
            PrintOptions: SafeArray<beans.PropertyValue>;

            /**
             * provides access to a {@link com.sun.star.sdbc.XResultSet} of a {@link com.sun.star.sdbc.ResultSet} service.
             *
             * Note that any superservices of {@link com.sun.star.sdbc.ResultSet} are also allowed. Especially, this member can denote an instance of the {@link
             * com.sun.star.sdb.RowSet} , or an instance obtained by calling {@link com.sun.star.sdb.XResultSetAccess.createResultSet()} on such a {@link
             * com.sun.star.sdb.RowSet} . This becomes important in conjunction with the {@link Selection} property.
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            ResultSet: sdbc.XResultSet;

            /**
             * determines that the output of the mail merge is save in one single file.
             *
             * This property is only evaluated for file output.
             * @since OOo 2.0
             */
            SaveAsSingleFile: boolean;

            /**
             * contains the name of the document filter to save the output file(s).
             *
             * This property is only evaluated for file output.
             * @since OOo 2.0
             */
            SaveFilter: string;

            /**
             * contains a selection that refers to bookmarks of the ResultSet.
             *
             * This property is relevant in conjunction with the {@link ResultSet} only. A single element of this array describes a bookmark relative to the result
             * set. ;  Note that this implies that the {@link ResultSet} needs to support the {@link com.sun.star.sdbcx.XRowLocate} interface.
             *
             * If this array is empty, the whole result set, as described by {@link ResultSet} respectively the triple ( {@link DataSourceName} , {@link CommandType}
             * , {@link Command} ).
             *
             * For the interaction of this property with other data access relevant properties, see the {@link com.sun.star.sdb.DataAccessDescriptor} service.
             */
            Selection: SafeArray;

            /**
             * determines that the created mail merge document is sent as attachment.
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            SendAsAttachment: boolean;

            /**
             * determines that the created mail merge document is sent as body in HTML format. This property is only valid if the property "SendAsAttachment" is set
             * to `FALSE` .
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            SendAsHTML: boolean;

            /**
             * determines whether single print jobs will be generated per output document.
             *
             * This property is only evaluated for printer output.
             */
            SinglePrintJobs: boolean;

            /**
             * contains the subject of the e-Mail message.
             *
             * This property is only evaluated for e-Mail output.
             * @since OOo 2.0
             */
            Subject: string;
        }

        /**
         * represents a mail merge event.
         *
         * This type of event is being send by the mail merge service right before the merging of the next document to be processed. This allows for example to
         * modify the document specifically before it gets merged.
         * @see com.sun.star.text.MailMerge
         * @since OOo 1.1.2
         */
        interface MailMergeEvent extends lang.EventObject {
            /** The model of the document to be processed next. */
            Model: frame.XModel;
        }

        /** provides access to a numbering level as part of the Numbering Rules. */
        interface NumberingLevel {
            /** adjusts the numbering (HoriOrientation_LEFT/RIGHT/CENTER) */
            Adjust: number;

            /** contains the symbol in the given font. This is only valid if the numbering type is {@link com.sun.star.style.NumberingType.CHAR_SPECIAL} . */
            BulletChar: string;

            /** contains the color for the symbol. This is only valid if the numbering type is {@link com.sun.star.style.NumberingType.CHAR_SPECIAL} . */
            BulletColor: util.Color;

            /** the font used to paint the bullet. */
            BulletFont: awt.FontDescriptor;

            /** the name of the font for the symbol. This is only valid if the numbering type is {@link com.sun.star.style.NumberingType.CHAR_SPECIAL} . */
            BulletFontName: string;

            /**
             * the ID of the symbol in the given font. This is only valid if the numbering type is {@link com.sun.star.style.NumberingType.CHAR_SPECIAL} .
             * @deprecated Deprecated
             */
            BulletId: number;

            /**
             * contains the size of the symbol relative to the high of the paragraph. This is only valid if the numbering type is {@link
             * com.sun.star.style.NumberingType.CHAR_SPECIAL} .
             */
            BulletRelSize: number;

            /** Name of the character style that is used for the numbering symbol. */
            CharStyleName: string;

            /**
             * additional line indent for the first text line <p>
             *
             * Specifies the first line indent.
             *
             * Only of relevance, if PositionAndSpaceMode equals LABEL_ALIGNMENT.
             *
             * </p>
             * @since OOo 3.0
             */
            FirstLineIndent: number;

            /** specifies the offset between the beginning of the first line and the beginning of the following lines of the paragraph. */
            FirstLineOffset: number;

            /** the bitmap containing the bullet. */
            GraphicBitmap: awt.XBitmap;

            /** size of the graphic that is used as bullet. */
            GraphicSize: awt.Size;

            /**
             * the URL of the graphic file that is used as the numbering symbol.
             *
             * This is only valid if the numbering type is {@link com.sun.star.style.NumberingType.BITMAP} .
             */
            GraphicURL: string;

            /**
             * contains the name of the paragraph style that is interpreted as the header of this level. It is only contained in the levels of chapter numbering
             * rules.
             */
            HeadingStyleName: string;

            /**
             * indentation of the text lines <p>
             *
             * Specifies the indent of the text lines
             *
             * Only of relevance, if PositionAndSpaceMode equals LABEL_ALIGNMENT.
             *
             * </p>
             * @since OOo 3.0
             */
            IndentAt: number;

            /**
             * character following the list label <p>
             *
             * Specifies the character following the list label.
             *
             * For valid values see com::sun::star::text::LabelFollow.
             *
             * Only of relevance, if PositionAndSpaceMode equals LABEL_ALIGNMENT.
             *
             * </p>
             * @since OOo 3.0
             */
            LabelFollowedBy: number;

            /** specifies the left margin of the numbering */
            LeftMargin: number;

            /**
             * list tab position <p>
             *
             * Specifies the position of the list tab stop - only non-negative
             *
             * values are allowed.
             *
             * Only of relevance, if PositionAndSpaceMode equals LABEL_ALIGNMENT
             *
             * and LabelFollowedBy equal LABELFOLLOW_LISTTAB
             *
             * </p>
             * @since OOo 3.0
             */
            ListtabStopPosition: number;

            /** specifies the type of numbering. */
            NumberingType: number;

            /**
             * contains the name of the paragraph style that should use this numbering. This is ignored for chapter numbering rules, use HeadingStyleName.
             * @since LibreOffice 3.6
             */
            ParagraphStyleName: string;

            /** number of upper levels that are included in the current numbering symbol. */
            ParentNumbering: number;

            /**
             * position and space mode <p>
             *
             * Specifies the position and space mode of the numbering level.
             *
             * For valid values see com::sun::star::text::PositionAndSpaceMode.
             *
             * If it equals LABEL_WIDTH_AND_POSITION, properties Adjust,
             *
             * LeftMargin, SymbolTextDistance and FirstLineOffset are used.
             *
             * If it equals LABEL_ALIGNMENT, properties Adjust, LabelFollowedBy,
             *
             * ListtabStopPosition, FirstLineIndent, IndentAt are used.
             *
             * </p>
             * @since OOo 3.0
             */
            PositionAndSpaceMode: number;

            /** the prefix of the numbering symbol. */
            Prefix: string;

            /**
             * specifies the start value for the numbering.
             *
             * This property is only valid if the numbering type is not {@link com.sun.star.style.NumberingType.BITMAP} or {@link
             * com.sun.star.style.NumberingType.CHAR_SPECIAL} .
             */
            StartWith: number;

            /** the suffix of the numbering symbol. */
            Suffix: string;

            /** specifies the distance between the numbering symbol and the text of the paragraph. */
            SymbolTextDistance: number;

            /**
             * contains the vertical orientation of a graphic.
             *
             * It is set using {@link com.sun.star.text.VertOrientation} .
             */
            VertOrient: number;
        }

        /**
         * provides access to the numbering rules.
         *
         * Numbering rules may be set at a {@link Paragraph} object. The numbering rules are levels of property values. Each level contains equal properties.
         */
        interface NumberingRules extends container.XIndexReplace, beans.XPropertySet {
            /** id of default list for the numbering rules instance */
            DefaultListId: string;

            /** determines if the margins are absolute or relative to the preceding numbering level. */
            IsAbsoluteMargins: boolean;

            /** determines if the numbering rules are automatically created as opposed to numbering rules that are part of a numbering style. */
            IsAutomatic: boolean;

            /** determines if the numbering levels are counted continuously or if each numbering level is counted separately. */
            IsContinuousNumbering: boolean;

            /** contains the name of the numbering rules. It is used to identify a certain numbering rules property */
            Name: string;

            /** This numbering is used in the outline of the document (e.g. headings). */
            NumberingIsOutline: boolean;

            /** the type of numbering (Arabic, characters, roman numbers, etc.). */
            NumberingType: number;
        }

        /** specifies a style sheet numberings within a {@link com.sun.star.text.Text} . */
        interface NumberingStyle extends style.Style, NumberingRules {}

