        const enum WebDAVHTTPMethod {
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.9"} */
            CONNECT = 7,
            /**
             * Copy the source to the target folder.
             *
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.8"}
             */
            COPY = 12,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.7"} */
            DELETE = 4,
            /**
             * Get a list of all folders.
             *
             * HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.3"}
             */
            GET = 0,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.4"} */
            HEAD = 1,
            /**
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.10"}
             */
            LOCK = 14,
            /**
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.3"}
             */
            MKCOL = 11,
            /**
             * Move the source to the target folder.
             *
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.9"}
             */
            MOVE = 13,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.2"} */
            OPTIONS = 6,
            /** HTTP request method as defined in [RFC 5789: PATCH Method for HTTP]{@link url="http://tools.ietf.org/html/rfc5789"} */
            PATCH = 8,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.5"} */
            POST = 2,
            /**
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.1"}
             */
            PROPFIND = 9,
            /**
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.2"}
             */
            PROPPATCH = 10,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.6"} */
            PUT = 3,
            /** HTTP request method as defined in [RFC 2616: Hypertext Transfer Protocol  -  HTTP/1.1]{@link url="http://tools.ietf.org/html/rfc2616#section-9.8"} */
            TRACE = 5,
            /**
             * WebDAV methods as defined in [HTTP Extensions for Web Distributed Authoring and Versioning (WebDAV)]{@link
             * url="http://tools.ietf.org/html/rfc4918#section-9.11"}
             */
            UNLOCK = 15,
        }

        /**
         * is a factory to get {@link XAnyCompare} service implementations.
         * @since OOo 1.1.2
         */
        interface AnyCompareFactory extends XAnyCompareFactory {
            createWithLocale(aLocale: lang.Locale): void;
        }

        /**
         * An interaction continuation handing back some authentication data
         * @since LibreOffice 4.4
         */
        interface AuthenticationFallbackRequest extends task.ClassifiedInteractionRequest {
            /** Instructions to be followed by the user */
            instructions: string;

            /** url to be opened in browser */
            url: string;
        }

        /** An error specifying lack of correct authentication data (e.g., to log into an account). */
        interface AuthenticationRequest extends task.ClassifiedInteractionRequest {
            /**
             * Any already specified account.
             *
             * If HasAccount is false, this member should be ignored.
             */
            Account: string;

            /** Any diagnostic message about the failure to log in (if applicable; it will typically be an English phrase or sentence). */
            Diagnostic: string;

            /** Specifies if the authentication involves an "account" (as can be the case for FTP). */
            HasAccount: boolean;

            /** Specifies if the authentication involves a "password" (as is almost always the case). */
            HasPassword: boolean;

            /** Specifies if the authentication involves a "realm" (as can be the case for HTTP). */
            HasRealm: boolean;

            /** Specifies if the authentication involves a "user name" (as is almost always the case). */
            HasUserName: boolean;

            /**
             * Any already specified password.
             *
             * If HasPassword is false, this member should be ignored.
             */
            Password: string;

            /**
             * Any already specified realm.
             *
             * If HasRealm is false, this member should be ignored.
             */
            Realm: string;

            /** The name of the server (if applicable). */
            ServerName: string;

            /**
             * Any already specified user name.
             *
             * If HasUserName is false, this member should be ignored.
             */
            UserName: string;
        }

        /**
         * is used on client side to access a {@link ContentResultSet} remote optimized.
         *
         * The {@link CachedContentResultSet} will not load every single property or even row just in that moment you ask for it, but load the data for some rows
         * beforehand.
         *
         * Every time when a new package of data is loaded, the so far loaded data will be released, so the cash will not grow and grow and grow.
         */
        interface CachedContentResultSet extends ContentResultSet {
            /**
             * contains the direction for fetching rows from an underlying database.
             *
             * The value can be one of the {@link com.sun.star.sdbc.FetchDirection} constants group.
             *
             * The default value is implementation specific.
             *
             * If you set the value to {@link com.sun.star.sdbc.FetchDirection.UNKNOWN} an implementation specific direction will be used.
             */
            FetchDirection: number;

            /**
             * contains the number of result set rows that should be fetched from an underlying database.
             *
             * The default fetch size is implementation specific.
             *
             * Every negative value for parameter {@link FetchSize} will force an implementation specific value to be set.
             */
            FetchSize: number;
        }

        /** is used on provider side to access a {@link ContentResultSet} remote optimized. */
        interface CachedContentResultSetStub extends ContentResultSet, XFetchProvider, XFetchProviderForContentAccess {}

        /**
         * provides read access to a static or dynamically changing {@link ContentResultSet} .
         *
         * For example, a {@link DynamicResultSet} is returned from the open-command executed by an {@link XCommandProcessor} of the service {@link Content} .
         */
        interface CachedDynamicResultSet extends XDynamicResultSet, XSourceInitialization {}

        /**
         * provides read access to a static or dynamically changing {@link ContentResultSet} .
         *
         * For example, a {@link DynamicResultSet} is returned from the open-command executed by an {@link XCommandProcessor} of the service {@link Content} .
         */
        interface CachedDynamicResultSetStub extends XDynamicResultSet, XSourceInitialization {}

        /** An error specifying an invalid certificate. */
        interface CertificateValidationRequest extends task.ClassifiedInteractionRequest {
            /** The certificate itself. */
            Certificate: security.XCertificate;

            /** This value describes the validity of the certificate. */
            CertificateValidity: number;

            /** The host name. */
            HostName: string;
        }

        /**
         * contains information needed to checkin a document.
         *
         * The checkin command is always called on the target private working copy document.
         */
        interface CheckinArgument {
            /** Tells whether to create a new major or minor version during the checkin. */
            MajorVersion: boolean;

            /** contains the Mime-Type of the content to check-in as it may be different from the original one. */
            MimeType: string;

            /**
             * contains the title of the transferred object, if it is different from the original one.
             *
             * If this field is filled, for example, a file will be renamed while it is being checked in.
             */
            NewTitle: string;

            /** contains the URL of the source of the action (e.g. the URL of the temporary file to checkin). */
            SourceURL: string;

            /** contains the URL of the private working copy to checkin. */
            TargetURL: string;

            /** Contains the version comment to set during the checkin. */
            VersionComment: string;
        }

        /**
         * contains a command.
         * @see XCommandProcessor
         */
        interface Command {
            /** contains the argument of the command */
            Argument: any;

            /**
             * contains an implementation specific handle for the command.
             *
             * It must be `-1` if the implementation has no handle. `0` is a valid command handle.
             */
            Handle: number;

            /** contains the name of the command. */
            Name: string;
        }

        interface CommandEnvironment extends XCommandEnvironment {
            /**
             * Constructor.
             * @param InteractionHandler the interaction handler instance that will be returned by this service's implementation of XCommandEnvironemt::getInteractionH
             * @param ProgressHandler the progress handler instance that will be returned by this service's implementation of XCommandEnvironemt::getProgressHandler()
             */
            create(InteractionHandler: task.XInteractionHandler, ProgressHandler: XProgressHandler): void;
        }

        /**
         * This exception is thrown if an exception situation occurred during the processing of a command and an {@link com.sun.star.task.XInteractionHandler}
         * was able to handle the request for the error condition and the requesting code decided to abort the command execution according to the selection made
         * by the interaction handler.
         * @author Kai Sommerfeld
         * @see XCommandProcessor
         * @version 1.0
         */
        interface CommandFailedException extends uno.Exception {
            /** contains the exception that was passed to the {@link com.sun.star.task.XInteractionHandler} . */
            Reason: any;
        }

        /**
         * describes a command.
         * @see XCommandProcessor
         */
        interface CommandInfo {
            /** contains the type of the command's argument. */
            ArgType: type;

            /**
             * contains an implementation specific handle for the command.
             *
             * It may be `-1` if the implementation has no handle.
             */
            Handle: number;

            /** contains the name of a command. */
            Name: string;
        }

        /**
         * This event gets delivered whenever a {@link XCommandInfo} is changed.
         *
         * A {@link CommandInfoChangeEvent} object is sent to XCommandInfoChangeListeners.
         */
        interface CommandInfoChangeEvent extends lang.EventObject {
            /**
             * contains the implementation handle for the command.
             *
             * May be `-1` if the implementation has no handle.
             */
            Handle: number;

            /** contains the name of the command. */
            Name: string;

            /**
             * contains the reason for the event.
             *
             * The value can be one of the {@link CommandInfoChange} constants.
             */
            Reason: number;
        }

        /** A {@link Content} is a service that provides access to data of a content provided by an implementation of the service {@link ContentProvider} . */
        interface Content
            extends
                XContent,
                lang.XComponent,
                XCommandProcessor,
                XCommandProcessor2,
                beans.XPropertiesChangeNotifier,
                beans.XPropertyContainer,
                beans.XPropertySetInfoChangeNotifier,
                XCommandInfoChangeNotifier,
                XContentCreator,
                container.XChild
        {}

        /**
         * This exception is thrown to indicate that the creation of a UCB content failed.
         * @author Kai Sommerfeld
         * @version 1.0
         */
        interface ContentCreationException extends uno.Exception {
            /** An error code. */
            eError: ContentCreationError;
        }

        /** A structure for content events. */
        interface ContentEvent extends lang.EventObject {
            /**
             * The action.
             *
             * The value can be one of the {@link ContentAction} constants.
             */
            Action: number;

            /**
             * The content to that the action is related (e.g., the content that was just physically destroyed, the content that was just inserted into a folder
             * content).
             *
             * This member must be filled as follows:
             *
             * {{table here, see documentation}}
             */
            Content: XContent;

            /**
             * A content identifier, which must be filled according to the action notified (e.g., the id of the folder content into which another content was
             * inserted).
             *
             * This member must be filled as follows:
             *
             * {{table here, see documentation}}
             */
            Id: XContentIdentifier;
        }

        /**
         * A structure for information about contents.
         * @see XContentCreator
         * @see XCommandProcessor
         */
        interface ContentInfo {
            /**
             * Additional attributes.
             *
             * These flags contain extra information on the content, like its kind (KIND_FOLDER, KIND_DOCUMENT, KIND_LINK).
             *
             * It is highly recommended to fill these flags very accurately, as they are very important when transferring contents between different
             * ContentProviders.
             *
             * The value can be one of the {@link ContentInfoAttribute} constants.
             */
            Attributes: number;

            /**
             * This field contains a list with the properties which must be set at a content that was just created using {@link XContentCreator.createNewContent()}
             * before it can be committed (by executing the command "insert" at the new content).
             *
             * If one of the properties is missing, the insert command will fail.
             *
             * In example, a new file system folder content will need a title. The Properties member of the {@link ContentInfo} provided for this kind of content
             * must include the property "Title".
             *
             * **Important:** The required properties must have one of the following basic data types (in order to make it possible to implement client applications
             * with a small set of generic input methods for the values):
             *
             * booleancharbytestringshortlonghyperfloatdouble
             */
            Properties: SafeArray<beans.Property>;

            /**
             * A type identifier string for a content.
             *
             * This is an implementation specific string characterizing the kind of a content (e.g. "application/vnd.sun.star.hierarchy-link"). The value of this
             * member should match the value returned by {@link XContent.getContentType()} of an appropriate content.
             */
            Type: string;
        }

