        interface RemoteContentProviderChangeEvent extends lang.EventObject {
            /** An indicator whether a remote content provider has been added or removed. */
            Action: RemoteContentProviderChangeAction;

            /** The identifier with which the remote content provider is registered at the {@link com.sun.star.ucb.XRemoteContentProviderSupplier} . */
            Identifier: string;
        }

        /**
         * A {@link ContentProvider} that wraps remote content providers that (potentially) have been distributed to a UCB.
         *
         * Before trying to pass a request to a "real", underlying content provider (which will most likely be a remote content provider distributed to this
         * UCB), this proxy first activates any remote content providers that have been distributed here, but are still inactive (see {@link
         * RemoteContentProviderAcceptor} and {@link XRemoteContentProviderActivator} for more information).
         *
         * The way this works might change, therefore this interface is marked as deprecated.
         * @deprecated Deprecated
         */
        interface RemoteProxyContentProvider
            extends XContentProvider, XContentIdentifierFactory, XParameterizedContentProvider
        {}

        /**
         * describes a rule that can be applies to a number of objects.
         *
         * A rule consists of a sequence of RuleTerms describing the objects to which the rule should be applied, the {@link RuleAction} which should be used on
         * the matching objects, and a parameter.
         */
        interface Rule {
            /**
             * the action to perform on the matching objects.
             *
             * The value can be one of the {@link RuleAction} constants.
             */
            Action: number;

            /**
             * Some RuleActions require a parameter.
             *
             * {{table here, see documentation}}
             */
            Parameter: string;

            /** the rule terms describing the objects to which the rule should be applied. */
            Terms: SafeArray<RuleTerm>;
        }

        /**
         * describes a set of Rules.
         *
         * A {@link RuleSet} is applied to a folder. It consists of a sequence of rules. Each rule consists of a sequence of RuleTerms describing the objects to
         * which the rule should by applied and the {@link RuleAction} which should be performed on the matching objects.
         */
        interface RuleSet {
            /** is a flag indicating whether the rules apply to folders, too. */
            HandleFolder: boolean;

            /** contains a number of rules. */
            Rules: SafeArray<Rule>;
        }

        /**
         * describes a term.
         *
         * A term is used to select objects to which a rule should apply.
         */
        interface RuleTerm {
            /** this flag indicates whether a string "operand" shall be compared case sensitive. */
            CaseSensitive: boolean;

            /** the value of the property used to compare with the document property. */
            Operand: any;

            /**
             * the operator used to compare the property of the document with the given value (e.g. "contains" or "greater equal").
             *
             * The value can be one of the {@link RuleOperator} constants.
             */
            Operator: number;

            /** the name of the property used to match the term. */
            Property: string;

            /** this flag indicates whether a string "operand" shall be treated as a regular expression. */
            RegularExpression: boolean;
        }

        /**
         * The argument for the command "search".
         * @see XCommandProcessor
         */
        interface SearchCommandArgument {
            /** the search criteria. */
            Info: SearchInfo;

            /** the properties for which values shall be provided through the {@link ContentResultSet} returned by the search command. */
            Properties: SafeArray<beans.Property>;
        }

        /** a criterion describing how an object must match some rules that specify (part of) a search. */
        interface SearchCriterium {
            /** a number of rule terms. */
            Terms: SafeArray<RuleTerm>;
        }

        /** information needed to (recursively) search an object. */
        interface SearchInfo {
            /** the search criteria. */
            Criteria: SafeArray<SearchCriterium>;

            /** whether to follow indirections (link objects) and search through their respective targets also. */
            FollowIndirections: boolean;

            /** whether to include the object itself in the search or only (some of) its sub-objects. */
            IncludeBase: boolean;

            /** the mode of recursion to use. */
            Recursion: SearchRecursion;

            /**
             * whether to respect the "view restrictions" specified for the documents hierarchically contained within an object (e.g., only searches through marked
             * documents).
             */
            RespectDocViewRestrictions: boolean;

            /**
             * whether to respect the "view restrictions" specified for the folders hierarchically contained within an object (e.g., only searches through subscribed
             * folders).
             */
            RespectFolderViewRestrictions: boolean;
        }

        /**
         * contains information related to a send protocol.
         *
         * It can contain any string values (server names, user names, passwords, ...).
         */
        interface SendInfo {
            /** the protocol to which the info is related (i.e. "NNTP", "SMTP", "VIM"). */
            ProtocolType: string;

            /** the value. */
            Value: string;
        }

        /** contains a list of Internet media types (like "text/plain" and "text/html"), that are related to a send protocol. */
        interface SendMediaTypes {
            /** the protocol to which the information is related (i.e. "NNTP", "SMTP", "VIM"). */
            ProtocolType: string;

            /** a list of Internet media types */
            Value: SafeArray<string>;
        }

        /** contains a sorting info. */
        interface SortingInfo {
            /** contains a flag indicating the sort mode (ascending or descending). */
            Ascending: boolean;

            /** specifies the name of a property to use for sorting ( e.g. "Title" ). */
            PropertyName: string;
        }

        /**
         * contains information needed to transfer objects from one location to another.
         *
         * The transfer command is always called on the target folder. For a details description of the transfer command refer to the documentation of service
         * {@link Content} .
         */
        interface TransferInfo {
            /** contains the flags describing whether the data shall be moved instead of copied. */
            MoveData: boolean;

            /**
             * describes how to act in case of title clashes while transferring the data.
             *
             * A title clash for instance occurs, if a file named "foo.txt" is to be transferred to a folder already containing another file named "foo.txt".
             *
             * The value can be one of the {@link NameClash} constants.
             *
             * Implementations that are not able to detect whether there is a clashing resource may ignore {@link NameClash.ERROR} and {@link NameClash.RENAME}
             * always write the new data.
             */
            NameClash: number;

            /**
             * contains the title of the transferred object, if it is different from the original one.
             *
             * If this field is filled, for example, a file will be renamed while it is being transferred.
             */
            NewTitle: string;

            /** contains the URL of the source of the action (e.g. the URL of a file to move). */
            SourceURL: string;
        }

        /** extends {@link TransferInfo} structure to give some additional parameters for transfers. */
        interface TransferInfo2 extends TransferInfo {
            /** contains the MIME type of the source of the action */
            MimeType: string;
        }

        /** Information about a transfer activity. */
        interface TransferResult {
            /** Either void if the transfer has been carried out successfully, or an exception indicating the kind of failure. */
            Result: any;

            /** The URL of the source object. */
            Source: string;

            /** The URL of the target folder into which to transfer (a copy of) the source object. */
            Target: string;
        }

