        /** describes what and how to search within a container. */
        interface SearchDescriptor extends XSearchDescriptor, beans.XPropertySet {
            /** If `TRUE` , the search is done backwards in the document. */
            SearchBackwards: boolean;

            /** If `TRUE` , the case of the letters is important for the match. */
            SearchCaseSensitive: boolean;

            /**
             * If `TRUE` , the search string is evaluated as a regular expression.
             *
             * SearchRegularExpression, SearchWildcard and SearchSimilarity are mutually exclusive, only one can be `TRUE` at the same time.
             */
            SearchRegularExpression: boolean;

            /**
             * If `TRUE` , a "similarity search" is performed.
             *
             * In the case of a similarity search, the following properties specify the kind of similarity:
             *
             * SearchSimilarityRelaxSearchSimilarityRemoveSearchSimilarityAddSearchSimilarityExchange
             *
             * SearchRegularExpression, SearchWildcard and SearchSimilarity are mutually exclusive, only one can be `TRUE` at the same time.
             */
            SearchSimilarity: boolean;

            /** specifies the number of characters that must be added to match the search pattern. */
            SearchSimilarityAdd: number;

            /** This property specifies the number of characters that must be replaced to match the search pattern. */
            SearchSimilarityExchange: number;

            /**
             * If `TRUE` , all similarity rules are applied together.
             *
             * In the case of a relaxed similarity search, the following properties are applied together:
             *
             * SearchSimilarityRemoveSearchSimilarityAddSearchSimilarityExchange
             */
            SearchSimilarityRelax: boolean;

            /** This property specifies the number of characters that may be ignored to match the search pattern. */
            SearchSimilarityRemove: number;

            /** If `TRUE` , it is searched for positions where the paragraph style with the name of the search pattern is applied. */
            SearchStyles: boolean;

            /**
             * If `TRUE` , the search string is evaluated as a wildcard pattern.
             *
             * Wildcards are '*' (asterisk) for any sequence of characters, including an empty sequence, and '?' (question mark) for exactly one character. Escape
             * character is '\' (U+005C REVERSE SOLIDUS) aka backslash, it escapes the special meaning of a question mark, asterisk or escape character that follows
             * immediately after the escape character.
             *
             * SearchRegularExpression, SearchWildcard and SearchSimilarity are mutually exclusive, only one can be `TRUE` at the same time.
             * @since LibreOffice 5.2
             */
            SearchWildcard: boolean;

            /** If `TRUE` , only complete words will be found. */
            SearchWords: boolean;
        }

        interface SearchOptions {
            /** search type */
            algorithmType: SearchAlgorithms;

            /** This many characters can be different (as a replacement) between the found word and the search pattern in a "Weighted Levenshtein; Distance" search. */
            changedChars: number;

            /** This many characters can be missing in the found word in a "Weighted Levenshtein Distance" search. */
            deletedChars: number;

            /** This many characters can be additional in the found word in a "Weighted Levenshtein Distance" search. */
            insertedChars: number;

            /** The locale for case insensitive search. */
            Locale: lang.Locale;

            /** The replacement text (is for optional replacing - SearchOption is only the data container for it) */
            replaceString: string;

            /**
             * some flags - can be mixed
             * @see SearchFlags
             */
            searchFlag: number;

            /** The text or pattern to be searched. */
            searchString: string;

            /** Flags for the transliteration. Same meaning as the enum of {@link com.sun.star.i18n.TransliterationModules} */
            transliterateFlags: number;
        }

        /**
         * This augments {@link com.sun.star.util.SearchOptions} to be able to specify additional search algorithms for use with {@link
         * com.sun.star.util.XTextSearch2}
         * @since LibreOffice 5.2
         */
        interface SearchOptions2 extends SearchOptions {
            /**
             * Search type, one of {@link com.sun.star.util.SearchAlgorithms2} constants. This is preferred over the content of the SearchAlgorithms {@link
             * SearchOptions.algorithmType} enum field.
             */
            AlgorithmType2: number;

            /**
             * The escape character to be used with a {@link com.sun.star.util.SearchAlgorithms2.WILDCARD} search.
             *
             * A Unicode character, if not 0 escapes the special meaning of a question mark, asterisk or escape character that follows immediately after the escape
             * character. If 0 defines no escape character is used.
             *
             * Common values are '\' (U+005C REVERSE SOLIDUS) aka backslash in text processing context, or '~' (U+007E TILDE) in spreadsheet processing context.
             */
            WildcardEscapeCharacter: number;
        }

        interface SearchResult {
            endOffset: SafeArray<number>;
            startOffset: SafeArray<number>;

            /**
             * Number of subexpressions.
             *
             * If it is 0, then no match found; this value is 1 for ABSOLUTE and APPROXIMATE match. The start and endOffset are always dependent on the search
             * direction.
             *
             * For example, if you search "X" in the text "-X-" the offsets are: for forward:    start = 1, end = 2
             *
             * for backward:   start = 2, end = 1
             *
             * Forward, the startOffset is inclusive, the endOffset exclusive. Backward, the startOffset is exclusive, the endOffset inclusive.
             *
             * For regular expressions it can be greater than 1. If the value is 1, startoffset[0] and endoffset[0] points to the matching sub string if value is >
             * 1, still startoffset[0] and endoffset[0] points to the matching substring for whole regular expression startoffset[i] and endoffset[i] points to the
             * matching substring of i th matching substring.
             */
            subRegExpressions: number;
        }

        /**
         * specifies the properties which can be used to describe a sort order applied to an {@link XSortable} .
         * @deprecated Deprecated
         * @see XSortable
         */
        interface SortDescriptor extends beans.XPropertySet {
            /**
             * specifies the algorithm for the compare operator (collator).
             *
             * The collator algorithm may be defined for separate keys in specific implementations. For those this property may not need to be set.
             * @see com.sun.star.text.TextSortDescriptor
             * @see com.sun.star.i18n.XCollator
             */
            CollatorAlgorithm: string;

            /** specifies the locale for the compare operator (collator). */
            CollatorLocale: lang.Locale;

            /** specifies if the case of letters is important when comparing entries. */
            IsCaseSensitive: boolean;

            /**
             * specifies the sorting order.
             *
             * The sorting order may be defined for separate keys in specific implementations. For those this property may not need to be set.
             * @see com.sun.star.text.TextSortDescriptor
             */
            SortAscending: boolean;

            /**
             * specifies if the columns are sorted.
             *
             * **TRUE**: The columns are sorted.;
             *
             * **FALSE**: The rows are sorted.
             */
            SortColumns: boolean;
        }

        /**
         * describes a single field in a sort descriptor.
         * @deprecated Deprecated
         */
        interface SortField {
            /** index of the field in the table; 0-based. */
            Field: number;

            /** type of contents in the field. */
            FieldType: SortFieldType;

            /** `TRUE` if data are sorted in ascending order, `FALSE` if in descending order. */
            SortAscending: boolean;
        }

        /** represents a time value. */
        interface Time {
            /** contains the hour (0-23). */
            Hours: number;

            /**
             * true: time zone is UTC false: unknown time zone.
             * @since LibreOffice 4.1
             */
            IsUTC: boolean;

            /** contains the minutes (0-59). */
            Minutes: number;

            /** contains the nanoseconds (0 - 999 999 999). */
            NanoSeconds: number;

            /** contains the seconds (0-59). */
            Seconds: number;
        }

        /**
         * represents a combined time value with time zone.
         * @since LibreOffice 4.1
         */
        interface TimeWithTimezone {
            /** the time (in TimeZone) */
            TimeInTZ: Time;

            /**
             * contains the time zone, as signed offset in minutes **from** UTC, that is **east** of UTC, that is the amount of minutes that should be added to UTC
             * time to obtain the time in that timezone.
             *
             * To obtain UTC time from TimeInTZ, you need to **subtract** TimeZone minutes.
             */
            Timezone: number;
        }

        /**
         * represents the structure of an Uniform Resource Locator.
         *
         * If the structure represents a valid {@link URL} or not depends on prior usage of the functions of {@link XURLTransformer} . Only after one of the
         * functions returned `TRUE` this can be assumed. ;  It is not necessary to set all of the fields; either {@link URL.Complete} or (some of) the others
         * are set. Additionally, most of the other fields, like URL::Host, {@link URL.Port} , {@link URL.User} , {@link URL.Password} , or {@link URL.Mark} ,
         * are optional.
         * @see XURLTransformer
         */
        interface URL {
            /** contains the arguments part of the {@link URL} , for example, "a=b" */
            Arguments: string;

            /**
             * contains the string representation of the complete {@link URL} , for example, [http://www.sun.de:8080/pub/test/foo.txt?a=b#xyz]{@link
             * url="http://www.sun.de:8080/pub/test/foo.txt?a=b#xyz"}
             *
             * It is used as a central input/output or input parameter for the interfaces of {@link XURLTransformer} . The usage of one of the {@link
             * XURLTransformer} function is mandatory to validate the {@link URL} . It cannot be assumed that {@link URL.Complete} represents always a valid URL!
             */
            Complete: string;

            /**
             * contains the {@link URL} without a mark and without arguments, for example, [http://www.sun.de:8080/pub/test/foo.txt]{@link
             * url="http://www.sun.de:8080/pub/test/foo.txt"}
             */
            Main: string;

            /** contains the mark part of the {@link URL} , for example, "xyz" */
            Mark: string;

            /**
             * contains the last segment of the hierarchical path of the {@link URL} , for the above example, "foo.txt"
             *
             * **Attention:** A service implementing the {@link XURLTransformer} interface will normally not detect if the last segment is a folder or a file. So it
             * is possible that the last segment describes a folder. If you want to be sure that a file {@link URL} that references a folder will be correctly put
             * into the {@link URL} fields you should append a "/" at the end of the hierarchical path.
             */
            Name: string;

            /** contains the users password of the {@link URL} , for example, "pass" */
            Password: string;

            /** contains all segments but the last one of the hierarchical path of the {@link URL} , for example, "/pub/test/" */
            Path: string;

            /** contains the port at the server of the {@link URL} , for example, "8080" */
            Port: number;

            /** contains the protocol (scheme) of the {@link URL} , for example, "http" */
            Protocol: string;

            /** contains the server part of the {@link URL} , for example, "www.sun.de" */
            Server: string;

            /** contains the user-identifier of the {@link URL} , for example, "me" */
            User: string;
        }

        /**
         * allows estimating the memory usage of a service.
         * @since LibreOffice 5.3
         */
        interface XAccounting extends uno.XInterface {
            /** @returns an estimate of the current memory usage, in octets. */
            estimateUsage(): number;
        }

        /**
         * an interface to map between **string** s and **id** s
         *
         * a note on atoms: ;  Atoms are abbreviations for strings. When a string gets registered, it is assigned a numeric id so that said string can always be
         * referred to by this id. This way strings have to be transported only once over remote connections. Valid ids are (in this implementation) non zero,
         * signed 32 bit values. An atom of 0 means that the string in question is not registered
         *
         * Additionally there is the abstraction of atom class: ;  Atoms are grouped into classes, so that an id can be assigned to multiple strings, depending
         * on the class context. The main advantage of this is that atoms in one class may be kept to small numbers, so that bandwidth can be reduced by sending
         * the atoms only as 16 bit values. Note that it is up to the user in this case to handle overflows.
         */
        interface XAtomServer extends uno.XInterface {
            /**
             * registers or searches for a string
             * @param atomClass the class of atoms in question
             * @param description the string in question
             * @param create if true a new atom will be created for an unknown string else the invalid atom (0) will be returned for an unknown string
             * @returns the atom for the string `description`
             */
            getAtom(atomClass: number, description: string, create: boolean): number;

            /**
             * returns the strings for an arbitrary amount of atoms of multiple classes
             * @param atoms describes which strings to return
             * @returns the strings for the requested atoms
             */
            getAtomDescriptions(atoms: LibreOffice.SeqEquiv<AtomClassRequest>): SafeArray<string>;

            /**
             * returns a whole atom class
             * @param atomClass which class to return
             * @returns the descriptions for all atoms of class `atomClass`
             */
            getClass(atomClass: number): SafeArray<AtomDescription>;

            /**
             * returns multiple atom classes
             * @param atomClasses which classes to return
             * @returns the descriptions for all atoms of the requested classes
             */
            getClasses(atomClasses: LibreOffice.SeqEquiv<number>): SafeArray<SafeArray<AtomDescription>>;

            /**
             * returns the atoms that have been registered to a class after an already known atom
             *
             * Hint to implementor: using ascending atoms is the easiest way to decide, which atoms are recent.
             * @param atomClass the class in question
             * @param atom the last known atom
             * @returns all atom description that have been added to class `atomClass` after `atom`
             */
            getRecentAtoms(atomClass: number, atom: number): SafeArray<AtomDescription>;
        }

        /**
         * allows to control notification behavior of a broadcaster.
         * @since OOo 3.0
         */
        interface XBroadcaster extends uno.XInterface {
            /**
             * suspends broadcasts to the registered listeners.
             *
             * The calls to {@link XBroadcaster.lockBroadcasts()} and {@link XBroadcaster.unlockBroadcasts()} may be nested and even overlapping, but they must be in
             * pairs. While there is at least one lock remaining, no broadcasts are sent to registered listeners.
             */
            lockBroadcasts(): void;

            /**
             * resumes the broadcasts which were suspended by {@link XBroadcaster.lockBroadcasts()} .
             *
             * The calls to {@link XBroadcaster.lockBroadcasts()} and {@link XBroadcaster.unlockBroadcasts()} may be nested and even overlapping, but they must be in
             * pairs. While there is at least one lock remaining, no broadcasts are sent to registered listeners.
             *
             * Pending broadcasts will be sent immediately after the last call to {@link XBroadcaster.lockBroadcasts()} is matched by a call to {@link
             * XBroadcaster.unlockBroadcasts()} . An implementation can decide to broadcast all pending notification in order or batch them in single broadcasts.
             */
            unlockBroadcasts(): void;
        }

        /**
         * offers the possibility of canceling a job.
         *
         * This is supported by objects which represent a job.
         */
        interface XCancellable extends uno.XInterface {
            /** cancels the current job of the object. */
            cancel(): void;
        }

        /** enables the object to be a member of a chain. */
        interface XChainable extends uno.XInterface {
            /** @returns the previous object in this chain or NULL, if this is the first object of this chain. */
            getPredecessor(): XChainable;

            /** @returns the next object in this chain or NULL, if this is the last object in this chain. */
            getSuccessor(): XChainable;

            /** checks if the specified object can be linked to this. */
            isChainable(xChainable: XChainable): boolean;

            /** @returns the previous object in this chain or NULL, if this is the first object of this chain. */
            readonly Predecessor: XChainable;

            /**
             * connects the specified object to this object as the successor in a chain.
             *
             * This implies that this object will become the predecessor of **xChainable** .
             */
            setSuccessor(xChainable: XChainable): void;

            /** @returns the next object in this chain or NULL, if this is the last object in this chain. */
            Successor: XChainable;
        }

        /**
         * this interface enables applying a set of changes in one batch transaction.
         *
         * An object implementing this interface allows other interfaces to change its state locally. It will keep a list of pending changes until such changes
         * are committed or canceled.
         *
         * Only when they are explicitly committed will these changes take effect persistently or globally.
         * @see XChangesNotifier
         * @see XChangesSet
         * @see XCancellable
         */
        interface XChangesBatch extends uno.XInterface {
            /**
             * commits any pending changes.
             *
             * The exact action depends on the concrete service.
             */
            commitChanges(): void;

            /** queries for any pending changes that can be committed. */
            getPendingChanges(): ChangesSet;

            /** checks whether this object has any pending changes that can be committed. */
            hasPendingChanges(): boolean;

            /** queries for any pending changes that can be committed. */
            readonly PendingChanges: ChangesSet;
        }

        /**
         * receives events from batch change broadcaster objects.
         * @see ChangesEvent
         * @see XChangesNotifier
         * @see XChangesBatch
         */
        interface XChangesListener extends lang.XEventListener {
            /** is invoked when a batch of changes occurred. */
            changesOccurred(Event: ChangesEvent): void;
        }

        /**
         * broadcasts events about multiple changes that occur in bulk.
         * @see XChangesListener
         * @see XChangesBatch
         * @see ChangesEvent
         */
        interface XChangesNotifier extends uno.XInterface {
            /** adds the specified listener to receive events when changes occurred. */
            addChangesListener(aListener: XChangesListener): void;

            /** removes the specified listener. */
            removeChangesListener(aListener: XChangesListener): void;
        }

        /**
         * this interface enables inspecting a set of changes forming one batch transaction.
         *
         * An object implementing this interface should implement more container interfaces to access individual changes as well.
         * @see XChangesBatch
         * @see ChangesEvent
         * @see XChangesListener
         * @see XChangesNotifier
         */
        interface XChangesSet extends container.XElementAccess {
            /**
             * queries for all contained changes at once.
             * @returns an array of {@link ElementChange} holding information about each changes that is part of this object.
             */
            readonly AllChanges: SafeArray<ElementChange>;

            /**
             * queries for all contained changes at once.
             * @returns an array of {@link ElementChange} holding information about each changes that is part of this object.
             */
            getAllChanges(): SafeArray<ElementChange>;
        }

        /** makes it possible to create a copy of the object which supports this interface. */
        interface XCloneable extends uno.XInterface {
            /** creates a copy of the object. */
            createClone(): XCloneable;
        }

        /**
         * makes it possible to release any objects in a ordered manner by using a two-step mechanism
         *
         * If an object should be terminated, it can be: ; disposed (if it supports {@link com.sun.star.lang.XComponent.dispose()} )closed (if it supports {@link
         * XCloseable.close()} ) First version gives the object no chance to disagree with that (e.g. if a process is still running and can't be canceled
         * really). Last version provides this possibility, but can't guarantee real termination of called object. It depends from the environment of an object,
         * if one or both mechanism are necessary.
         *
         * Base interface {@link XCloseBroadcaster} makes it possible that any listener which is interested on life time of listened object ... can get a
         * notification about closing of itor can have a veto to break that.
         * @see com.sun.star.lang.XComponent.dispose()
         * @see XCloseBroadcaster
         * @see XCloseListener
         */
        interface XCloseable extends XCloseBroadcaster {
            /**
             * try to close the object
             *
             * Must definitely be called before {@link com.sun.star.lang.XComponent.dispose()} . But nobody can guarantee real closing of called object - because it
             * can disagree with that if any still running processes can't be canceled yet. It's not allowed to block this call till internal operations will be
             * finished here. They must be canceled or call must return immediately by throwing the {@link CloseVetoException} . Otherwise (if nothing exist to
             * disagree) it must return normally.
             *
             * Before any internal processes will be canceled, all registered {@link XCloseListener} must be notified. Any of them can disagree with a {@link
             * CloseVetoException} too. It's forbidden to catch this exception inside the called {@link close()} method because the caller must get this information!
             *
             * If somewhere disagree with a {@link CloseVetoException} it will not clear who has to close the object again after still running processes was
             * finished. The parameter **DeliverOwnership** regulate that. If it is set to `FALSE` the caller of the method {@link close()} will be the owner of this
             * object in every case. Then it's not allowed to call {@link close()} from any other place (may a registered {@link XCloseListener} ). If it is set to
             * `TRUE` the caller gives up its ownership. If a {@link XCloseListener} throw the veto exception it will be the new owner of the closing object. This
             * information is passed to the listener by a parameter of its notification method {@link XCloseListener.queryClosing()} . After its operations was
             * finished it MUST try to close it again. If the closing object itself disagree by an exception and the parameter **DeliverOwnership** was set to `TRUE`
             * the object will be its own owner with all consequences of that. ; **Note:**;  There is no way to get the ownership back if it was delivered!
             *
             * If this method was already called on an object it should return without any reaction. Normally it's possible to throw a {@link
             * com.sun.star.lang.DisposedException} for already disposed or closed objects (which represent a {@link com.sun.star.uno.RuntimeException} and can be
             * thrown by every interface call), but it shouldn't be used here. The veto exception should be the only way to indicates the result.
             * @param DeliverOwnership `TRUE` delegates the ownership of this closing object to any one which throw the {@link CloseVetoException} . This new owner has
             * @see XCloseListener
             * @see CloseVetoException
             * @see com.sun.star.lang.XComponent.dispose()
             * @see com.sun.star.lang.DisposedException
             * @throws CloseVetoException indicates that the closing object itself or any of its currently registered listeners disagree with this {@link close()} request.
             */
            close(DeliverOwnership: boolean): void;
        }

        /**
         * broadcasts each tried closing of an object to all interest listener
         *
         * The called object for closing must post the closing events immediately and before any internal cancel operations will be started. If a listener
         * disagree with that it should throw a {@link CloseVetoException} and called function {@link XCloseable.close()} must be broken immediately. It's not
         * allowed to catch it inside the close() request. If no listener nor internal processes hinder the object on closing all listeners get a notification
         * about real closing.
         * @see
         */
        interface XCloseBroadcaster extends uno.XInterface {
            /**
             * adds the specified listener to receive or have a veto for "close" events
             * @param Listener the listener which is interest on closing events
             */
            addCloseListener(Listener: XCloseListener): void;

            /**
             * removes the specified listener
             * @param Listener the listener which isn't interest on closing events any longer
             */
            removeCloseListener(Listener: XCloseListener): void;
        }

        /**
         * makes it possible to receive events when an object is called for closing
         *
         * Such close events are broadcasted by a {@link XCloseBroadcaster} if somewhere tries to close it by calling {@link XCloseable.close()} . Listener can:
         * break that by throwing {@link CloseVetoException}or accept that by deregistering itself at this broadcaster.
         *
         * If an event {@link com.sun.star.lang.XEventListener.disposing()} occurred, nobody called {@link XCloseable.close()} on listened object before. Then
         * it's not allowed to break this request - it must be accepted!
         * @see XCloseable
         * @see XCloseBroadcaster
         */
        interface XCloseListener extends lang.XEventListener {
            /**
             * is called when the listened object is closed really
             *
             * Now the listened object is closed really. Listener has to accept that; should deregister itself and release all references to it. It's not allowed
             * nor possible to disagree with that by throwing any exception.
             *
             * If the event {@link com.sun.star.lang.XEventListener.disposing()} occurred before it must be accepted too. There exist no chance for a disagreement
             * any more.
             * @param Source describes the source of the event (must be the listened object)
             */
            notifyClosing(Source: lang.EventObject): void;

            /**
             * is called when somewhere tries to close listened object
             *
             * Is called before {@link XCloseListener.notifyClosing()} . Listener has the chance to break that by throwing a {@link CloseVetoException} . This
             * exception must be passed to the original caller of {@link XCloseable.close()} without any interaction.
             *
             * The parameter **GetsOwnership** regulate who has to try to close the listened object again, if this listener disagree with the request by throwing the
             * exception. If it's set to `FALSE` the original caller of {@link XCloseable.close()} will be the owner in every case. It's not allowed to call close()
             * from this listener then. If it's set to `TRUE` this listener will be the new owner if it throw the exception, otherwise not! If it has still running
             * processes will be finished it must call close() on listened object again then.
             *
             * If this listener doesn't disagree with the close request it depends on its internal implementation if it deregisters itself from the listened object.
             * But normally this must be done in {@link XCloseListener.notifyClosing()} .
             * @param Source describes the source of the event (must be the listened object)
             * @param GetsOwnership `TRUE` pass the ownership to this listener, if it throw the veto exception (otherwise this parameter must be ignored!) ; `FALSE` fo
             * @throws CloseVetoException if listener disagree with the close request on listened object it must throw this exception
             */
            queryClosing(Source: lang.EventObject, GetsOwnership: boolean): void;
        }

        /** connects to a model and broadcasts status change events. */
