        /** is the interface for binding programmatic names to aliases. Aliases can be provided in several locales for the same programmatic name. */
        interface XLocalizedAliases extends uno.XInterface {
            /** registers an alias for a programmatic name. */
            bindAlias(programmaticName: string, locale: lang.Locale, alias: string): void;

            /**
             * retrieves a list of all registered aliases for a certain language.
             * @param locale specifies the locale scope.
             * @returns a sequence of registered pair of alias and programmatic name.
             */
            listAliases(locale: lang.Locale): SafeArray<AliasProgrammaticPair>;

            /** retrieves a registered programmatic name identified by an alias. */
            lookupAlias(locale: lang.Locale, Alias: string): string;

            /** retrieves a given alias for a programmatic name. */
            lookupProgrammatic(locale: lang.Locale, programmatic: string): string;

            /** rebinds all aliases registered to a given {@link URL} to a new one. */
            rebindAliases(currentProgrammatic: string, newProgrammatic: string): void;

            /** renames an alias for a programmatic name. */
            renameAlias(locale: lang.Locale, oldName: string, aNewName: string): void;

            /** revokes an alias for a programmatic name. */
            unbindAlias(locale: lang.Locale, alias: string): void;

            /** removes all aliases for a programmatic name. */
            unbindAliases(programmaticName: string): void;
        }

        /**
         * allows locking a component
         *
         * `lock` and `unlock` calls can be nested. However, they must be in pairs. As long as there has been one more call to `lock` than to `unlock` , the
         * component is considered locked, which is reflected by {@link isLocked()} returning `TRUE` .
         */
        interface XLockable {
            /**
             * determines whether the component is currently locked.
             * @see lock
             * @see unlock
             */
            isLocked(): boolean;

            /**
             * locks the component
             * @see unlock
             * @see isLocked
             */
            lock(): void;

            /**
             * unlocks the component
             * @see lock
             * @see isLocked
             * @throws NotLockedException if the component is not currently locked.
             */
            unlock(): void;
        }

        /**
         * Expands macro in expressions, i.e. substitudes macro names.
         * @since OOo 1.1.2
         */
        interface XMacroExpander extends uno.XInterface {
            /**
             * Expands macrofied expressions.
             * @param exp macrofied expression
             * @returns demacrofied expression
             * @throws IllegalArgumentException if a macro name is unknown, thus cannot be expanded
             */
            expandMacros(exp: string): string;
        }

        /** represents a range of cells that can be merged. */
