        /**
         * encapsulates access to the current office installation directory and office user data directory, provides functionality to create URLs containing
         * relocatable (not absolute) references to the current office installation directory and user data directory and vice versa.
         *
         * This functionality is useful when data containing references to the current office installation directory must be made persistent and re-read later.
         * In many cases, storing the reference directly would destroy the relocatability of an office installation.
         * @since OOo 2.0
         */
        interface XOfficeInstallationDirectories extends uno.XInterface {
            /**
             * returns the absolute {@link URL} containing the directory of the current office installation (for example "file:///opt/LibreOffice")
             * @returns the absolute {@link URL} containing the directory of the current office installation.
             */
            getOfficeInstallationDirectoryURL(): string;

            /**
             * returns the absolute {@link URL} containing the directory where the current office installation expects its user data (for example
             * "file:///home/kso/.config/libreoffice/4")
             * @returns the absolute {@link URL} containing the directory of the current office user data.
             */
            getOfficeUserDataDirectoryURL(): string;

            /**
             * the counterpart of `makeRelocatableURL` .
             *
             * If the given {@link URL} contains a placeholder for an absolute reference to the current office installation directory or for the office user data
             * directory, that was created using `makeRelocatableURL` , the respective placeholder will be replaced by an absolute reference to the current office
             * installation directory or office user data directory.
             * @param URL The {@link URL} for that an absolute {@link URL} is requested. In case the {@link URL} does not contain the opaque relocation placeholder use
             * @returns The absolute {@link URL} .
             */
            makeAbsoluteURL(URL: string): string;

            /**
             * calculates a relocatable {@link URL} from the given {@link URL} .
             *
             * If the given {@link URL} contains an absolute reference to the current office installation directory or office user data directory, this method will
             * replace the absolute reference by an opaque placeholder string. `makeRelocatableURL` must be used in order to re-replace the placeholder by an
             * absolute reference.
             * @param URL The {@link URL} for that a relocatable {@link URL} is requested. In case the {@link URL} does not contain a reference to the current office i
             * @returns The relocatable {@link URL} .
             */
            makeRelocatableURL(URL: string): string;

            /**
             * returns the absolute {@link URL} containing the directory of the current office installation (for example "file:///opt/LibreOffice")
             * @returns the absolute {@link URL} containing the directory of the current office installation.
             */
            readonly OfficeInstallationDirectoryURL: string;

            /**
             * returns the absolute {@link URL} containing the directory where the current office installation expects its user data (for example
             * "file:///home/kso/.config/libreoffice/4")
             * @returns the absolute {@link URL} containing the directory of the current office user data.
             */
            readonly OfficeUserDataDirectoryURL: string;
        }

        /** @since LibreOffice 4.1 */
        interface XPathSettings extends beans.XPropertySet {
            /** Specifies the directory that contains spreadsheet add-ins which use the old add-in API */
            Addin: string;

            /** The settings of the AutoCorrect dialog. The value can be more than one path separated by a semicolon. */
            AutoCorrect: string;

            /** The directory which contains the AutoText modules. The value can be more than one path separated by a semicolon. */
            AutoText: string;

            /** Automatic backup copies of documents are stored here. */
            Backup: string;
            BasePathShareLayer: string;
            BasePathUserLayer: string;

            /** The Basic files, used by the AutoPilots, can be found here. The value can be more than one path separated by a semicolon. */
            Basic: string;

            /** This directory contains the icons for the toolbars. */
            Bitmap: string;

            /** The configuration files are located here. This entry cannot be changed by the user in Office user interface. */
            Config: string;

            /** The provided dictionaries are stored here. */
            Dictionary: string;

            /** Path to save folder bookmarks */
            Favorite: string;

            /** Specifies the directory where all the filters are stored. */
            Filter: string;

            /** Specifies the directories which contains the Gallery database and multimedia files. The value can be more than one path separated by a semicolon. */
            Gallery: string;

            /** This directory is displayed when the dialog for opening a graphic or for saving a new graphic is called. */
            Graphic: string;

            /** The path to the Office help files. */
            Help: string;

            /** The files that are necessary for the spell check are saved here. */
            Linguistic: string;

            /** This is the path for the modules. */
            Module: string;

            /**
             * This is the path to the palette files *.SOB to *.SOF containing user-defined colors and patterns. The value can be more than one path separated by a
             * semicolon.
             */
            Palette: string;

            /** Plugins are saved in these directories. The value can be more than one path separated by a semicolon. */
            Plugin: string;

            /** Mail, News files and other information (for example, about FTP Server) are stored here. */
            Storage: string;

            /** The base url to the office temp-files */
            Temp: string;

            /** The templates originate from these folders and sub-folders. The value can be more than one path separated by a semicolon. */
            Template: string;

            /**
             * Global directories to look for user interface configuration files. The user interface configuration will be merged with user settings stored in the
             * directory specified by **UserConfig** . The value can be more than one path separated by a semicolon.
             */
            UIConfig: string;

            /** Specifies the folder with the user settings. */
            UserConfig: string;

            /**
             * The custom dictionaries are contained here.
             * @deprecated Deprecated
             */
            UserDictionary: string;

            /** The path of the work folder can be modified according to the user's needs. The path specified here can be seen in the Open or Save dialog. */
            Work: string;
        }

        /** makes it possible to search and replace properties. */
