                    click = 3,
                    DOMActivate = 2,
                    DOMAttrModified = 14,
                    DOMCharacterDataModified = 15,
                    DOMFocusIn = 0,
                    DOMFocusOut = 1,
                    DOMNodeInserted = 10,
                    DOMNodeInsertedIntoDocument = 13,
                    DOMNodeRemoved = 11,
                    DOMNodeRemovedFromDocument = 12,
                    DOMSubtreeModified = 9,
